function erpNormalizeAllowedModes(raw) {
    if (!raw) return [];
    if (Array.isArray(raw)) return raw.map(String);
    if (typeof raw === 'string') {
        try {
            const j = JSON.parse(raw);
            return Array.isArray(j) ? j.map(String) : [];
        } catch (e) { return []; }
    }
    return [];
}

/**
 * Bir modun verilen yetki listesiyle açılıp açılmadığını söyler.
 * Hem oturumdaki kullanıcı (erpUserCan) hem de yönetim ekranındaki önizleme
 * aynı fonksiyonu kullanır; böylece işaretli kutular ile gerçek erişim ayrışmaz.
 */
function erpModeAcikMi(mode, modes, isAdmin) {
    if (mode === 'KULLANICI_YONETIMI' || mode === 'GUNLUK_ISLEMLER') return !!isAdmin;
    if (isAdmin) return true;
    // Mobilin iç ekran adı YIKAMA_TAKIP; yetki kodu iki platformda da KONFEKSIYON_YIKAMA
    if (mode === 'YIKAMA_TAKIP') mode = 'KONFEKSIYON_YIKAMA';
    if (mode === 'DASHBOARD') return true;
    if (mode === 'DEPO_HAREKET' || mode === 'DEPO_HAREKET_LISTE' || mode === 'MUHASEBE_FIS' || mode === 'STOK_SAYIM') {
        return modes.includes('DEPO_HAREKET') || modes.includes('DEPO_HAREKET_LISTE') || modes.includes('MUHASEBE_FIS')
            || modes.includes('STOK_SAYIM')
            || modes.includes('IPLIK') || modes.includes('KUMAS') || modes.includes('MAMUL_DEPO');
    }
    if (mode === 'KART_LISTE' || mode === 'IPLIK_KART_GIRIS' || mode === 'KUMAS_KART_GIRIS' || mode === 'MAMUL_KART_GIRIS') {
        return modes.includes(mode) || modes.includes('KART_LISTE') || modes.includes('IPLIK') || modes.includes('KUMAS')
            || modes.includes('MAMUL_DEPO') || modes.includes('DEPO_HAREKET') || modes.includes('DEPO_HAREKET_LISTE');
    }
    if (mode === 'IPLIK' || mode === 'KUMAS' || mode === 'MAMUL_DEPO') {
        return modes.includes(mode) || modes.includes('DEPO_HAREKET');
    }
    if (mode === 'SEVKIYAT') {
        return modes.includes('SEVKIYAT') || modes.includes('KONFEKSIYON') || modes.includes('PLANLAMA');
    }
    if (mode === 'KONFEKSIYON_PLANLAMA') {
        return modes.includes('KONFEKSIYON_PLANLAMA') || modes.includes('KONFEKSIYON');
    }
    if (mode === 'FASON_TAKIP') {
        return modes.includes('FASON_TAKIP') || modes.includes('KONFEKSIYON');
    }
    if (mode === 'DOKUMA_FASON_TAKIP') {
        return modes.includes('DOKUMA_FASON_TAKIP') || modes.includes('DOKUMA_TAKIP');
    }
    if (mode === 'DOKUMA_DEPO') {
        return modes.includes('DOKUMA_DEPO') || modes.includes('DOKUMA_TAKIP');
    }
    if (mode === 'TEZGAH_PLANLAMA') {
        return modes.includes('TEZGAH_PLANLAMA') || modes.includes('DOKUMA_TAKIP');
    }
    if (mode === 'KONFEKSIYON_KESIM' || mode === 'KONFEKSIYON_YIKAMA' || mode === 'KONFEKSIYON_KALITE') {
        // YIKAMA_TAKIP: mobilin eski mod adı, kayıtlı kullanıcılarda hâlâ bulunabilir.
        // BOYAHANE_URETIM: yıkama ile aynı "Terbiye" grubunda, o yetki yıkamayı da açar.
        return modes.includes(mode) || modes.includes('KONFEKSIYON')
            || (mode === 'KONFEKSIYON_YIKAMA' && (modes.includes('YIKAMA_TAKIP') || modes.includes('BOYAHANE_URETIM')));
    }
    return modes.includes(mode);
}

function erpUserCan(mode) {
    if (!erpCurrentUser) return false;
    return erpModeAcikMi(
        mode,
        erpNormalizeAllowedModes(erpCurrentUser.allowed_modes),
        String(erpCurrentUser.role || '').toLowerCase() === 'admin'
    );
}

/** Sevk / yüklenen adedi — tek kaynak menü: Sevkiyat */
function planlamaIhtiyacSevkGirisYapabilir() {
    if (typeof erpIsAdmin === 'function' && erpIsAdmin()) return true;
    if (!erpCurrentUser) return false;
    const modes = erpNormalizeAllowedModes(erpCurrentUser.allowed_modes);
    return modes.includes('SEVKIYAT')
        || modes.includes('KONFEKSIYON')
        || modes.includes('PLANLAMA');
}
try { window.planlamaIhtiyacSevkGirisYapabilir = planlamaIhtiyacSevkGirisYapabilir; } catch (e) {}

/** Adet kutuları yalnızca Sevkiyat ekranında açık */
function sevkiyatAdetGirisAktifMi() {
    return (typeof appMode === 'string' && appMode === 'SEVKIYAT')
        && (typeof planlamaIhtiyacSevkGirisYapabilir === 'function' ? planlamaIhtiyacSevkGirisYapabilir() : false);
}
try { window.sevkiyatAdetGirisAktifMi = sevkiyatAdetGirisAktifMi; } catch (e) {}

function erpIsAdmin() {
    return !!erpCurrentUser && String(erpCurrentUser.role || '').toLowerCase() === 'admin';
}

function erpUpdateSidebarUser() {
    const av = document.getElementById('erp-sidebar-avatar');
    const nm = document.getElementById('erp-sidebar-name');
    const rl = document.getElementById('erp-sidebar-role');
    if (!erpCurrentUser) {
        if (av) av.textContent = '—';
        if (nm) nm.textContent = '—';
        if (rl) rl.textContent = '—';
        return;
    }
    const dn = erpCurrentUser.display_name || erpCurrentUser.username || 'Kullanıcı';
    const parts = String(dn).trim().split(/\s+/).filter(Boolean);
    const ini = (parts.length >= 2 ? parts[0][0] + parts[1][0] : (parts[0] || '?').slice(0, 2)).toUpperCase();
    if (av) av.textContent = ini.slice(0, 2);
    if (nm) nm.textContent = `Aktif kullanıcı: ${erpCurrentUser.username || dn}`;
    if (rl) rl.textContent = erpCurrentUser.role === 'admin' ? 'Yönetici' : 'Kullanıcı';
}

async function erpSidebarVersionGuncelle() {
    const el = document.getElementById('erp-sidebar-version');
    if (!el) return;
    /* Gösterilen sürüm = programın ÇALIŞTIRDIĞI ekranların sürümü (erp-build.js, içerik
       güncellemesiyle gelir). Eskiden EXE sürümü (getAppVersion) gösteriliyordu: EXE 10.09'dan
       beri 1.1.15'te kaldığı için fabrika bilgisayarları 1.1.20 ekranlarını çalıştırırken
       menüde "1.1.15" yazıyor, güncelleme gelmemiş sanılıyordu (24.09.2026). EXE sürümü
       farklıysa üzerine gelince görünür. */
    const icerik = String(window.__ERP_BUILD?.version || '').trim();
    let program = '';
    if (window.erpDesktop?.getAppVersion) {
        try { program = String((await window.erpDesktop.getAppVersion()) || '').trim(); } catch (e) {}
    }
    const v = icerik || program || '1.0.4';
    el.textContent = `sürüm ${v} GG`;
    el.title = program && program !== v
        ? `Ekranlar: sürüm ${v} · program dosyası (EXE): sürüm ${program}`
        : `sürüm ${v}`;
}

function erpToast(message, type = 'success', ms = 2600) {
    const id = 'erp-toast-host';
    let host = document.getElementById(id);
    if (!host) {
        host = document.createElement('div');
        host.id = id;
        host.style.cssText = 'position:fixed;right:18px;top:18px;z-index:99999;display:flex;flex-direction:column;gap:8px;pointer-events:none';
        document.body.appendChild(host);
    }
    const ok = type !== 'error';
    const bg = ok ? 'rgba(16,185,129,0.95)' : 'rgba(239,68,68,0.95)';
    const border = ok ? 'rgba(16,185,129,1)' : 'rgba(239,68,68,1)';
    const icon = ok ? '✅' : '⚠️';
    const t = document.createElement('div');
    t.style.cssText = `pointer-events:none;min-width:220px;max-width:360px;padding:10px 12px;border-radius:10px;color:#fff;background:${bg};border:1px solid ${border};box-shadow:0 10px 24px rgba(0,0,0,.28);font-size:12px;font-weight:600;line-height:1.35;display:flex;gap:8px;align-items:flex-start;transform:translateY(-6px);opacity:0;transition:all .18s ease`;
    t.innerHTML = `<span style="font-size:13px;line-height:1">${icon}</span><span>${pdfEsc(String(message || 'İşlem tamamlandı.'))}</span>`;
    host.appendChild(t);
    requestAnimationFrame(() => { t.style.opacity = '1'; t.style.transform = 'translateY(0)'; });
    setTimeout(() => {
        t.style.opacity = '0';
        t.style.transform = 'translateY(-6px)';
        setTimeout(() => { try { t.remove(); } catch (e) {} }, 220);
    }, Math.max(1200, parseInt(ms, 10) || 2600));
}

function erpClearTransientUi() {
    // Tekil toast
    const t = document.getElementById('erp-toast');
    if (t) {
        try { clearTimeout(t._timer); } catch (e) {}
        try { t.remove(); } catch (e) {}
    }
    // Çoklu toast host
    const host = document.getElementById('erp-toast-host');
    if (host) {
        try { host.innerHTML = ''; } catch (e) {}
        try { host.remove(); } catch (e) {}
    }
    // Arama dropdown'ları body'e taşındığı için mod değişiminde temizle
    try { hideAllDropdowns(); } catch (e) {}
}

function erpApplyNavPermissions() {
    const nav = document.getElementById('main-nav');
    if (!nav) return;
    nav.querySelectorAll('.erp-nav-denied').forEach(el => el.classList.remove('erp-nav-denied'));
    document.querySelectorAll('.erp-sidebar [data-erp-mode].erp-nav-denied').forEach(el => el.classList.remove('erp-nav-denied'));

    if (!erpCurrentUser) return;

    const mark = (el, mode) => {
        if (!el || !mode) return;
        if (!erpUserCan(mode)) el.classList.add('erp-nav-denied');
    };

    mark(document.getElementById('nav-DASHBOARD'), 'DASHBOARD');

    nav.querySelectorAll('.nav-pro-sub[id^="nav-"]').forEach(el => {
        if (el.hasAttribute('data-erp-mode')) return;
        const id = el.id || '';
        if (!id.startsWith('nav-')) return;
        const m = id.slice(4);
        mark(el, m);
    });

    nav.querySelectorAll('.nav-pro-sub[data-erp-mode]').forEach(el => {
        mark(el, el.getAttribute('data-erp-mode'));
    });

    ['siparis', 'depo', 'sevkiyat', 'dokuma', 'terbiye', 'konfeksiyon', 'fason', 'numune', 'planlama', 'yonetim'].forEach(prefix => {
        const area = document.getElementById('sub-' + prefix);
        const toggle = document.getElementById('nav-' + prefix + '-toggle');
        if (!area || !toggle) return;
        const subs = Array.from(area.querySelectorAll(':scope > .nav-pro-sub'));
        const anyVis = subs.some(s => !s.classList.contains('erp-nav-denied'));
        if (!anyVis) {
            area.classList.add('erp-nav-denied');
            toggle.classList.add('erp-nav-denied');
        }
    });

    const uretimGroup = document.getElementById('group-uretim');
    const uretimWrap = uretimGroup?.closest('.nav-group');
    if (uretimWrap && uretimGroup) {
        const toggles = Array.from(uretimGroup.querySelectorAll(':scope > .nav-pro[id$="-toggle"]'));
        const anyVis = toggles.some(t => !t.classList.contains('erp-nav-denied'));
        uretimWrap.style.display = anyVis ? '' : 'none';
    }

    document.querySelectorAll('.erp-sidebar [data-erp-mode]').forEach(btn => {
        const m = btn.getAttribute('data-erp-mode');
        mark(btn, m);
    });
}

// ── Canlı yetki senkronu ────────────────────────────────────
// Yönetici yetki kaydı → hedef kullanıcının açık ekranı hemen güncellenir
// (BroadcastChannel + localStorage + Supabase broadcast + kısa aralıklı poll).
const ERP_YETKI_SENK_MS = 3000;
const ERP_YETKI_SENK_MS_REALTIME = 20000;
const ERP_YETKI_RT_KANAL = 'erp-yetki-global';
let erpYetkiSenkTimer = null;
let erpYetkiSenkMesgul = false;
let erpYetkiSenkDinleyiciKuruldu = false;
let erpYetkiSenkSonAt = 0;
let erpYetkiSenkIlkTur = true;
let _erpYetkiBc = null;
let _erpYetkiRtChannel = null;
let _erpYetkiRtAbone = false;

/** Gerçek oturum yoksa (yerel bypass) yetki senkronu atlanır. */
function erpYetkiSenkAtlaMi() {
    if (!erpCurrentUser) return true;
    if (String(erpCurrentUser.username || '') === 'yerel') return true;
    if (!erpGetToken()) return true;
    return false;
}

/** Tüm oturumlar aynı Supabase kanalını dinler / yayınlar. */
function erpYetkiRtKanalAl() {
    // `sb` let ile tanımlı — window.sb yok; yanlış kontrol senkronu tamamen öldürürdü.
    if (!sb || typeof sb.channel !== 'function') return null;
    if (_erpYetkiRtChannel) return _erpYetkiRtChannel;
    _erpYetkiRtChannel = sb.channel(ERP_YETKI_RT_KANAL, {
        config: { broadcast: { ack: false, self: false } }
    })
        .on('broadcast', { event: 'bump' }, ({ payload }) => {
            if (erpYetkiBumpBanaMi(payload)) erpYetkiSenkTick(true);
        });
    _erpYetkiRtChannel.subscribe((status) => {
        _erpYetkiRtAbone = status === 'SUBSCRIBED';
    });
    return _erpYetkiRtChannel;
}

function erpYetkiImzasi(u) {
    if (!u) return '';
    const modlar = erpNormalizeAllowedModes(u.allowed_modes).slice().sort();
    return [
        String(u.role || '').toLowerCase(),
        u.active === false ? 'pasif' : 'aktif',
        String(u.display_name || ''),
        modlar.join('|')
    ].join('~');
}

/** Yönetici kaydı sonrası: hedef kullanıcının açık oturumunu hemen uyandır */
function erpYetkiBumpYayinla(username) {
    const payload = { u: String(username || '').trim().toLowerCase(), t: Date.now() };
    if (!payload.u) return;
    try { localStorage.setItem('erp_yetki_bump', JSON.stringify(payload)); } catch (e) {}
    try {
        if (!_erpYetkiBc) _erpYetkiBc = new BroadcastChannel('erp-yetki');
        _erpYetkiBc.postMessage(payload);
    } catch (e) {}
    try {
        const ch = erpYetkiRtKanalAl();
        if (!ch) return;
        const msg = { type: 'broadcast', event: 'bump', payload };
        const gonder = () => {
            try { ch.send(msg); } catch (e) {}
        };
        gonder();
        if (!_erpYetkiRtAbone) {
            setTimeout(gonder, 500);
            setTimeout(gonder, 1500);
        }
    } catch (e) {}
}

function erpYetkiBumpBanaMi(payload) {
    const u = String(payload?.u || '').trim().toLowerCase();
    const me = String(erpCurrentUser?.username || '').trim().toLowerCase();
    return !!u && !!me && u === me;
}

function erpNavGrupAc(prefix) {
    const area = document.getElementById('sub-' + prefix);
    if (!area || area.classList.contains('erp-nav-denied')) return;
    area.classList.add('open');
    const chev = document.getElementById('chev-' + prefix);
    if (chev) chev.textContent = '▴';
}

/** Sunucudan gelen kullanıcıyı uygular; değişiklik olduysa true döner. */
function erpYetkiUygula(sunucuUser) {
    if (!sunucuUser || !erpCurrentUser) return false;
    let raw = sunucuUser;
    if (typeof raw === 'string') {
        try { raw = JSON.parse(raw); } catch (e) { return false; }
    }
    if (!raw || typeof raw !== 'object') return false;

    const yeniRol = String(raw.role || 'user').toLowerCase() === 'admin' ? 'admin' : 'user';
    const yeni = {
        username: raw.username || erpCurrentUser.username,
        display_name: raw.display_name || raw.username || erpCurrentUser.display_name,
        role: yeniRol,
        allowed_modes: yeniRol === 'admin' ? [] : erpNormalizeAllowedModes(raw.allowed_modes),
        active: raw.active !== false
    };
    if (erpYetkiImzasi(yeni) === erpYetkiImzasi(erpCurrentUser)) return false;

    const oncekiRol = String(erpCurrentUser.role || '').toLowerCase();
    const oncekiModlar = new Set(erpNormalizeAllowedModes(erpCurrentUser.allowed_modes));
    erpCurrentUser = yeni;
    try { localStorage.setItem('erp_user_cache', JSON.stringify(yeni)); } catch (e) {}

    erpUpdateSidebarUser();
    erpApplyNavPermissions();
    if (yeni.role === 'admin') {
        erpInjectAdminNav();
        // Yönetici olunca tüm menü gruplarını aç — boş allowed_modes ile "kazandi" hiç tetiklenmezdi
        try {
            ['siparis', 'depo', 'sevkiyat', 'dokuma', 'terbiye', 'konfeksiyon', 'fason', 'planlama', 'yonetim']
                .forEach((p) => erpNavGrupAc(p));
        } catch (e) {}
    } else if (oncekiRol === 'admin') {
        document.getElementById('nav-KULLANICI_YONETIMI')?.remove();
        document.getElementById('nav-GUNLUK_ISLEMLER')?.remove();
    }

    // Yeni açılan menü gruplarını göster — yalnızca yeni yetki eklendiyse
    try {
        if (yeni.role !== 'admin') {
            const yeniModlar = new Set(erpNormalizeAllowedModes(yeni.allowed_modes));
            const kazandi = (m) => yeniModlar.has(m) && !oncekiModlar.has(m);
            if (kazandi('PLANLAMA') || kazandi('SEVKIYAT') || kazandi('KONFEKSIYON')) erpNavGrupAc('planlama');
            if (kazandi('SIPARIS_LISTE') || kazandi('SIPARIS_GIRIS') || kazandi('SIPARIS_KAPANAN')) erpNavGrupAc('siparis');
            if (kazandi('KUMAS') || kazandi('MAMUL_DEPO') || kazandi('DEPO_HAREKET') || kazandi('STOK_SAYIM')) erpNavGrupAc('depo');
            if (kazandi('SEVKIYAT')) erpNavGrupAc('sevkiyat');
            if (kazandi('DOKUMA_TAKIP') || kazandi('DOKUMA_DEPO') || kazandi('IPLIK') || kazandi('TEZGAH_PLANLAMA')) erpNavGrupAc('dokuma');
            if (kazandi('BOYAHANE_URETIM') || kazandi('KONFEKSIYON_YIKAMA')) erpNavGrupAc('terbiye');
            if (kazandi('KONFEKSIYON')) erpNavGrupAc('konfeksiyon');
            if (kazandi('FASON_TAKIP')) erpNavGrupAc('fason');
        }
    } catch (e) {}

    if (erpYetkiSenkIlkTur) return true;

    if (typeof appMode === 'string' && appMode && !erpUserCan(appMode)) {
        try { erpToast('Bu ekranın yetkisi kaldırıldı, anasayfaya alındınız.', 'error', 4200); } catch (e) {}
        try { setAppMode('DASHBOARD'); } catch (e) {}
    } else {
        try { erpToast('Yetkileriniz güncellendi — menü anında yenilendi.', 'success', 3200); } catch (e) {}
    }
    return true;
}

async function erpYetkiSenkTick(force = false) {
    if (erpYetkiSenkMesgul) {
        if (force) setTimeout(() => { try { erpYetkiSenkTick(true); } catch (e) {} }, 350);
        return;
    }
    if (!erpCurrentUser || !sb) return;
    if (erpYetkiSenkAtlaMi()) return;
    const token = erpGetToken();
    if (!token) return;
    const simdi = Date.now();
    if (!force && simdi - erpYetkiSenkSonAt < 2000) return;
    erpYetkiSenkSonAt = simdi;

    erpYetkiSenkMesgul = true;
    try {
        const { data, error } = await sb.rpc('erp_session_me', { p_token: token });
        if (error) return;
        let payload = data;
        if (typeof payload === 'string') {
            try { payload = JSON.parse(payload); } catch (e) { return; }
        }
        if (!payload || payload.ok !== true) {
            try { erpLiveSyncStop(); } catch (e) {}
            erpYetkiSenkDurdur();
            erpSetToken(null);
            localStorage.removeItem('erp_user_cache');
            erpCurrentUser = null;
            alert('Oturumunuz sonlandırıldı. Lütfen tekrar giriş yapın.');
            location.reload();
            return;
        }
        erpYetkiUygula(payload.user);
        erpYetkiSenkIlkTur = false;
    } catch (e) {
        /* sessiz */
    } finally {
        erpYetkiSenkMesgul = false;
    }
}

function erpYetkiSenkBaslat() {
    erpYetkiSenkDurdur();
    if (erpYetkiSenkAtlaMi()) return;
    /* Realtime kanalı bağlıyken bu poll yalnızca yedek (session iptali
       kontrolü); bağlı değilken hızlı kalır. bkz. erpLiveStartPoll (04). */
    const yetkiSenkMs = () => (_erpYetkiRtAbone ? ERP_YETKI_SENK_MS_REALTIME : ERP_YETKI_SENK_MS);
    const yetkiSenkTickDongu = () => {
        erpYetkiSenkTick(false);
        if (erpYetkiSenkTimer) {
            clearInterval(erpYetkiSenkTimer);
            erpYetkiSenkTimer = setInterval(yetkiSenkTickDongu, yetkiSenkMs());
        }
    };
    erpYetkiSenkTimer = setInterval(yetkiSenkTickDongu, yetkiSenkMs());

    if (!erpYetkiSenkDinleyiciKuruldu) {
        erpYetkiSenkDinleyiciKuruldu = true;
        window.addEventListener('focus', () => { erpYetkiSenkTick(true); });
        document.addEventListener('visibilitychange', () => {
            if (!document.hidden) erpYetkiSenkTick(true);
        });
        window.addEventListener('storage', (e) => {
            if (e.key !== 'erp_yetki_bump' || !e.newValue) return;
            try {
                const p = JSON.parse(e.newValue);
                if (erpYetkiBumpBanaMi(p)) erpYetkiSenkTick(true);
            } catch (err) {}
        });
        try {
            _erpYetkiBc = new BroadcastChannel('erp-yetki');
            _erpYetkiBc.onmessage = (ev) => {
                if (erpYetkiBumpBanaMi(ev.data)) erpYetkiSenkTick(true);
            };
        } catch (e) {}
    }

    // Supabase broadcast — farklı bilgisayar / tarayıcıdaki açık oturum
    try { erpYetkiRtKanalAl(); } catch (e) {}

    erpYetkiSenkTick(true);
}

function erpYetkiSenkDurdur() {
    if (erpYetkiSenkTimer) {
        clearInterval(erpYetkiSenkTimer);
        erpYetkiSenkTimer = null;
    }
    if (_erpYetkiRtChannel && sb) {
        try { sb.removeChannel(_erpYetkiRtChannel); } catch (e) {}
        _erpYetkiRtChannel = null;
        _erpYetkiRtAbone = false;
    }
}

function erpBootstrapLocalSession() {
    const allModes = ERP_PERM_MODES.map((p) => p[0]);
    erpCurrentUser = {
        username: 'yerel',
        display_name: 'Yerel kullanıcı',
        role: 'admin',
        allowed_modes: allModes
    };
    erpUpdateSidebarUser();
    erpApplyNavPermissions();
}

