/* Sıralama kartta gösterilen kapanış tarihiyle aynı kaynaktan (siparisKapanisBilgiOku: gerçek
   kapanış kaydı, yoksa son işlem). Aynı anda kapananlarda yeni sipariş no üstte. */
function siparisKapananSonKapanisTs(sip) {
    return siparisKapanisBilgiOku(sip).d?.getTime() || 0;
}
function siparisKapananSonKapanisSirala(liste) {
    const snoNo = (s) => parseInt(String(s?.sno || '').replace(/\D+/g, ''), 10) || 0;
    return (liste || [])
        .map(s => [siparisKapananSonKapanisTs(s), snoNo(s), s])
        .sort((a, b) => (b[0] - a[0]) || (b[1] - a[1]))
        .map(x => x[2]);
}
/** Kapanan sipariş listesi: kapanış bilgisi.
    ÖNEMLİ — iki ayrı kaynak var, hangisi varsa o gösterilir:
      1) kapanis (notlar içindeki [KAPANIS:...] etiketi) — durum TAMAMLANDI yapıldığında
         yazılan GERÇEK kapatma kaydı: tarih + kapatan kişi. Kesin bilgidir.
      2) updated_at / updated_by — yalnızca yedek. Bu alan "bu satıra en son kim/ne yazdı"
         demektir; Excel içe aktarımı, not düzenlemesi, grup değişikliği de bunu değiştirir.
         Bu yüzden kişi adı "son işlem" olarak, soluk ve işaretli gösterilir; kapatan kişi
         diye sunulmaz (canlı veride 212 eski siparişin hiçbirinde gerçek kapanış kaydı yok). */
/** Kapanış günlük satırı: "✅ 09.09.2026 15:30:00 — [KİŞİ]: Sipariş TAMAMLANDI olarak kapatıldı." */
/** İptal satırı (07.10.2026) da kapanış sayılır: "🚫 … — [KİŞİ]: Sipariş İPTAL edildi. Önceki durum: X." */
const SIPARIS_KAPANIS_RE = /(?:✅|🚫)\s*(\d{2})\.(\d{2})\.(\d{4})\s+(\d{2}):(\d{2})(?::\d{2})?\s*—\s*\[([^\]]+)\]:\s*Sipariş (?:TAMAMLANDI|İPTAL)/;

function siparisGunlukZaman() {
    return new Date().toLocaleString('tr-TR', {
        day: '2-digit', month: '2-digit', year: 'numeric',
        hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
}

/** Kapanmadan önceki durum da yazılır ("Önceki durum: SEVK.") — Geri al oraya döndürür. */
function siparisKapanisSatiriOlustur(kisi, oncekiDurum) {
    const ad = String(kisi || (typeof currentUser !== 'undefined' ? currentUser : '') || 'Bilinmiyor').trim();
    const onc = siparisDurumNorm(oncekiDurum);
    const oncMetin = onc && onc !== 'TAMAMLANDI' ? ` Önceki durum: ${onc}.` : '';
    return `✅ ${siparisGunlukZaman()} — [${ad}]: Sipariş TAMAMLANDI olarak kapatıldı.${oncMetin}`;
}

/** İptal satırı — kapanış gibi önceki durumu da yazar (Geri al oraya döndürür). */
function siparisIptalSatiriOlustur(kisi, oncekiDurum) {
    const ad = String(kisi || (typeof currentUser !== 'undefined' ? currentUser : '') || 'Bilinmiyor').trim();
    const onc = siparisDurumNorm(oncekiDurum);
    const oncMetin = onc && !siparisKapaliMi(onc) ? ` Önceki durum: ${onc}.` : '';
    return `🚫 ${siparisGunlukZaman()} — [${ad}]: Sipariş İPTAL edildi.${oncMetin}`;
}

/** Geri alma günlük satırı — kim, ne zaman, hangi duruma (denetim izi). */
function siparisGeriAcmaSatiriOlustur(yeniDurum, kisi) {
    const ad = String(kisi || (typeof currentUser !== 'undefined' ? currentUser : '') || 'Bilinmiyor').trim();
    return `↩️ ${siparisGunlukZaman()} — [${ad}]: Kapanan sipariş geri alındı (${siparisDurumMeta(yeniDurum).label}).`;
}

/** Kapanan siparişi yalnız yönetici geri alır (kullanıcı, 01.10.2026: "sadece yöneticiler
    yapabilsin"). Mobil salt okunur — orada yok. */
function siparisGeriAcYetkiliMi() {
    return !window.ERP_MOBIL_LITE && typeof erpIsAdmin === 'function' && erpIsAdmin();
}
try { window.siparisGeriAcYetkiliMi = siparisGeriAcYetkiliMi; } catch (e) {}

/** Geri alınca dönülecek durum: kapanış satırındaki önceki durum; eski kayıtlarda yoksa Sevk
    (kapanıştan hemen önceki aşama). */
const SIPARIS_GERI_AL_VARSAYILAN = 'SEVK';
function siparisGeriAlHedefDurum(sip) {
    return siparisKapanisBilgiOku(sip).onceki || SIPARIS_GERI_AL_VARSAYILAN;
}

/** Kapanan siparişler listesindeki "↩ Geri al" düğmesi. */
function siparisGeriAl(siparisId) {
    const sip = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    if (!sip) return;
    return siparisListeDurumDegistir(siparisId, siparisGeriAlHedefDurum(sip), null);
}
try { window.siparisGeriAl = siparisGeriAl; } catch (e) {}

function siparisGeriAlDugmeHtml(sip) {
    if (!siparisGeriAcYetkiliMi() || !siparisKapaliMi(sip)) return '';
    const hedef = siparisDurumMeta(siparisGeriAlHedefDurum(sip)).label;
    return `<button type="button" class="siparis-geri-al-btn" title="Siparişi geri al — ${pdfEsc(hedef)} durumuna döner (yalnız yönetici)"
        onclick="event.stopPropagation();siparisGeriAl('${String(sip.id).replace(/'/g, "\\'")}')"
        onmousedown="event.stopPropagation()"
        style="cursor:pointer;font-size:8px;font-weight:700;padding:1px 6px;margin-top:3px;border-radius:999px;border:1px solid var(--border);background:var(--surface2);color:var(--text2);align-self:flex-start;line-height:1.4">↩ Geri al</button>`;
}

function siparisKapanisBilgiOku(sip) {
    /* Geri alınıp yeniden kapanan siparişte birden çok kapanış satırı olur — sonuncusu geçerli. */
    const tum = String(sip?.islem_gecmisi || '').split('\n').filter(s => SIPARIS_KAPANIS_RE.test(s));
    const satir = tum.length ? tum[tum.length - 1] : '';
    const m = satir ? satir.match(SIPARIS_KAPANIS_RE) : null;
    if (m) {
        const d = new Date(+m[3], +m[2] - 1, +m[1], +m[4], +m[5]);
        const om = satir.match(/Önceki durum:\s*([^.\n]+)\./);
        const onceki = om ? siparisDurumNorm(om[1]) : '';
        if (!Number.isNaN(d.getTime())) return { d, kisi: String(m[6] || '').trim(), kesin: true, onceki: onceki && !siparisKapaliMi(onceki) ? onceki : '', iptal: satir.includes('🚫') };
    }
    const ts = sip?.updated_at || sip?.ttarih || sip?.created_at || '';
    const d = ts ? new Date(ts) : null;
    if (!d || Number.isNaN(d.getTime())) return { d: null, kisi: String(sip?.updated_by || '').trim(), kesin: false };
    return { d, kisi: String(sip?.updated_by || '').trim(), kesin: false };
}

function siparisKapanisBilgiHtml(sip) {
    const b = siparisKapanisBilgiOku(sip);
    const esc = (v) => (typeof pdfEsc === 'function' ? pdfEsc(v) : String(v ?? ''));
    const tarih = b.d ? b.d.toLocaleDateString('tr-TR') : '—';
    const saat = b.d ? b.d.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }) : '';
    const kisiBaslik = b.kesin
        ? `Kapatan: ${esc(b.kisi)}`
        : `Son işlemi yapan: ${esc(b.kisi)} — bu kişi siparişi kapatan kişi olmayabilir (alan, kayda en son yazan kullanıcıyı/işlemi tutar)`;
    return `<div style="font-weight:600;color:var(--text)" title="${b.kesin ? 'Kapanış tarihi' : 'Son işlem tarihi (kesin kapanış kaydı yok)'}">${esc(tarih)}</div>
        ${saat ? `<div style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace;margin-top:1px">${esc(saat)}</div>` : ''}
        ${b.kisi ? `<div style="font-size:9px;color:var(--text${b.kesin ? '2' : '3'});margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${kisiBaslik}">${b.kesin ? '' : '~'}${esc(b.kisi)}</div>` : ''}`;
}
