function erpSyncTableWatermarkMs(rows) {
    let max = 0;
    (rows || []).forEach((r) => {
        /* updated_at varsa o (düzeltmeler de artımlı gelsin), yoksa created_at */
        const t = Date.parse(r && (r.updated_at || r.created_at) ? (r.updated_at || r.created_at) : 0);
        if (Number.isFinite(t) && t > max) max = t;
    });
    return max;
}

function erpSyncUnionById(incoming, onceki) {
    const inc = incoming || [];
    const prev = onceki || [];
    if (!prev.length) return inc;
    if (!inc.length) return prev;
    const map = new Map(prev.map(r => [String(r.id), r]));
    inc.forEach((r) => {
        if (!r || r.id == null) return;
        const key = String(r.id);
        map.set(key, map.has(key) ? { ...map.get(key), ...r } : r);
    });
    return Array.from(map.values());
}

/** Ağır JSON.stringify yerine dar alanlı arama metni (giriş alanları aynı kalır) */
function erpRowSearchIdx(row) {
    if (!row || typeof row !== 'object') return '';
    if (row._search_idx) return row._search_idx;
    const parts = [
        row.stok_kodu, row.desen_kodu, row.desen_adi, row.urun_adi, row.firma, row.marka, row.renk,
        row.lot_no, row.parti_no, row.iplik_no, row.kumas_cinsi, depoIrsNo(row), row.notlar,
        row.sno, row.cins, row.ebat, row.olcu, row.updated_by, row.kaynak_birim, row.araci_firma,
        row.depo, row.kalite, row.ana_grup, row.uretim_yeri, row.hareket_tipi, row.islem_turu
    ];
    row._search_idx = parts.map((x) => String(x == null ? '' : x).toLowerCase()).join(' ');
    return row._search_idx;
}
try { window.erpRowSearchIdx = erpRowSearchIdx; } catch (e) {}

/** Sipariş no için parçalama/sıralama yardımcıları */
function parseSiparisNoParts(sno) {
    const raw = String(sno || '').trim();
    const upper = raw.toUpperCase();
    const sp = upper.match(/^SP\s*[-_ ]?\s*(\d+)$/);
    if (sp) return { year: 9999, seq: parseInt(sp[1], 10), raw };
    const m = upper.match(/(\d{4})\s*\/\s*(\d+)/);
    if (m) return { year: parseInt(m[1], 10), seq: parseInt(m[2], 10), raw };
    const nums = upper.match(/\d+/g);
    const seq = nums && nums.length ? parseInt(nums[nums.length - 1], 10) : 0;
    return { year: 0, seq: Number.isFinite(seq) ? seq : 0, raw };
}
function normalizeSiparisNo(sno) {
    return String(sno || '').trim().toUpperCase();
}
function compareSiparisNo(a, b) {
    const pa = parseSiparisNoParts(a);
    const pb = parseSiparisNoParts(b);
    if (pa.year !== pb.year) return pa.year - pb.year;
    if (pa.seq !== pb.seq) return pa.seq - pb.seq;
    return String(pa.raw).localeCompare(String(pb.raw), 'tr', { numeric: true, sensitivity: 'base' });
}

function siparisListeKalemleriArr(i) {
    if (!i) return [];
    try {
        const c = i.cins;
        if (typeof c === 'string') return JSON.parse(c) || [];
        return Array.isArray(c) ? c : [];
    } catch (e) {
        return [];
    }
}

/** Liste satırı için kısa ürün özeti (ad / kod + varsa renk · renk kodu) */
function siparisKalemOzetEtiket(k) {
    if (!k || typeof k !== 'object') return '';
    const ad = String(k.ad || k.urun_adi || k.kod || '').trim();
    const renk = String(k.renk || '').trim();
    const rk = typeof siparisKalemRenkKoduMetni === 'function'
        ? siparisKalemRenkKoduMetni(k)
        : String(k.rkod || k.renk_kodu || [k.rkod1, k.rkod2, k.rkod3].filter(Boolean).join(' · ') || '').trim();
    const boyaliIpucu = /boya|bask[iı]|terbiye|renkli/i.test([ad, k.grup, k.tip].join(' '));
    const renkParca = [renk, rk].filter(Boolean).join(' · ');
    if (!ad && !renkParca) return '';
    if (!renkParca) return ad;
    // Boyalı / renkli ürünlerde renk + renk kodu her zaman görünsün
    if (boyaliIpucu || renk || rk) {
        return ad ? `${ad} · ${renkParca}` : renkParca;
    }
    return ad;
}

function siparisListeOzetMetni(i, maxLen) {
    const kalemler = siparisListeKalemleriArr(i);
    if (!kalemler.length) return '—';
    maxLen = maxLen || 96;
    const parts = kalemler.map(k => siparisKalemOzetEtiket(k)).filter(Boolean);
    let s = '';
    if (parts.length) {
        s = parts.slice(0, 2).join(', ');
        if (parts.length > 2) s += ` (+${parts.length - 2})`;
    } else {
        s = `${kalemler.length} kalem`;
    }
    if (kalemler.length > 1 && parts.length <= 2 && !s.includes('(+')) s += ` · ${kalemler.length} çeşit`;
    if (s.length > maxLen) s = s.slice(0, Math.max(1, maxLen - 1)) + '…';
    return s;
}
try { window.siparisKalemOzetEtiket = siparisKalemOzetEtiket; } catch (e) {}
try { window.siparisListeOzetMetni = siparisListeOzetMetni; } catch (e) {}

function siparisListeAdetGoster(i) {
    const kalemler = siparisListeKalemleriArr(i);
    if (!kalemler.length) {
        const header = parseFloat(i.miktar);
        return Number.isFinite(header) && header > 0 ? `${header} adet` : '—';
    }
    const toplamlar = { ADET: 0, KG: 0, MT: 0 };
    kalemler.forEach(k => {
        const birim = siparisKalemBirim(k);
        const ham = parseFloat(k?.miktar || 0);
        if (!Number.isFinite(ham) || ham <= 0) return;
        if (birim === 'ADET') toplamlar.ADET += Math.round(ham);
        else if (birim === 'KG') toplamlar.KG += ham;
        else if (birim === 'MT') toplamlar.MT += ham;
    });
    const parcali = [];
    if (toplamlar.ADET > 0) parcali.push(`${toplamlar.ADET.toLocaleString('tr-TR')} adet`);
    if (toplamlar.KG > 0) parcali.push(`${toplamlar.KG.toFixed(1)} kg`);
    if (toplamlar.MT > 0) parcali.push(`${toplamlar.MT.toFixed(1)} mt`);
    return parcali.length ? parcali.join(' + ') : '—';
}

/** Kalem düzeyinde ürün tipi (sipariş girişi — kalem satırı) */
const SIPARIS_URUN_GRUPLARI = [
    { kod: 'PIKE', etiket: 'Pike' },
    { kod: 'YORGAN', etiket: 'Yorgan' },
    { kod: 'DOLGULU', etiket: 'Dolgulu' },
    { kod: '4_KATLI', etiket: '4 Katlı' },
    { kod: 'MUSLIN', etiket: 'Müslin' },
    { kod: 'NEVRESIM', etiket: 'Nevresim' },
    { kod: 'CARSAF', etiket: 'Çarşaf' },
    { kod: 'HAVLU', etiket: 'Havlu' },
    { kod: 'BATTANIYE', etiket: 'Battaniye' },
    { kod: 'YASTIK', etiket: 'Yastık' },
    { kod: 'ALEZ', etiket: 'Alezi' },
    { kod: 'KIRLENT', etiket: 'Kırlent' },
    { kod: 'ORTU', etiket: 'Örtü' },
    { kod: 'HALI', etiket: 'Halı' },
    { kod: 'DIGER', etiket: 'Diğer' }
];

/** Sipariş listesi — filtre ve sütun (iş grupları) */
const SIPARIS_GRUP_FILTRE = [
    { kod: 'EV_TEKSTILI', etiket: 'Ev tekstili' },
    { kod: 'GIDA', etiket: 'Gıda' },
    { kod: 'HALI', etiket: 'Halıcı' },
    { kod: 'KOLTUK_ORTUSU', etiket: 'Koltuk örtüsü' }
];

function normSiparisGrubu(v) {
    const s = String(v || '').trim().toUpperCase()
        .replaceAll('İ', 'I').replaceAll('Ş', 'S').replaceAll('Ğ', 'G')
        .replaceAll('Ü', 'U').replaceAll('Ö', 'O').replaceAll('Ç', 'C');
    if (!s) return '';
    if (s.includes('GIDA')) return 'GIDA';
    if (s.includes('HALI')) return 'HALI';
    if (s.includes('EV') && s.includes('TEKSTIL')) return 'EV_TEKSTILI';
    if (s.includes('KOLTUK') && s.includes('ORTU')) return 'KOLTUK_ORTUSU';
    return s.replaceAll(' ', '_');
}

function siparisGrubuEtiket(kod) {
    const k = normSiparisGrubu(kod);
    const hit = SIPARIS_GRUP_FILTRE.find(g => g.kod === k);
    return hit ? hit.etiket : (k ? k.replaceAll('_', ' ') : '—');
}

function siparisSatirGrubuBul(row) {
    const dogrudan = normSiparisGrubu(row?.siparis_grubu || '');
    if (dogrudan && SIPARIS_GRUP_FILTRE.some(g => g.kod === dogrudan)) return dogrudan;
    const firma = normSiparisGrubu(row?.firma || '');
    if (SIPARIS_GRUP_FILTRE.some(g => g.kod === firma)) return firma;
    return dogrudan || '';
}




function siparisListeUrunGrubuMetni(row) {
    const g = siparisSatirGrubuBul(row);
    return g ? siparisGrubuEtiket(g) : '—';
}



function siparisListeAramaBlob(i) {
    if (i && i._search_siparis_blob) return i._search_siparis_blob;
    const grup = siparisSatirGrubuBul(i);
    const grupLbl = siparisGrubuEtiket(grup);
    const kalemler = siparisListeKalemleriArr(i);
    const kalemTxt = kalemler.map(k => {
        const rk = typeof siparisKalemRenkKoduMetni === 'function' ? siparisKalemRenkKoduMetni(k) : (k.rkod || k.renk_kodu || '');
        return [k.kod, k.ad, k.grup, k.renk, rk, k.ebat, k.birim, k.miktar].join(' ');
    }).join(' ');
    const durumLbl = (() => {
        const d = siparisDurumNorm(i?.durum);
        const hit = (typeof SIPARIS_DURUM_SECENEKLERI !== 'undefined' ? SIPARIS_DURUM_SECENEKLERI : [])
            .find(x => x.kod === d);
        return hit ? hit.label : (i?.durum || '');
    })();
    const terminTr = (() => {
        const iso = String(i?.ttarih || '').slice(0, 10);
        if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
        const [y, m, d] = iso.split('-');
        return `${d}.${m}.${y} ${d}/${m}/${y} ${iso}`;
    })();
    const blob = [
        i?.sno, i?.firma, i?.durum, durumLbl, i?.siparis_grubu, grup, grupLbl,
        i?.ttarih, terminTr, i?.starih, i?.notlar, i?.aciklama,
        kalemTxt,
        typeof siparisListeOzetMetni === 'function' ? siparisListeOzetMetni(i, 240) : '',
        typeof siparisListeAdetGoster === 'function' ? siparisListeAdetGoster(i) : ''
    ].join(' ').toLowerCase();
    if (i) i._search_siparis_blob = blob;
    return blob;
}

/* 30.09.2026: önce kutudaki yazı okunuyordu, boşsa hafızadaki değer. Kutu her
   tuşta yeniden çizildiği için hızlı silmede ekranda silinmiş yazı görünürken
   liste eski yazıyla süzülü kalıyor, ancak başka yere tıklayınca düzeliyordu.
   Artık tek kaynak hafızadaki değer (her tuşta siparisListePanelFiltreAlan yazar);
   kutu yalnız hafıza hiç kurulmamışsa okunur. */
function siparisListeTekAramaOku() {
    const hafiza = window.siparisListePanelFiltre && typeof window.siparisListePanelFiltre === 'object'
        ? window.siparisListePanelFiltre.q : undefined;
    return String(hafiza != null ? hafiza : (document.getElementById('f-siparis-q')?.value || '')).trim().toLowerCase();
}

function siparisListeTekAramaEslesir(i, q) {
    const raw = String(q ?? siparisListeTekAramaOku()).trim().toLowerCase();
    if (!raw) return true;
    const blob = siparisListeAramaBlob(i);
    const tokens = raw.split(/\s+/).filter(Boolean);
    if (!tokens.length) return true;
    return tokens.every(t => blob.includes(t));
}

/**
 * Sipariş kalemi — Renk kodu metni: yalnızca girilmiş kodlar.
 * Ürün rengi (renk sütunu) ile aynı olan tekrarlar ve mükerrer kodlar yazılmaz.
 */
function siparisKalemRenkKoduMetni(k) {
    if (!k || typeof k !== 'object') return '';
    const renkRaw = String(k.renk || '').trim();
    const renkNorm = renkRaw.toLocaleLowerCase('tr-TR');
    const chunks = [];
    const rkMain = String(k.rkod || '').trim();
    if (rkMain) {
        rkMain.split(/\s*[|·,;]+\s*/).forEach(part => {
            const t = String(part || '').trim();
            if (t) chunks.push(t);
        });
    }
    [k.rkod1, k.rkod2, k.rkod3, k.rkod4, k.rkod5, k.rkod6, k.renk_kodu].forEach(x => {
        const t = String(x || '').trim();
        if (t) chunks.push(t);
    });
    const seen = new Set();
    const out = [];
    for (const raw of chunks) {
        const norm = raw.toLocaleLowerCase('tr-TR');
        if (renkNorm && norm === renkNorm) continue;
        if (seen.has(norm)) continue;
        seen.add(norm);
        out.push(raw);
    }
    return out.join(' · ');
}

function sortSiparislerBySno(list) {
    return [...(list || [])].sort((x, y) => compareSiparisNo(x.sno, y.sno));
}

/** Tezgah no: 1,2,3…10,11 (metin sırası 1,10,11,2 değil) */
function sortTezgahlarByTezgahNo(list) {
    return [...(list || [])].sort((x, y) =>
        String(x.tezgah_no ?? '').localeCompare(String(y.tezgah_no ?? ''), 'tr', { numeric: true, sensitivity: 'base' })
    );
}
function siparisMaxSeqFromList(list) {
    let maxSeq = 399;
    for (const s of (list || [])) {
        const raw = String(s?.sno || '').trim();
        if (!raw) continue;
        const p = parseSiparisNoParts(raw);
        const n = parseInt(p?.seq, 10);
        if (Number.isFinite(n) && n > maxSeq) maxSeq = n;
    }
    return maxSeq;
}

function suggestNextSiparisNo() {
    return `SP${siparisMaxSeqFromList(dataCache.siparisler) + 1}`;
}

async function fetchMaxSiparisSeqFromDb() {
    if (!sb?.from) return siparisMaxSeqFromList(dataCache.siparisler);
    let maxSeq = 399;
    let from = 0;
    const pageSize = 2000;
    while (from < 50000) {
        const { data, error } = await erpWithTimeout(
            sb.from('siparisler').select('sno').order('created_at', { ascending: false }).range(from, from + pageSize - 1),
            'siparis sno',
            25000
        );
        if (error) throw error;
        const batch = data || [];
        if (!batch.length) break;
        maxSeq = Math.max(maxSeq, siparisMaxSeqFromList(batch));
        if (batch.length < pageSize) break;
        from += pageSize;
    }
    return maxSeq;
}

async function syncSiparisNoInput() {
    const snoEl = document.getElementById('val-sno');
    if (!snoEl) return;
    if (editingId && originalRecordSnapshot?.sno) {
        snoEl.value = String(originalRecordSnapshot.sno || '').trim();
        updateSiparisPreview();
        return;
    }
    const gen = ++_siparisNoSyncGen;
    try {
        const maxSeq = await fetchMaxSiparisSeqFromDb();
        if (gen !== _siparisNoSyncGen || editingId) return;
        const el = document.getElementById('val-sno');
        if (el) el.value = `SP${maxSeq + 1}`;
    } catch (e) {
        if (gen !== _siparisNoSyncGen || editingId) return;
        console.warn('Sipariş no sunucu sorgusu:', e?.message || e);
        const el = document.getElementById('val-sno');
        if (el) el.value = suggestNextSiparisNo();
    }
    if (gen === _siparisNoSyncGen && !editingId) updateSiparisPreview();
}

/** Sipariş üretim/iş sırası durumları (liste + form) */
const SIPARIS_DURUM_SECENEKLERI = [
    { kod: 'PLANDA', label: 'Planda', pill: 'pill-gray', renk: '#94a3b8' },
    { kod: 'BEKLEMEDE', label: 'Beklemede', pill: 'pill-amber', renk: '#fbbf24' },
    { kod: 'DOKUMA', label: 'Dokuma', pill: 'pill-cyan', renk: '#22d3ee' },
    { kod: 'TERBIYE', label: 'Terbiye', pill: 'pill-blue', renk: '#38bdf8' },
    { kod: 'ÜRETİMDE', label: 'Üretimde', pill: 'pill-violet', renk: '#a78bfa' },
    { kod: 'KONFEKSIYON', label: 'Konfeksiyon', pill: 'pill-pink', renk: '#fb7185' },
    /* Hazır (07.10.2026): her şey girilmiş, yalnız yükleme bekliyor — Tamamlandı denene kadar burada
       kalır (sipariş durumu yalnız elle değişir, otomatik geçiş yok). */
    { kod: 'HAZIR', label: 'Hazır', pill: 'pill-teal', renk: '#14b8a6' },
    { kod: 'SEVK', label: 'Sevk', pill: 'pill-green', renk: '#34d399' },
    { kod: 'TAMAMLANDI', label: 'Tamamlandı', pill: 'pill-green', renk: '#10b981' },
    { kod: 'İPTAL', label: 'İptal', pill: 'pill-red', renk: '#f87171' },
    { kod: 'DEVAM', label: 'Devam (eski)', pill: 'pill-violet', renk: '#a78bfa' }
];

function siparisDurumNorm(dbDurum) {
    let d = String(dbDurum || 'BEKLEMEDE').trim().toUpperCase()
        .replace(/İ/g, 'I').replace(/ı/g, 'I');
    // Türkçe karakterli kodlara geri map
    const raw = String(dbDurum || 'BEKLEMEDE').trim();
    if (raw === 'ÜRETİMDE' || d === 'URETIMDE') return 'ÜRETİMDE';
    if (raw === 'İPTAL' || d === 'IPTAL') return 'İPTAL';
    if (d === 'DEVAM EDIYOR' || d === 'DEVAM_EDIYOR') return 'ÜRETİMDE';
    if (d === 'KONFEKSIYON' || d === 'KONF') return 'KONFEKSIYON';
    if (d === 'TERBIYE' || d === 'BOYAHANE') return 'TERBIYE';
    if (d === 'HAZIR') return 'HAZIR';
    if (d === 'SEVK' || d === 'SEVKIYAT' || d === 'SEVK_HAZIR') return 'SEVK';
    if (d === 'PLANDA' || d === 'PLAN') return 'PLANDA';
    if (d === 'DOKUMA') return 'DOKUMA';
    if (d === 'BEKLEMEDE') return 'BEKLEMEDE';
    if (d === 'TAMAMLANDI') return 'TAMAMLANDI';
    if (d === 'DEVAM') return 'DEVAM';
    if (SIPARIS_DURUM_SECENEKLERI.some(x => x.kod === raw)) return raw;
    return raw || 'BEKLEMEDE';
}

/** Kapalı sipariş = Tamamlandı veya İptal (07.10.2026: iptal edilen sipariş kapananlara taşınır; açık
    listede, uyarılarda, geciken sayımında, planlama/sevk listelerinde görünmez). Sipariş ya da durum alır. */
function siparisKapaliMi(sipVeyaDurum) {
    const ham = sipVeyaDurum && typeof sipVeyaDurum === 'object' ? sipVeyaDurum.durum : sipVeyaDurum;
    if (!String(ham || '').trim()) return false;
    const d = siparisDurumNorm(ham);
    return d === 'TAMAMLANDI' || d === 'İPTAL';
}
try { window.siparisKapaliMi = siparisKapaliMi; } catch (e) {}

function siparisDurumMeta(dbDurum) {
    const kod = siparisDurumNorm(dbDurum);
    return SIPARIS_DURUM_SECENEKLERI.find(x => x.kod === kod)
        || { kod, label: kod, pill: 'pill-blue', renk: '#818cf8' };
}

function siparisDurumSelectHtml(siparisId, dbDurum, opts = {}) {
    const cur = siparisDurumNorm(dbDurum);
    const compact = !!opts.compact;
    /* Kapanmış sipariş: yalnız etiket — durum seçilerek açılmaz; geri alma Kapanan
       siparişler listesindeki "↩ Geri al" düğmesiyle, yalnız yönetici. */
    if (cur === 'TAMAMLANDI' || cur === 'İPTAL') {
        const m = siparisDurumMeta(cur);
        return `<span class="pill ${m.pill}" style="font-size:${compact ? '7px' : '9px'};padding:1px 5px;align-self:flex-start">${pdfEsc(m.label)}</span>`;
    }
    const optsHtml = SIPARIS_DURUM_SECENEKLERI
        .filter(d => d.kod !== 'DEVAM' || cur === 'DEVAM')
        .map(d => `<option value="${d.kod}" ${cur === d.kod ? 'selected' : ''}>${pdfEsc(d.label)}</option>`)
        .join('');
    const meta = siparisDurumMeta(cur);
    return `<select class="siparis-durum-sel" data-siparis-id="${pdfEsc(String(siparisId))}"
        title="Sipariş durumu — iş sırası"
        onclick="event.stopPropagation()"
        onmousedown="event.stopPropagation()"
        onchange="siparisListeDurumDegistir('${String(siparisId).replace(/'/g, "\\'")}', this.value, this)"
        style="appearance:auto;cursor:pointer;font-size:${compact ? '8px' : '9px'};font-weight:800;padding:${compact ? '2px 4px' : '3px 6px'};border-radius:999px;border:1px solid ${meta.renk}55;background:${meta.renk}22;color:${meta.renk};max-width:${compact ? '110px' : '130px'};font-family:'DM Mono',monospace;line-height:1.2">
        ${optsHtml}
    </select>`;
}

async function siparisListeDurumDegistir(siparisId, yeniDurum, selEl) {
    const sid = String(siparisId || '');
    const durum = siparisDurumNorm(yeniDurum);
    if (!sid || !durum) return;
    const sip = (dataCache.siparisler || []).find(s => String(s.id) === sid);
    const onceki = siparisDurumNorm(sip?.durum);
    if (onceki === durum) return;
    /* Kapalıdan (Tamamlandı / İptal) çıkış = geri alma — yalnız yönetici */
    const geriAcma = siparisKapaliMi(onceki) && durum !== onceki;
    if (geriAcma) {
        if (!siparisGeriAcYetkiliMi()) {
            if (selEl) selEl.value = onceki;
            erpToast('Kapanan siparişi yalnız yönetici geri alabilir.', 'error', 5000);
            return;
        }
        if (!confirm(`${sip?.sno || 'Bu sipariş'} geri alınsın mı?\n\n"${siparisDurumMeta(durum).label}" durumuna döner ve açık siparişler listesine geçer; geri alan kişi işlem geçmişine yazılır.`)) {
            if (selEl) selEl.value = onceki;
            return;
        }
    }
    if (durum === 'İPTAL' && !geriAcma) {
        if (!confirm(`${sip?.sno || 'Bu sipariş'} İPTAL edilsin mi?\n\nKapanan siparişler listesine üstü çizili olarak taşınır; açık listelerde, uyarılarda ve planlamada görünmez. İptal eden kişi işlem geçmişine yazılır; yönetici geri alabilir.`)) {
            if (selEl) selEl.value = onceki;
            return;
        }
    }
    if (durum === 'TAMAMLANDI' && onceki !== 'TAMAMLANDI') {
        if (!confirm('Sipariş TAMAMLANDI olarak işaretlensin mi?\n\nKapalı siparişler üretim listelerinde varsayılan olarak gizlenir.')) {
            if (selEl) selEl.value = onceki;
            return;
        }
    }
    try {
        if (typeof sb === 'undefined' || !sb?.from) throw new Error('Bağlantı yok');
        /* TAMAMLANDI'ya geçişte kapatma kaydı düşülür: kim, ne zaman. updated_by "kayda en son
           yazan" demek olduğu için tek başına kapatanı göstermez (bkz. siparisKapanisBilgiOku). */
        const yama = { durum };
        if (durum === 'TAMAMLANDI' && onceki !== 'TAMAMLANDI') {
            const eski = String(sip?.islem_gecmisi || '');
            yama.islem_gecmisi = (eski ? eski + '\n' : '') + siparisKapanisSatiriOlustur(null, onceki);
            if (typeof currentUser !== 'undefined' && currentUser) yama.updated_by = currentUser;
        }
        if (durum === 'İPTAL' && !geriAcma) {
            const eski = String(sip?.islem_gecmisi || '');
            yama.islem_gecmisi = (eski ? eski + '\n' : '') + siparisIptalSatiriOlustur(null, onceki);
            if (typeof currentUser !== 'undefined' && currentUser) yama.updated_by = currentUser;
        }
        if (geriAcma) {
            const eski = String(sip?.islem_gecmisi || '');
            yama.islem_gecmisi = (eski ? eski + '\n' : '') + siparisGeriAcmaSatiriOlustur(durum);
            if (typeof currentUser !== 'undefined' && currentUser) yama.updated_by = currentUser;
        }
        const { error } = await sb.from('siparisler').update(yama).eq('id', sid);
        if (error) throw error;
        if (sip) {
            sip.durum = durum;
            if (yama.islem_gecmisi) sip.islem_gecmisi = yama.islem_gecmisi;
            if (yama.updated_by) sip.updated_by = yama.updated_by;
        }
        const idx = (dataCache.siparisler || []).findIndex(s => String(s.id) === sid);
        if (idx >= 0) dataCache.siparisler[idx].durum = durum;
        if (selEl) {
            const meta = siparisDurumMeta(durum);
            selEl.style.borderColor = meta.renk + '55';
            selEl.style.background = meta.renk + '22';
            selEl.style.color = meta.renk;
        }
        erpToast(`${sip?.sno || sid}: ${siparisDurumMeta(durum).label}`, 'success', 2200);
        // Sayaç / filtre güncel kalsın
        if (appMode === 'SIPARIS_LISTE' || appMode === 'SIPARIS_KAPANAN') {
            debounce('siparisDurumListeYenile', () => loadData(), 400);
        }
    } catch (e) {
        if (selEl) selEl.value = onceki;
        erpToast('Durum kaydedilemedi: ' + (e?.message || e), 'error', 4000);
    }
}

function siparisFormSiparisDurumUiSync() {
    const kapat = document.getElementById('siparis-kapat-wrap');
    const tamBanner = document.getElementById('siparis-tamamlandi-banner');
    if (appMode !== 'SIPARIS_GIRIS') return;
    const d = siparisDurumNorm(siparisFormKayitDurum);
    const isEdit = !!editingId;
    if (isEdit && d === 'TAMAMLANDI') {
        if (kapat) kapat.style.display = 'none';
        if (tamBanner) tamBanner.style.display = 'block';
        return;
    }
    /* İptal de kapalı: formdan durum değiştirilemez — geri alma yalnız yönetici (Kapanan listesi, Geri al) */
    if (isEdit && d === 'İPTAL') {
        if (kapat) kapat.style.display = 'none';
        if (tamBanner) tamBanner.style.display = 'none';
        return;
    }
    if (kapat) kapat.style.display = isEdit ? 'block' : 'none';
    if (tamBanner) tamBanner.style.display = 'none';
}

async function siparisFormSiparisiTamamla() {
    if (!editingId) return alert('Önce sipariş listesinden kaydı düzenlemek için açın.');
    if (siparisFormKayitDurum === 'TAMAMLANDI') return alert('Bu sipariş zaten tamamlanmış.');
    if (!confirm('Sipariş TAMAMLANDI olarak kapatılsın mı?\n\nKapalı siparişler üretim listelerinde varsayılan olarak görünmez. Bu işlem yalnızca sipariş formundan yapılır.')) return;
    if (typeof sb === 'undefined' || !sb.from) return alert('Bağlantı hazır değil.');
    /* Fason ürün ağacı: fasonda kalan malzemeye karar (iade bekleniyor / fire say) — 22-fason-agac-foy.js */
    const kapanacakId = editingId;
    if (typeof fasonAgacKapamaKararSor === 'function' && !(await fasonAgacKapamaKararSor(kapanacakId))) return;
    if (String(editingId) !== String(kapanacakId)) return alert('Form değişti; sipariş kapatılmadı.');
    const mevcut = (dataCache.siparisler || []).find(s => String(s.id) === String(editingId));
    const kapanisLog = (String(mevcut?.islem_gecmisi || '') ? String(mevcut.islem_gecmisi) + '\n' : '') + siparisKapanisSatiriOlustur(null, mevcut?.durum);
    const yama = { durum: 'TAMAMLANDI', islem_gecmisi: kapanisLog };
    if (typeof currentUser !== 'undefined' && currentUser) yama.updated_by = currentUser;
    const { error } = await sb.from('siparisler').update(yama).eq('id', editingId);
    if (error) return alert('Hata: ' + error.message);
    const idx = (dataCache.siparisler || []).findIndex(s => String(s.id) === String(editingId));
    if (idx !== -1) {
        dataCache.siparisler[idx].durum = 'TAMAMLANDI';
        dataCache.siparisler[idx].islem_gecmisi = kapanisLog;
        if (yama.updated_by) dataCache.siparisler[idx].updated_by = yama.updated_by;
    }
    if (originalRecordSnapshot) originalRecordSnapshot = { ...originalRecordSnapshot, durum: 'TAMAMLANDI' };
    siparisFormKayitDurum = 'TAMAMLANDI';
    siparisFormSiparisDurumUiSync();
    alert('Sipariş tamamlandı.');
}

