        desen_kodu:'Desen Kodu', desen_adi:'Desen Adı', urun_adi:'Ürün Adı',
        kumas_cinsi:'Kumaş Cinsi', ana_grup:'Ana Grup',
        // Kumaş teknik
        tarak_no:'Tarak No', tarak_eni:'Tarak Eni (cm)', atki_sikligi:'Atkı Sıklığı',
        cozgu_no:'Çözgü No', cozgu_cinsi:'Çözgü Cinsi',
