function erpEscapeHtml(t) {
    const d = document.createElement('div');
    d.textContent = t == null ? '' : String(t);
    return d.innerHTML;
}
function erpAttr(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/"/g, '&quot;');
}
/** onclick="fn('...')" gibi satır içi handler'lara güvenli metin gömer. */
function erpJsStr(s) {
    return String(s == null ? '' : s)
        .replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")
        .replace(/"/g, '&quot;')
        .replace(/</g, '\\x3c');
}

// ── Kullanıcı yönetimi: sol liste + sağ detay ──────────────
let erpAdminDurum = {
    kullanicilar: [],
    secili: '',
    arama: '',
    yeniMod: false,
    silmeYok: false
};

function erpAdminBasHarf(u) {
    const ad = String(u?.display_name || u?.username || '?').trim();
    const p = ad.split(/\s+/).filter(Boolean);
    return (p.length >= 2 ? p[0][0] + p[1][0] : ad.slice(0, 2)).toUpperCase();
}

/** Miras kuralları dahil, gerçekten açılabilen ekran sayısı. */
function erpAdminAcikSayisi(modes) {
    return ERP_PERM_MODES.filter(([kod]) => erpModeAcikMi(kod, modes, false)).length;
}

/** Satırda gösterilecek "hangi bölümler açık" özeti. */
function erpAdminGrupOzeti(modes) {
    return ERP_PERM_GROUP_DEFS
        .filter(g => g.kodlar.some(kod => modes.includes(kod)))
        .map(g => g.ad);
}

function erpAdminKullaniciBul(un) {
    const k = String(un || '').toLowerCase();
    return erpAdminDurum.kullanicilar.find(u => String(u.username || '').toLowerCase() === k) || null;
}

// ── Yetki çipleri ──
function erpAdminYetkiHtml(modes, inputClass) {
    const etiketler = Object.fromEntries(ERP_PERM_MODES);
    return ERP_PERM_GROUP_DEFS.map(g => {
        const cipler = g.kodlar.map(kod => {
            const secili = modes.includes(kod);
            const oto = !secili && erpModeAcikMi(kod, modes, false);
            const sinif = 'kya-chip' + (secili ? ' kya-chip--on' : (oto ? ' kya-chip--oto' : ''));
            return `<label class="${sinif}">
                <input type="checkbox" class="${inputClass}" value="${erpAttr(kod)}" ${secili ? 'checked' : ''} onchange="erpAdminYetkiDegisti(this)">
                <span>${erpEscapeHtml(etiketler[kod] || kod)}</span>
                <span class="kya-chip__oto" style="${oto ? '' : 'display:none'}">oto</span>
            </label>`;
        }).join('');
        const acik = g.kodlar.filter(kod => erpModeAcikMi(kod, modes, false)).length;
        return `<div class="kya-grp">
            <div class="kya-grp__head">
                <span class="kya-grp__ad">${g.ikon} ${erpEscapeHtml(g.ad)}
                    <span class="kya-grp__sayi" data-kya-grpsayi="${g.id}">${acik}/${g.kodlar.length}</span>
                </span>
                <span style="display:flex;gap:5px">
                    <button type="button" class="kya-mini" onclick="erpAdminGrupTumu(this,'${g.id}',true)">Tümü</button>
                    <button type="button" class="kya-mini" onclick="erpAdminGrupTumu(this,'${g.id}',false)">Temizle</button>
                </span>
            </div>
            <div class="kya-grp__items">${cipler}</div>
        </div>`;
    }).join('');
}

/** Bir kutu değişince çip renklerini, grup sayaçlarını ve toplamı tazeler. */
function erpAdminYetkiTazele(kok) {
    if (!kok) return;
    const sinif = kok.getAttribute('data-kya-input') || 'kya-chk';
    const kutular = [...kok.querySelectorAll('input.' + sinif)];
    const secili = kutular.filter(k => k.checked).map(k => k.value);

    kutular.forEach(k => {
        const cip = k.closest('.kya-chip');
        if (!cip) return;
        const oto = !k.checked && erpModeAcikMi(k.value, secili, false);
        cip.classList.toggle('kya-chip--on', k.checked);
        cip.classList.toggle('kya-chip--oto', oto);
        const rozet = cip.querySelector('.kya-chip__oto');
        if (rozet) rozet.style.display = oto ? '' : 'none';
    });

    ERP_PERM_GROUP_DEFS.forEach(g => {
        const el = kok.querySelector(`[data-kya-grpsayi="${g.id}"]`);
        if (el) el.textContent = `${g.kodlar.filter(kod => erpModeAcikMi(kod, secili, false)).length}/${g.kodlar.length}`;
    });

    const toplam = kok.querySelector('[data-kya-toplam]');
    if (toplam) toplam.textContent = `${erpAdminAcikSayisi(secili)} / ${ERP_PERM_MODES.length} ekran açık`;
}

function erpAdminYetkiDegisti(cb) {
    erpAdminYetkiTazele(cb.closest('[data-kya-input]'));
}

function erpAdminGrupTumu(btn, grupId, ac) {
    const kok = btn.closest('[data-kya-input]');
    const g = ERP_PERM_GROUP_DEFS.find(x => x.id === grupId);
    if (!kok || !g) return;
    const sinif = kok.getAttribute('data-kya-input');
    g.kodlar.forEach(kod => {
        const inp = kok.querySelector(`input.${sinif}[value="${CSS.escape(kod)}"]`);
        if (inp) inp.checked = ac;
    });
    erpAdminYetkiTazele(kok);
}

function erpAdminHepsi(btn, ac) {
    const kok = btn.closest('[data-kya-input]');
    if (!kok) return;
    kok.querySelectorAll('input.' + kok.getAttribute('data-kya-input')).forEach(i => { i.checked = ac; });
    erpAdminYetkiTazele(kok);
}

function erpAdminSablon(sel) {
    const kok = sel.closest('[data-kya-input]');
    const s = ERP_PERM_SABLONLAR.find(x => x.id === sel.value);
    sel.value = '';
    if (!kok || !s) return;
    kok.querySelectorAll('input.' + kok.getAttribute('data-kya-input')).forEach(i => {
        i.checked = s.kodlar.includes(i.value);
    });
    erpAdminYetkiTazele(kok);
}

// ── Çizim ──
async function renderKullaniciYonetimi() {
    const list = document.getElementById('main-list');
    if (!list) return;
    if (!erpCurrentUser || erpCurrentUser.role !== 'admin') {
        list.innerHTML = '<div class="panel-box" style="padding:1.25rem 1.5rem">Bu bölüme yalnızca yönetici erişebilir.</div>';
        return;
    }
    list.innerHTML = '<div style="padding:2rem;color:var(--text3);font-size:12px">Yükleniyor…</div>';

    const { data, error } = await sb.rpc('erp_admin_users_list', { p_token: erpGetToken() });
    if (error || !data || !data.ok) {
        list.innerHTML = `<div class="panel-box" style="padding:1.25rem 1.5rem;color:#f87171">Liste alınamadı: ${erpEscapeHtml(error?.message || data?.err || 'bilinmiyor')}</div>`;
        return;
    }
    let users = data.users;
    if (typeof users === 'string') { try { users = JSON.parse(users); } catch (e) { users = []; } }
    erpAdminDurum.kullanicilar = Array.isArray(users) ? users : [];

    if (!erpAdminKullaniciBul(erpAdminDurum.secili)) {
        erpAdminDurum.secili = erpAdminDurum.kullanicilar[0]?.username || '';
    }
    erpAdminCiz();
    /* Satırlarda çevrimiçi / son görülme / son giriş (17-aktif) — ekran açıkken tazelenir */
    if (typeof erpAktifPanelBaslat === 'function') erpAktifPanelBaslat();
}

function erpAdminCiz() {
    const list = document.getElementById('main-list');
    if (!list) return;
    list.innerHTML = `
    <div class="kya-wrap">
        <div class="kya-panel">
            <div class="kya-panel__head" style="flex-direction:column;align-items:stretch;gap:8px">
                <div style="display:flex;align-items:center;justify-content:space-between;gap:8px">
                    <span class="kya-panel__title">Kullanıcılar</span>
                    <button type="button" class="kya-mini" onclick="erpAdminYeniAc()">+ Yeni</button>
                </div>
                <input class="kya-search" type="text" placeholder="Ara: ad veya kullanıcı adı"
                       value="${erpAttr(erpAdminDurum.arama)}" oninput="erpAdminAra(this.value)">
            </div>
            <div class="kya-list" id="kya-liste"></div>
        </div>
        <div class="kya-panel" id="kya-detay"></div>
    </div>`;
    erpAdminListeCiz();
    erpAdminDetayCiz();
}

function erpAdminListeCiz() {
    const kap = document.getElementById('kya-liste');
    if (!kap) return;
    const ara = erpAdminDurum.arama.trim().toLocaleLowerCase('tr-TR');
    const liste = erpAdminDurum.kullanicilar.filter(u => {
        if (!ara) return true;
        return String(u.username || '').toLocaleLowerCase('tr-TR').includes(ara)
            || String(u.display_name || '').toLocaleLowerCase('tr-TR').includes(ara);
    });

    if (!liste.length) {
        kap.innerHTML = '<div class="kya-bos">Eşleşen kullanıcı yok.</div>';
        return;
    }

    kap.innerHTML = liste.map(u => {
        const un = u.username || '';
        const yonetici = u.role === 'admin';
        const pasif = u.active === false;
        const modlar = erpNormalizeAllowedModes(u.allowed_modes);
        const ozet = yonetici ? 'Tüm ekranlar' : (erpAdminGrupOzeti(modlar).join(' · ') || 'Yetki verilmemiş');
        const secili = String(erpAdminDurum.secili || '').toLowerCase() === un.toLowerCase();
        return `<div class="kya-row${secili ? ' kya-row--on' : ''}${pasif ? ' kya-row--pasif' : ''}" onclick="erpAdminSec('${erpJsStr(un)}')">
            <div class="kya-av">${erpEscapeHtml(erpAdminBasHarf(u))}</div>
            <div class="kya-row-main">
                <div class="kya-row-name">${erpEscapeHtml(u.display_name || un)}</div>
                <div class="kya-row-sub">${erpEscapeHtml(un)} · ${yonetici ? 'tümü' : erpAdminAcikSayisi(modlar) + ' ekran'}</div>
                <div class="kya-row-sub" style="color:var(--text3);opacity:.8">${erpEscapeHtml(ozet)}</div>
                ${typeof erpAktifKyaHtml === 'function' ? erpAktifKyaHtml(un) : ''}
            </div>
            <div style="display:flex;flex-direction:column;align-items:flex-end;gap:3px">
                <span class="kya-badge ${yonetici ? 'kya-badge--admin' : 'kya-badge--user'}">${u.kurucu === true ? '🔒 Kurucu' : yonetici ? 'Yönetici' : 'Kullanıcı'}</span>
                ${pasif ? '<span class="kya-badge kya-badge--pasif">Pasif</span>' : ''}
            </div>
        </div>`;
    }).join('');
}

function erpAdminDetayCiz() {
    const kap = document.getElementById('kya-detay');
    if (!kap) return;

    if (erpAdminDurum.yeniMod) { kap.innerHTML = erpAdminYeniHtml(); return; }

    const u = erpAdminKullaniciBul(erpAdminDurum.secili);
    if (!u) {
        kap.innerHTML = '<div class="kya-bos">Soldan bir kullanıcı seçin.</div>';
        return;
    }

    const un = u.username || '';
    const kendisi = un.toLowerCase() === String(erpCurrentUser.username || '').toLowerCase();
    const yonetici = u.role === 'admin';
    const modlar = erpNormalizeAllowedModes(u.allowed_modes);
    /* Kurucu hesap (erp_users.kurucu): rolü/aktifliği kimse değiştiremez, silinemez; şifre ve adı
       yalnız kendisi değiştirir. Asıl engel veritabanında (trg_erp_users_kurucu_koru) — burası bilgi. */
    const kurucu = u.kurucu === true;
    const kilitli = kurucu && !kendisi;
    const rolKilit = kendisi || kurucu;

    kap.innerHTML = `
    <div class="kya-detay" data-kya-input="kya-chk" data-kya-user="${erpAttr(un)}">
        ${kurucu ? `<div style="display:flex;gap:8px;align-items:flex-start;padding:9px 12px;margin-bottom:10px;border-radius:9px;border:1px solid rgba(245,158,11,0.35);background:rgba(245,158,11,0.08);font-size:11px;color:var(--text2)">
            <span style="font-size:14px;line-height:1">🔒</span>
            <span><b style="color:var(--text)">Kurucu hesap.</b> ${kendisi
                ? 'Rolünüz ve erişiminiz kimse tarafından (siz dahil) değiştirilemez; hesabınız silinemez. Şifrenizi ve adınızı yalnız siz değiştirebilirsiniz.'
                : 'Bu hesabın rolü, yetkileri, aktifliği, şifresi ve adı değiştirilemez; hesap silinemez. Yalnız hesabın sahibi kendi şifresini ve adını değiştirebilir.'}</span>
        </div>` : ''}
        <div class="kya-detay__head">
            <div style="display:flex;gap:11px;align-items:center;min-width:0">
                <div class="kya-av" style="width:40px;height:40px;flex:0 0 40px;border-radius:11px;font-size:13px">${erpEscapeHtml(erpAdminBasHarf(u))}</div>
                <div style="min-width:0">
                    <div class="kya-detay__ad">${erpEscapeHtml(u.display_name || un)}</div>
                    <div class="kya-detay__kadi">${erpEscapeHtml(un)}${kendisi ? ' · bu hesap sizsiniz' : ''}</div>
                </div>
            </div>
            <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">
                <select class="kya-inp" id="kya-rol" onchange="erpAdminRolDegisti(this)" ${rolKilit ? `disabled title="${kurucu ? 'Kurucu hesabın rolü değiştirilemez' : 'Kendi rolünüzü değiştiremezsiniz'}"` : ''}>
                    <option value="user" ${yonetici ? '' : 'selected'}>Kullanıcı</option>
                    <option value="admin" ${yonetici ? 'selected' : ''}>Yönetici</option>
                </select>
                <label class="kya-chip ${u.active !== false ? 'kya-chip--on' : ''}" id="kya-aktif-chip">
                    <input type="checkbox" id="kya-aktif" ${u.active !== false ? 'checked' : ''} ${rolKilit ? 'disabled' : ''}
                           onchange="document.getElementById('kya-aktif-chip').classList.toggle('kya-chip--on', this.checked)">
                    <span>Aktif</span>
                </label>
                ${kurucu ? '<span class="kya-badge kya-badge--admin" title="Kurucu hesap — kilitli">🔒 Kurucu</span>' : ''}
                ${kendisi || kurucu ? '' : `<button type="button" class="kya-mini" style="color:#fca5a5;border-color:rgba(248,113,113,0.35)" onclick="erpAdminSil('${erpJsStr(un)}')">Sil</button>`}
            </div>
        </div>

        <div class="kya-alan">
            <div class="kya-alan__baslik">Görünen ad</div>
            <input class="kya-inp" id="kya-ad" type="text" style="width:100%;max-width:320px" value="${erpAttr(u.display_name || '')}" ${kilitli ? 'disabled title="Kurucu hesabın adını yalnız kendisi değiştirebilir"' : ''}>
        </div>

        <div class="kya-alan" id="kya-yetki-alan" style="${yonetici ? 'display:none' : ''}">
            <div class="kya-alan__baslik">
                <span>Erişebileceği ekranlar — <span data-kya-toplam>${erpAdminAcikSayisi(modlar)} / ${ERP_PERM_MODES.length} ekran açık</span></span>
                <span style="display:flex;gap:5px;align-items:center">
                    <select class="kya-inp" style="font-size:9px;padding:3px 6px" onchange="erpAdminSablon(this)">
                        <option value="">Hazır profil seç…</option>
                        ${ERP_PERM_SABLONLAR.map(s => `<option value="${s.id}">${erpEscapeHtml(s.ad)}</option>`).join('')}
                    </select>
                    <button type="button" class="kya-mini" onclick="erpAdminHepsi(this,true)">Hepsi</button>
                    <button type="button" class="kya-mini" onclick="erpAdminHepsi(this,false)">Hiçbiri</button>
                </span>
            </div>
            ${erpAdminYetkiHtml(modlar, 'kya-chk')}
            <div style="font-size:9px;color:var(--text3);margin-top:2px">
                <span style="color:#6ee7b7;font-weight:700">oto</span> işaretli ekranlar, üstündeki bir yetki sayesinde zaten açık olanlardır.
            </div>
        </div>

        ${kilitli ? '' : `<div class="kya-alan" ${yonetici ? '' : 'style="border-top:1px solid var(--border);padding-top:12px"'}>
            <div class="kya-alan__baslik">Şifre sıfırla</div>
            <div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap">
                <input class="kya-inp" id="kya-sifre" type="password" autocomplete="new-password" placeholder="Yeni şifre (en az 8 karakter)" style="width:220px">
                <button type="button" class="kya-mini" onclick="erpAdminSifre('${erpJsStr(un)}')">Şifreyi değiştir</button>
            </div>
        </div>`}

        <div class="kya-alt">
            <span class="kya-canli"><span class="kya-canli__nokta"></span>${kilitli ? 'Kurucu hesap — değişiklik yapılamaz' : 'Kaydettiğiniz an kullanıcının ekranına yansır'}</span>
            <span style="display:flex;gap:10px;align-items:center">
                <span class="kya-durum" id="kya-durum"></span>
                ${kilitli ? '' : `<button type="button" class="wizard-nav-btn" style="padding:7px 18px;font-size:10px" onclick="erpAdminKaydet('${erpJsStr(un)}')">Kaydet</button>`}
            </span>
        </div>
    </div>`;
}

