/** Sevkiyat mamül hareketlerini sipariş için DB'den çekip dataCache'e ekle (özet/durum depo köprüsü). */
async function sevkiyatSiparisDepoHareketleriYukle(siparisId) {
    const sid = String(siparisId || '').trim();
    if (!sid || typeof sb === 'undefined' || !sb) return [];
    const sip = (dataCache.siparisler || []).find(s => String(s.id) === sid);
    const sno = String(sip?.sno || '').trim();
    /* Kolonlar kumas_stok semasindan birebir. Onceki listede urun_adi, renk,
       ebat, ana_grup vardi; bu kolonlar tabloda olmadigi icin bes sorgu da
       400 donuyor ve fonksiyon her zaman bos liste veriyordu. */
    const cols = 'id,created_at,stok_kodu,kumas_cinsi,kumas_rengi,lot_no,cuval_sayisi,miktar_kg,miktar_mt,islem_turu,kaynak_birim,notlar,firma,updated_by,siparis_id,kalem_idx,siparis_sno';
    const seen = new Set();
    const out = [];
    const pushRows = (arr) => {
        (arr || []).forEach((r) => {
            const id = r?.id != null ? String(r.id) : '';
            if (id && seen.has(id)) return;
            if (id) seen.add(id);
            out.push(r);
        });
    };
    /* Bes sorgu birbirinden bagimsiz; sirali beklemek sipariş durum ekranini
       bes tam gidis-gelis geciktiriyordu. Tek turda calisir, pushRows sirasi
       (dolayisiyla tekillestirme onceligi) q1..q4 olarak korunur. */
    const sorgular = [
        /* Siparise bagli hareketler artik kumas_stok.siparis_id ile isaretli —
           notlar icinde metin aramaya gore kesin ve indeksli. */
        sb.from('kumas_stok').select(cols).eq('siparis_id', sid).limit(800),
        sb.from('kumas_stok').select(cols).ilike('notlar', `%SEVK_GRID:${sid}|%`).limit(800),
        sb.from('kumas_stok').select(cols).ilike('notlar', `%SEVK_MERKEZ_ADET:sip=${sid}|%`).limit(400)
    ];
    if (sno) {
        sorgular.push(
            sb.from('kumas_stok').select(cols).eq('lot_no', sno).ilike('kaynak_birim', 'DEPO_HAREKET_MAMUL%').limit(800),
            sb.from('kumas_stok').select(cols).eq('lot_no', sno).ilike('kaynak_birim', 'DEPO_HAREKET_KUMAS%').limit(800),
            sb.from('kumas_stok').select(cols).ilike('stok_kodu', `SIP-${sno}-K%`).limit(400)
        );
    }
    let sonuclar = [];
    try {
        sonuclar = await Promise.all(sorgular.map(q => Promise.resolve(q).catch(e => ({ error: e }))));
    } catch (e) { console.warn('sevkiyat depo hareketleri', e); }
    sonuclar.forEach((r) => { if (r && !r.error) pushRows(r.data); });
    if (!out.length) return [];
    if (!Array.isArray(dataCache.kumas_stok)) dataCache.kumas_stok = [];
    const have = new Set((dataCache.kumas_stok || []).map(r => String(r?.id || '')).filter(Boolean));
    out.forEach((r) => {
        const id = r?.id != null ? String(r.id) : '';
        if (!id) {
            dataCache.kumas_stok.unshift(r);
            return;
        }
        const ix = dataCache.kumas_stok.findIndex(x => String(x?.id) === id);
        if (ix >= 0) {
            dataCache.kumas_stok[ix] = { ...dataCache.kumas_stok[ix], ...r };
        } else {
            dataCache.kumas_stok.unshift(r);
        }
        have.add(id);
    });
    return out;
}
try { window.sevkiyatSiparisDepoHareketleriYukle = sevkiyatSiparisDepoHareketleriYukle; } catch (e) {}

/** Operasyon günlüğü KONF_SEVK / SEVK — kalem mutlak yükleme (toplam_sevk) veya delta toplamı. */
/* Raporlar tüm siparişlerin SEVK / KONF_SEVK günlük satırlarını tek sorguda yükleyip buraya
   yazar. Sipariş günlüğü (_konfIslemLogCache) yalnız pencere açılınca yüklendiği için, açılmamış
   siparişte yükleme sayısı eksik çıkıyordu (28.09.2026: SP360 günlük 176 · hesap 0). */
let _sevkAkisTopluIndeks = null;   // sid → SEVK / KONF_SEVK satırları
function sevkAkisTopluIndeksYaz(satirlar) {
    const m = new Map();
    (satirlar || []).forEach((r) => {
        const iso = String(r.islem || '').toUpperCase().replace(/İ/g, 'I');
        if (iso !== 'KONF_SEVK' && iso !== 'SEVK') return;
        const k = String(r.siparis_id);
        if (!m.has(k)) m.set(k, []);
        m.get(k).push(r);
    });
    _sevkAkisTopluIndeks = m;
}

function sevkiyatSiparisKalemYuklemeFromAkis(siparisId, kalemIdx) {
    const sid = String(siparisId || '').trim();
    const ki = parseInt(kalemIdx, 10);
    if (!sid || !Number.isFinite(ki) || ki < 0) return 0;
    const rows = (typeof _konfIslemLogCache !== 'undefined' && _konfIslemLogCache[sid])
        ? _konfIslemLogCache[sid]
        : ((_sevkAkisTopluIndeks && _sevkAkisTopluIndeks.get(sid)) || []);
    let kalemler = null;   // satır başına yeniden ayrıştırılmasın (Raporlar'da 5.776 çağrı, ~270 ms)
    /* "kesin_toplam" satırı (depo hareketi düzeltmesi, 06.10.2026): sevk o satırdaki toplama İNER;
       ondan önceki daha büyük toplamlar sayılmaz (yoksa düzeltilen 246 → 216 yine 246 görünürdü). */
    const adaylar = [];
    let kesinMs = -1;
    for (let i = 0; i < rows.length; i++) {
        const r = rows[i];
        if (typeof konfAkisSatirSilindiMi === 'function' && konfAkisSatirSilindiMi(r)) continue;
        const iso = String(r.islem || '').toUpperCase().replace(/İ/g, 'I');
        if (iso !== 'KONF_SEVK' && iso !== 'SEVK') continue;
        let j = r.not_json;
        if (!j || typeof j !== 'object') {
            try { j = JSON.parse(r.notlar || '{}') || {}; } catch (e) { j = {}; }
        }
        const meta = (typeof konfPipelineKalemMeta === 'function')
            ? konfPipelineKalemMeta(sid, j, r.kalem_ad, kalemler || (kalemler = konfGetSiparisKalemlerById(sid)))
            : { idx: parseInt(j.kalem_idx, 10) };
        if (Number(meta.idx) !== ki) continue;
        const toplam = parseInt(j.toplam_sevk, 10);
        const ms = Date.parse(r.created_at || j.ts || '') || 0;
        if (j.kesin_toplam && Number.isFinite(toplam) && ms >= kesinMs) kesinMs = ms;
        adaylar.push({ ms, toplam: Number.isFinite(toplam) && toplam >= 0 ? Math.round(toplam) : null, delta: Math.round(parseFloat(r.miktar) || 0) });
    }
    let maxAbs = 0;
    let deltaSum = 0;
    for (let i = 0; i < adaylar.length; i++) {
        const a = adaylar[i];
        if (a.ms < kesinMs) continue;
        if (a.toplam != null) maxAbs = Math.max(maxAbs, a.toplam);
        else deltaSum += a.delta;
    }
    /* Kesin satırdan sonra toplamsız (eski biçim) satırlar: kesin toplamın üstüne eklenir */
    if (kesinMs >= 0 && deltaSum) {
        const kesin = adaylar.find(a => a.ms === kesinMs && a.toplam != null);
        deltaSum += kesin ? kesin.toplam : 0;
    }
    return Math.max(0, maxAbs, Math.round(deltaSum));
}
try { window.sevkiyatSiparisKalemYuklemeFromAkis = sevkiyatSiparisKalemYuklemeFromAkis; } catch (e) {}

/** Sevkiyat Merkezi depo hareketlerinden (kumas_stok) kalem yükleme toplamı.
 * Mamül = adet (cuval); kumaş MT/KG kalem = metre (veya kg). Sipariş durum / özet buradan da okur. */
function sevkiyatSipStokKodEslesir(stokKodu, sipStok) {
    const s = String(stokKodu || '').trim().toUpperCase();
    const p = String(sipStok || '').trim().toUpperCase();
    if (!s || !p) return false;
    if (s === p) return true;
    return s.startsWith(p + '-');
}

/** Aynı siparişte bu ürün adı bu birim grubunda tek kalemde mi? */
function sevkiyatSiparisKalemAdTekilMi(kalemler, kalemIdx, kumasKalem) {
    const hedef = String((kalemler || [])[kalemIdx]?.ad || (kalemler || [])[kalemIdx]?.urun || '').trim().toUpperCase();
    if (!hedef) return false;
    let n = 0;
    (kalemler || []).forEach((k) => {
        const b = (typeof siparisKalemBirim === 'function' ? siparisKalemBirim(k) : String(k?.birim || 'ADET')).toUpperCase();
        const buKumas = b === 'MT' || b === 'KG' || b === 'M' || b === 'METRE';
        if (!!kumasKalem !== buKumas) return;
        if (String(k.ad || k.urun || '').trim().toUpperCase() === hedef) n++;
    });
    return n === 1;
}

/* Depo satırının bu hesapta kullanılan normalleştirilmiş hali — her kalem çağrısında tüm satırları
   yeniden büyük harfe çevirmek 88 siparişte ~400 ms tutuyordu. Kaynak alan değişince yeniden hesaplanır. */
const _sevkDepoSatirNormCache = new WeakMap();
const SEVK_DEPO_SATIR_ALANLARI = ['notlar', 'kaynak_birim', 'ana_grup', 'stok_kodu', 'lot_no', 'islem_turu',
    'miktar_mt', 'miktar_kg', 'cuval_sayisi', 'urun_adi', 'kumas_cinsi'];
function sevkiyatDepoSatirNorm(r) {
    const eski = _sevkDepoSatirNormCache.get(r);
    if (eski) {
        let ayni = true;
        for (let a = 0; a < SEVK_DEPO_SATIR_ALANLARI.length; a++) {
            const alan = SEVK_DEPO_SATIR_ALANLARI[a];
            if (eski.kaynak[alan] !== r[alan]) { ayni = false; break; }
        }
        if (ayni) return eski;
    }
    const kaynak = {};
    SEVK_DEPO_SATIR_ALANLARI.forEach(alan => { kaynak[alan] = r[alan]; });
    const not = String(r.notlar || '');
    const lot = String(r.lot_no || '').trim();
    const tip = String(r.islem_turu || '').toUpperCase()
        .replace(/İ/g, 'I').replace(/Ç/g, 'C').replace(/Ş/g, 'S');
    const n = {
        kaynak,
        not,
        kb: String(r.kaynak_birim || '').toUpperCase(),
        ana: String(r.ana_grup || '').toUpperCase(),
        stokKodu: String(r.stok_kodu || '').trim().toUpperCase(),
        lot,
        lotIlk: lot.split(',')[0].trim(),
        isCikis: tip.includes('CIKIS'),
        isGiris: tip.includes('GIRIS'),
        tagged: /SEVK_KUMAS:sip=|SEVK_GRID:|SEVK_MERKEZ_ADET:sip=/i.test(not),
        urun: String(r.urun_adi || r.kumas_cinsi || '').trim().toUpperCase(),
        mt: Math.abs(parseFloat(r.miktar_mt) || 0),
        kg: Math.abs(parseFloat(r.miktar_kg) || 0),
        signedMt: parseFloat(r.miktar_mt) || 0,
        signedKg: parseFloat(r.miktar_kg) || 0,
        cuval: parseInt(r.cuval_sayisi, 10) || 0
    };
    _sevkDepoSatirNormCache.set(r, n);
    return n;
}

/* Aday satır indeksi: bir kaleme ancak kendi sipariş etiketiyle, stok koduyla (tam ya da "KOD-…" öneki)
   ya da lot = sipariş no ile eşleşen satır sayılabilir; indeks bu üç anahtarın üst kümesini verir,
   kesin eşleşme yine aşağıdaki kurallarla yapılır. Satır nesnesi değişince (canlı güncelleme) yenilenir. */
const _sevkDepoIdx = { refs: null, bySid: null, byStok: null, byLot: null };
function sevkiyatDepoIndeks(rows) {
    const idx = _sevkDepoIdx;
    let gecerli = !!idx.refs && idx.refs.length === rows.length;
    for (let i = 0; gecerli && i < rows.length; i++) if (rows[i] !== idx.refs[i]) gecerli = false;
    if (gecerli) return idx;
    idx.refs = rows.slice();
    idx.bySid = new Map();
    idx.byStok = new Map();
    idx.byLot = new Map();
    const ekle = (m, k, i) => {
        if (!k) return;
        let a = m.get(k);
        if (!a) m.set(k, a = []);
        if (a[a.length - 1] !== i) a.push(i);
    };
    const reEtiket = /(?:SEVK_KUMAS:sip=|SEVK_MERKEZ_ADET:sip=|SEVK_GRID:)([^|]*)\|/gi;
    for (let i = 0; i < rows.length; i++) {
        if (!rows[i]) continue;
        const n = sevkiyatDepoSatirNorm(rows[i]);
        if (n.tagged) {
            reEtiket.lastIndex = 0;
            let m;
            while ((m = reEtiket.exec(n.not))) ekle(idx.bySid, m[1].toUpperCase(), i);
        }
        const s = n.stokKodu;
        ekle(idx.byStok, s, i);
        for (let j = s.indexOf('-'); j > 0; j = s.indexOf('-', j + 1)) ekle(idx.byStok, s.slice(0, j), i);
        ekle(idx.byLot, n.lot, i);
        if (n.lotIlk !== n.lot) ekle(idx.byLot, n.lotIlk, i);
    }
    return idx;
}

function sevkiyatSiparisKalemYuklemeFromDepo(siparisId, kalemIdx) {
    let net = 0;
    sevkiyatSiparisKalemDepoHareketleri(siparisId, kalemIdx).forEach((h) => { net += h.yon * h.miktar; });
    return Math.max(0, Math.round(net));
}
try { window.sevkiyatSiparisKalemYuklemeFromDepo = sevkiyatSiparisKalemYuklemeFromDepo; } catch (e) {}

/**
 * Bir sipariş kalemine eşleşen depo hareketleri, satır satır: { row, miktar, yon }.
 * yon = +1 çıkış (sevk), −1 giriş (iade). Miktar kalemin biriminde (mamül: adet, kumaş: mt/kg).
 * Sipariş penceresinin yükleme sayısı (sevkiyatSiparisKalemYuklemeFromDepo) ve Raporlar'ın
 * tarihli sevk kayıtları AYNI eşleştirmeyi kullanır.
 */
function sevkiyatSiparisKalemDepoHareketleri(siparisId, kalemIdx) {
    const sid = String(siparisId || '').trim();
    const ki = parseInt(kalemIdx, 10);
    const out = [];
    if (!sid || !Number.isFinite(ki) || ki < 0) return out;
    const sip = (dataCache.siparisler || []).find(s => String(s.id) === sid);
    const sno = String(sip?.sno || '').trim();
    const kalemler = (typeof siparisListeKalemleriArr === 'function')
        ? siparisListeKalemleriArr(sip || {})
        : [];
    const k = kalemler[ki] || {};
    const birim = (typeof siparisKalemBirim === 'function' ? siparisKalemBirim(k) : String(k.birim || 'ADET')).toUpperCase();
    const kumasKalem = birim === 'MT' || birim === 'KG' || birim === 'M' || birim === 'METRE';
    const kodN = String(k.kod || '').trim().toUpperCase();
    const adN = String(k.ad || '').trim().toUpperCase();
    const sipStok = sno ? `SIP-${sno}-K${ki}`.toUpperCase() : '';
    const sidEsc = sid.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const reGrid = new RegExp(`SEVK_GRID:${sidEsc}\\|${ki}\\|`, 'i');
    const reMerkez = new RegExp(`SEVK_MERKEZ_ADET:sip=${sidEsc}\\|k=${ki}\\|`, 'i');
    const reKumas = new RegExp(`SEVK_KUMAS:sip=${sidEsc}\\|k=${ki}\\|`, 'i');
    const adTekil = sevkiyatSiparisKalemAdTekilMi(kalemler, ki, kumasKalem);
    const rows = (typeof dataCache !== 'undefined' && dataCache.kumas_stok) ? dataCache.kumas_stok : [];
    const idx = sevkiyatDepoIndeks(rows);
    const aday = [];
    const adayEkle = (liste) => { if (liste) for (let j = 0; j < liste.length; j++) aday.push(liste[j]); };
    adayEkle(idx.bySid.get(sid.toUpperCase()));
    if (sipStok) adayEkle(idx.byStok.get(sipStok));
    if (kodN) adayEkle(idx.byStok.get(kodN));
    if (sno) adayEkle(idx.byLot.get(sno));
    aday.sort((a, b) => a - b);
    for (let j = 0; j < aday.length; j++) {
        if (j && aday[j] === aday[j - 1]) continue;
        const n = sevkiyatDepoSatirNorm(rows[aday[j]]);
        const kb = n.kb;

        if (kumasKalem) {
            const kumasHareket = kb === 'DEPO_HAREKET_KUMAS' || kb.startsWith('DEPO_HAREKET_KUMAS')
                || kb === 'DEPO_HAREKET_HAM_KUMAS' || kb === 'KUMAS';
            if (!kumasHareket) continue;
            let esles = reKumas.test(n.not);
            if (!esles && !n.tagged) {
                if (sevkiyatSipStokKodEslesir(n.stokKodu, sipStok)) esles = true;
                else if (kodN && kodN !== 'KODSUZ' && n.stokKodu === kodN) esles = true;
                else if (adTekil && sno && (n.lot === sno || n.lotIlk === sno)) {
                    if (adN && n.urun === adN) esles = true;
                }
            }
            if (!esles) continue;
            const miktar = birim === 'KG' ? (n.kg || n.mt) : (n.mt || n.kg);
            if (!(miktar > 0)) continue;
            const signed = birim === 'KG' ? n.signedKg : n.signedMt;
            let yon;
            if (n.isCikis || signed < 0) yon = 1;
            else if (n.isGiris || signed > 0) yon = -1;
            else yon = signed < 0 ? 1 : -1;
            out.push({ row: rows[aday[j]], miktar, yon });
            continue;
        }

        const mamulHareket = kb === 'DEPO_HAREKET_MAMUL_DEPO' || kb.startsWith('DEPO_HAREKET_MAMUL')
            || n.ana === 'MAMUL' || kb === 'MAMUL_DEPO';
        if (!mamulHareket) continue;
        let esles = reGrid.test(n.not) || reMerkez.test(n.not);
        if (!esles && !n.tagged) {
            if (sevkiyatSipStokKodEslesir(n.stokKodu, sipStok)) esles = true;
            else if (kodN && kodN !== 'KODSUZ' && n.stokKodu === kodN) esles = true;
            else if (adTekil && sno && n.lot === sno) {
                if (adN && n.urun === adN) esles = true;
            }
        }
        if (!esles) continue;
        const ad = Math.abs(n.cuval);
        if (!ad) continue;
        const signed = n.cuval;
        let yon;
        if (n.isCikis || signed < 0) yon = 1;
        else if (n.isGiris || signed > 0) yon = -1;
        else yon = signed < 0 ? 1 : -1;
        out.push({ row: rows[aday[j]], miktar: ad, yon });
    }
    return out;
}
try { window.sevkiyatSiparisKalemDepoHareketleri = sevkiyatSiparisKalemDepoHareketleri; } catch (e) {}

/** Durum inceleme günlüğü: sevkiyat/depo çıkışları. Kullanıcı yalnız stok satırındaki updated_by. */
function siparisDurumDepoSevkGunlukSatirlari(siparis) {
    const sid = String(siparis?.id || '').trim();
    if (!sid) return [];
    const sno = String(siparis?.sno || '').trim();
    const kalemler = (typeof uaSiparisKalemleriGetir === 'function')
        ? (uaSiparisKalemleriGetir(siparis) || [])
        : [];
    const rows = (typeof dataCache !== 'undefined' && dataCache.kumas_stok) ? dataCache.kumas_stok : [];
    const out = [];
    const sidEsc = sid.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const reGrid = new RegExp(`SEVK_GRID:${sidEsc}\\|(\\d+)\\|`, 'i');
    const reMerkez = new RegExp(`SEVK_MERKEZ_ADET:sip=${sidEsc}\\|k=(\\d+)\\|`, 'i');
    const reKumas = new RegExp(`SEVK_KUMAS:sip=${sidEsc}\\|k=(\\d+)\\|`, 'i');
    const snoU = sno.toUpperCase();
    for (let i = 0; i < rows.length; i++) {
        const r = rows[i];
        const not = String(r?.notlar || '');
        const tip = String(r?.islem_turu || '').toUpperCase()
            .replace(/İ/g, 'I').replace(/Ç/g, 'C').replace(/Ş/g, 'S');
        if (!tip.includes('CIKIS')) continue;
        let ki = NaN;
        let esles = false;
        let gm = not.match(reGrid) || not.match(reMerkez) || not.match(reKumas);
        if (gm) {
            esles = true;
            ki = parseInt(gm[1], 10);
        }
        const stokKodu = String(r?.stok_kodu || '').trim().toUpperCase();
        if (!esles && sno && stokKodu.indexOf(`SIP-${snoU}-K`) === 0) {
            esles = true;
            const km = stokKodu.match(/-K(\d+)/i);
            if (km) ki = parseInt(km[1], 10);
        }
        if (!esles && sno && String(r?.lot_no || '').trim() === sno) {
            const kb = String(r?.kaynak_birim || '').toUpperCase();
            if (kb.includes('DEPO_HAREKET_MAMUL') || kb.includes('DEPO_HAREKET_KUMAS') || kb === 'MAMUL_DEPO' || kb === 'KUMAS') {
                esles = true;
            }
        }
        if (!esles) continue;
        const mt = Math.abs(parseFloat(r.miktar_mt) || 0);
        const kg = Math.abs(parseFloat(r.miktar_kg) || 0);
        const ad = Math.abs(parseInt(r.cuval_sayisi, 10) || 0);
        if (!(mt > 0 || kg > 0 || ad > 0)) continue;
        const k = Number.isFinite(ki) ? (kalemler[ki] || {}) : {};
        const user = String(r.updated_by || '').trim();
        /* Kumaş satırında cuval_sayisi top sayısıdır, adet değil ("305 top · 19.802 m") */
        const kumasSatiri = String(r.kaynak_birim || '').toUpperCase().includes('KUMAS') || reKumas.test(not);
        out.push({
            id: 'depo-sevk-' + String(r.id || i),
            islem: 'SEVK',
            ts: r.created_at,
            created_at: r.created_at,
            kalem_ad: k.ad || k.kod || r.urun_adi || r.kumas_cinsi || '—',
            kalem_idx: Number.isFinite(ki) ? ki : null,
            miktar: kumasSatiri ? (mt || kg || ad) : (ad || mt || kg),
            miktar_adet: kumasSatiri ? 0 : ad,
            miktar_top: kumasSatiri ? ad : 0,
            miktar_mt: mt,
            miktar_kg: kg,
            kullanici: user || '—',
            not: [r.firma, r.stok_kodu].filter(Boolean).join(' · '),
            not_json: { kaynak: 'depo_hareket', hareket_id: r.id },
            _kaynak: 'depo_sevk',
            _kaynak_id: String(r.id || '')
        });
    }
    return out;
}
try { window.siparisDurumDepoSevkGunlukSatirlari = siparisDurumDepoSevkGunlukSatirlari; } catch (e) {}

/** Kumaş çıkış payload → sipariş + kalem eşlemesi */
function sevkiyatKumasPayloadSiparisKalemCoz(p) {
    if (!p) return null;
    let sid = p.siparis_id != null ? String(p.siparis_id).trim() : '';
    let ki = parseInt(p.kalem_idx, 10);
    /* Stoktan siparişe sevk (19-stoktan-sevk): siparis_id boş (stoktan düşer), sipariş etiketten */
    if (!sid && typeof stoktanSevkHedefCoz === 'function') {
        const h = stoktanSevkHedefCoz(p.notlar);
        if (h) { sid = h.sid; ki = h.ki; }
    }
    const stok = String(p.stok_kodu || '').trim();
    const mSip = stok.match(/^SIP-([^-]+)-K(\d+)/i);
    if (mSip) {
        const sno = String(mSip[1] || '').trim();
        const sip = (dataCache.siparisler || []).find(s => String(s.sno || '').trim() === sno);
        if (sip?.id != null) sid = String(sip.id);
        if (!Number.isFinite(ki) || ki < 0) ki = parseInt(mSip[2], 10);
    }
    if ((!sid || !Number.isFinite(ki) || ki < 0)) {
        const sno = String(p.lot_no || p.siparis_sno || '').trim().split(',')[0].trim();
        if (sno) {
            const sip = (dataCache.siparisler || []).find(s => String(s.sno || '').trim() === sno);
            if (sip?.id != null) {
                sid = String(sip.id);
                if (!Number.isFinite(ki) || ki < 0) {
                    const kalemler = (typeof siparisListeKalemleriArr === 'function')
                        ? siparisListeKalemleriArr(sip)
                        : [];
                    const kodN = stok.toUpperCase();
                    const adN = String(p.urun_adi || p.kumas_cinsi || '').trim().toUpperCase();
                    let idx = kalemler.findIndex((k, i) => {
                        const b = (typeof siparisKalemBirim === 'function' ? siparisKalemBirim(k) : k.birim || '').toUpperCase();
                        if (b !== 'MT' && b !== 'KG') return false;
                        const kk = String(k.kod || '').trim().toUpperCase();
                        const ka = String(k.ad || '').trim().toUpperCase();
                        if (kk && (kk === kodN || kodN.includes(kk))) return true;
                        if (ka && adN && (ka === adN || adN.includes(ka) || ka.includes(adN.slice(0, 18)))) return true;
                        return false;
                    });
                    if (idx < 0 && kalemler.length === 1) {
                        const b = (typeof siparisKalemBirim === 'function' ? siparisKalemBirim(kalemler[0]) : '').toUpperCase();
                        if (b === 'MT' || b === 'KG') idx = 0;
                    }
                    ki = idx;
                }
            }
        }
    }
    if (!sid || !Number.isFinite(ki) || ki < 0) return null;
    const mt = Math.abs(parseFloat(p.miktar_mt) || 0);
    const kg = Math.abs(parseFloat(p.miktar_kg) || 0);
    const sip = (dataCache.siparisler || []).find(s => String(s.id) === sid);
    const kalem = ((typeof siparisListeKalemleriArr === 'function') ? siparisListeKalemleriArr(sip || {}) : [])[ki] || {};
    const birim = (typeof siparisKalemBirim === 'function' ? siparisKalemBirim(kalem) : String(kalem.birim || 'MT')).toUpperCase();
    const miktar = birim === 'KG' ? (kg || mt) : (mt || kg);
    if (!(miktar > 0)) return null;
    return { siparisId: sid, kalemIdx: ki, miktar: Math.round(miktar), birim, sno: sip?.sno || '' };
}
try { window.sevkiyatKumasPayloadSiparisKalemCoz = sevkiyatKumasPayloadSiparisKalemCoz; } catch (e) {}

/**
 * Kumaş metraj çıkışı → sipariş durum Yükleme (KD sevk_edilen) — eski konfeksiyon sevk gibi birikir.
 * payloads: kumas_stok ÇIKIŞ satırları (mt/kg + lot/SIP/siparis_id).
 */
async function sevkiyatKumasCikisSiparisYuklemeIsle(payloads, opts = {}) {
    const list = Array.isArray(payloads) ? payloads : (payloads ? [payloads] : []);
    if (!list.length || typeof konfSevkToplamYaz !== 'function') return { ok: 0, skip: list.length };
    const byKey = new Map();
    list.forEach((p) => {
        const tip = String(p?.islem_turu || '').toUpperCase().replace(/İ/g, 'I').replace(/Ç/g, 'C').replace(/Ş/g, 'S');
        if (tip && !tip.includes('CIKIS')) return;
        const coz = sevkiyatKumasPayloadSiparisKalemCoz(p);
        if (!coz) return;
        const key = `${coz.siparisId}|${coz.kalemIdx}`;
        const cur = byKey.get(key) || { ...coz, miktar: 0 };
        cur.miktar += coz.miktar;
        byKey.set(key, cur);
    });
    let ok = 0;
    for (const item of byKey.values()) {
        try {
            const rowK = (_kdCache[`KD_KONFEKSIYON_${item.siparisId}`] || {})[`kalem_${item.kalemIdx}`] || {};
            const kdN = Math.max(
                parseInt(rowK.sevk_edilen || 0, 10) || 0,
                parseInt(rowK.sevk_adet || 0, 10) || 0,
                (typeof sevkiyatYuklemeCacheOku === 'function' ? sevkiyatYuklemeCacheOku(item.siparisId, item.kalemIdx) : null) || 0
            );
            const hedef = Math.max(0, kdN + item.miktar);
            if (hedef === kdN) continue;
            if (typeof sevkiyatYuklemeCacheYaz === 'function') sevkiyatYuklemeCacheYaz(item.siparisId, item.kalemIdx, hedef);
            /* Çıkan miktar FARK olarak yazılır: toplam taze kaydın üstüne kurulur (önbellekteki
               eski sayı başka cihazın sevkini ezmesin — SP701, 02.10.2026) */
            const yazilan = await konfSevkToplamYaz(item.siparisId, item.kalemIdx, hedef, {
                kaynak: opts.kaynak || 'SEVKIYAT_KUMAS',
                note: opts.note || `Kumaş sevk +${item.miktar} ${item.birim === 'KG' ? 'kg' : 'mt'}`,
                onceki: kdN,
                delta: item.miktar
            });
            if (typeof sevkiyatYuklemeCacheYaz === 'function') sevkiyatYuklemeCacheYaz(item.siparisId, item.kalemIdx, Number.isFinite(yazilan) ? yazilan : hedef);
            ok += 1;
        } catch (e) {
            console.warn('sevkiyatKumasCikisSiparisYuklemeIsle', item, e);
        }
    }
    try {
        if (ok > 0 && typeof sevkiyatRender === 'function' && typeof appMode === 'string' && appMode === 'SEVKIYAT') {
            sevkiyatRender({ keepFocus: true });
        }
    } catch (e) {}
    return { ok, skip: list.length - ok };
}
try { window.sevkiyatKumasCikisSiparisYuklemeIsle = sevkiyatKumasCikisSiparisYuklemeIsle; } catch (e) {}

/** Sevkiyat yükleme — oturum içi anlık mirror (KD gecikse bile Yüklenen hemen görünsün) */
const _sevkiyatYuklemeLocal = Object.create(null);

function sevkiyatYuklemeCacheKey(siparisId, kalemIdx) {
    return `${String(siparisId || '').trim()}|${parseInt(kalemIdx, 10)}`;
}

function sevkiyatYuklemeCacheOku(siparisId, kalemIdx) {
    const v = _sevkiyatYuklemeLocal[sevkiyatYuklemeCacheKey(siparisId, kalemIdx)];
    const n = parseInt(v, 10);
    return Number.isFinite(n) && n >= 0 ? n : null;
}

/** Yerel mirror — Sevkiyat Yüklenen alanı / planlamaIhtiyacSevkAdet buradan da beslenir.
 *  KD önbellek nesnesi YERİNDE DEĞİŞTİRİLMEZ (07.10.2026, SP554): o nesne yazıcıların TABANI
 *  (_kdHamMap: okunduğu hâl). Alanı iyimser değiştirilip tabanı eski kalınca, onu kopyalayıp yazan
 *  (onarma, konfeksiyon kaydı) ortak yazıcının sayaç birleştirmesinde (güncel + (benim − taban))
 *  iyimser farkı "benim değişikliğim" sayıp veritabanına EKLİYORDU; iki pencere/cihaz arasında her
 *  yazma diğerini tetikleyince sevk 290 milyona çıktı, eksiye düştü. Ekran yerel aynayı okur;
 *  KD önbelleği yazma başarılı olunca (sbKdYazildi) zaten yazılan hâle gelir. */
function sevkiyatYuklemeCacheYaz(siparisId, kalemIdx, toplam) {
    const sid = String(siparisId || '').trim();
    const ki = parseInt(kalemIdx, 10);
    const n = Math.max(0, Math.round(Number(toplam) || 0));
    if (!sid || !Number.isFinite(ki) || ki < 0) return n;
    _sevkiyatYuklemeLocal[sevkiyatYuklemeCacheKey(sid, ki)] = n;
    planlamaIhtiyacSatirCacheInvalidate();
    return n;
}
try { window.sevkiyatYuklemeCacheYaz = sevkiyatYuklemeCacheYaz; } catch (e) {}

/** Konfeksiyon sevk + KD + Sevkiyat depo hareketi — sevk ekranıyla aynı kaynak */
function planlamaIhtiyacSevkAdet(siparisId, kalemIdx, rowK) {
    const sid = String(siparisId || '').trim();
    const ki = parseInt(kalemIdx, 10);
    const sip = ((typeof dataCache !== 'undefined' && dataCache.siparisler) || []).find(s => String(s.id) === sid);
    const kalem = ((typeof siparisListeKalemleriArr === 'function')
        ? siparisListeKalemleriArr(sip || {})
        : [])[ki] || {};
    const kumasKalem = typeof siparisKalemKumasMi === 'function'
        ? siparisKalemKumasMi(kalem)
        : ['MT', 'KG', 'M', 'METRE'].includes(String(kalem.birim || '').toUpperCase().replace(/İ/g, 'I'));

    let sevk = Math.max(
        parseInt(rowK?.sevk_edilen || 0, 10) || 0,
        parseInt(rowK?.sevk_adet || 0, 10) || 0
    );
    const loc = sevkiyatYuklemeCacheOku(sid, ki);
    if (loc != null) sevk = Math.max(sevk, loc);
    const kdRow = (_kdCache[`KD_KONFEKSIYON_${sid}`] || {})[`kalem_${ki}`] || {};
    sevk = Math.max(
        sevk,
        parseInt(kdRow.sevk_edilen || 0, 10) || 0,
        parseInt(kdRow.sevk_adet || 0, 10) || 0
    );
    if (!kumasKalem) {
        if (typeof konfManuelSevkKalemOzet === 'function') {
            const o = konfManuelSevkKalemOzet(sid, ki);
            sevk = Math.max(sevk, parseInt(o && o.sevk, 10) || 0);
        } else {
            const rows = (typeof _konfGlobalKumasGelisCache !== 'undefined' && _konfGlobalKumasGelisCache) || [];
            let pipe = 0;
            rows.forEach((r) => {
                if (String(r.siparis_id) !== sid || Number(r.kalem_idx) !== ki) return;
                pipe += parseInt(r.sevk_edilen_adet || 0, 10) || 0;
            });
            sevk = Math.max(sevk, pipe);
        }
        if (typeof sevkiyatSiparisKalemYuklemeFromAkis === 'function') {
            sevk = Math.max(sevk, sevkiyatSiparisKalemYuklemeFromAkis(sid, ki));
        }
    }
    if (typeof sevkiyatSiparisKalemYuklemeFromDepo === 'function') {
        sevk = Math.max(sevk, sevkiyatSiparisKalemYuklemeFromDepo(sid, ki));
    }
    return sevk;
}

/** Sipariş yükleme oranı (0–1): kalem yüklemesi (planlamaIhtiyacSevkAdet) hedefiyle sınırlanır;
 *  tüm kalemler aynı birimdeyse miktar ağırlıklı, karışık birimde kalem oranlarının ortalaması. */
const _siparisYuklemeOraniMemo = { imza: '', harita: new Map() };
function siparisYuklemeOraniImza() {
    const ks = (typeof dataCache !== 'undefined' && dataCache.kumas_stok) || [];
    let enSon = '';
    for (let i = 0; i < ks.length; i++) {
        const t = String(ks[i]?.updated_at || ks[i]?.created_at || '');
        if (t > enSon) enSon = t;
    }
    let kdSon = 0;
    if (typeof _kdCacheAt === 'object' && _kdCacheAt) for (const k in _kdCacheAt) if (_kdCacheAt[k] > kdSon) kdSon = _kdCacheAt[k];
    let akis = 0;
    if (typeof _konfIslemLogCache !== 'undefined' && _konfIslemLogCache) for (const k in _konfIslemLogCache) akis += (_konfIslemLogCache[k] || []).length;
    return `${ks.length}|${enSon}|${kdSon}|${akis}`;
}
function siparisYuklemeOrani(siparis) {
    const sid = String(siparis?.id || '').trim();
    if (!sid) return 0;
    const memo = _siparisYuklemeOraniMemo;
    const imza = siparisYuklemeOraniImza();
    if (imza !== memo.imza) { memo.imza = imza; memo.harita.clear(); }
    const anahtar = `${sid}|${siparis.updated_at || ''}`;
    if (memo.harita.has(anahtar)) return memo.harita.get(anahtar);
    const kd = (_kdCache[`KD_KONFEKSIYON_${sid}`] || {});
    const satir = siparisListeKalemleriArr(siparis).map((k, i) => {
        const hedef = parseFloat(k.miktar) || 0;
        return {
            hedef,
            yuk: Math.min(hedef, planlamaIhtiyacSevkAdet(sid, i, kd[`kalem_${i}`] || {})),
            birim: String(siparisKalemBirim(k) || '').toUpperCase()
        };
    }).filter(x => x.hedef > 0);
    let oran = 0;
    if (satir.length) {
        oran = new Set(satir.map(x => x.birim)).size === 1
            ? satir.reduce((a, x) => a + x.yuk, 0) / satir.reduce((a, x) => a + x.hedef, 0)
            : satir.reduce((a, x) => a + x.yuk / x.hedef, 0) / satir.length;
    }
    oran = Math.max(0, Math.min(1, oran));
    memo.harita.set(anahtar, oran);
    return oran;
}
try { window.siparisYuklemeOrani = siparisYuklemeOrani; } catch (e) {}

/** Açık sipariş için depo + akış yüklemelerini KD_KONFEKSIYON'a geri yaz (özet/durum kalıcı görsün) */
async function sevkiyatSiparisYuklemeKdDepodanOnar(siparisId, opts = {}) {
    const sid = String(siparisId || '').trim();
    if (!sid || typeof sbKdGet !== 'function' || typeof sbKdSet !== 'function') return false;
    /* hazirVeri: cagiran depo hareketlerini ve islem logunu bu tur icinde zaten
       yukledi (siparisDurumVerileriniHazirla). Ayni sorgulari ikinci kez atma. */
    const hazirVeri = !!(opts && opts.hazirVeri);
    if (!hazirVeri) {
        try {
            if (typeof sevkiyatSiparisDepoHareketleriYukle === 'function') {
                await sevkiyatSiparisDepoHareketleriYukle(sid);
            }
        } catch (e) { console.warn('depo yukleme', e); }
        try {
            if (typeof konfLoadIslemLog === 'function') await konfLoadIslemLog(sid);
        } catch (e) {}
    }
    const sip = (dataCache.siparisler || []).find(s => String(s.id) === sid);
    const kalemler = (typeof siparisListeKalemleriArr === 'function')
        ? siparisListeKalemleriArr(sip || {})
        : [];
    if (!kalemler.length) return false;
    /* Mutlak "en büyüğe yükselt" yazıcısı: taban veritabanındaki hâl olmalı. Hesap önce son OKUNAN
       hâlden (iyimser değiştirilmiş önbellek nesnesi değil, ağ yok); yazmaya karar verirse taze okunup
       yeniden hesaplanır — eski tabanla yazılan hedef, birleştirmede fark olarak eklenmesin (SP554). */
    let kd = await kdSonOkunanKopya(sid, 'KD_KONFEKSIYON');
    let sonuc = sevkiyatYuklemeKdOnarHesapla(sid, kalemler, kd);
    let yazildi = false;
    if (sonuc.degisti) {
        kd = kdKopya(await sbKdGet(sid, 'KD_KONFEKSIYON', true));
        sonuc = sevkiyatYuklemeKdOnarHesapla(sid, kalemler, kd);
        if (sonuc.degisti) {
            kd.konf_last_save_ts = new Date().toISOString();
            kd.konf_last_save_tip = 'SEVK_DEPODAN_ONAR';
            const res = await sbKdSet(sid, 'KD_KONFEKSIYON', kd);
            if (res && res.error) return false;   /* yazılmayan değer aynaya da konmaz */
            yazildi = true;
        }
    }
    /* Yerel ayna KD (+ depo/günlük) ile eşitlenir — başka cihaz düşürdüyse eski yüksek değer kalmasın */
    for (let i = 0; i < kalemler.length; i++) {
        const r = kd[`kalem_${i}`] || {};
        if (typeof sevkiyatYuklemeCacheYaz === 'function') {
            sevkiyatYuklemeCacheYaz(sid, i, Math.max(parseInt(r.sevk_edilen || 0, 10) || 0, parseInt(r.sevk_adet || 0, 10) || 0));
        }
    }
    return yazildi;
}
try { window.sevkiyatSiparisYuklemeKdDepodanOnar = sevkiyatSiparisYuklemeKdDepodanOnar; } catch (e) {}

/** Onarma hesabı (kd yerinde güncellenir): kalem sevki = en büyük(KD, depo, günlük). */
function sevkiyatYuklemeKdOnarHesapla(sid, kalemler, kd) {
    let degisti = false;
    let tSevk = 0;
    for (let i = 0; i < kalemler.length; i++) {
        const key = `kalem_${i}`;
        if (!kd[key]) kd[key] = {};
        const depoN = sevkiyatSiparisKalemYuklemeFromDepo(sid, i);
        const akisN = sevkiyatSiparisKalemYuklemeFromAkis(sid, i);
        const kdN = Math.max(parseInt(kd[key].sevk_edilen || 0, 10) || 0, parseInt(kd[key].sevk_adet || 0, 10) || 0);
        const hedef = Math.max(kdN, depoN, akisN);
        if (hedef !== kdN) {
            kd[key].sevk_edilen = hedef;
            kd[key].sevk_adet = hedef;
            degisti = true;
        } else if (hedef > 0 && (kd[key].sevk_edilen == null || kd[key].sevk_edilen === '')) {
            kd[key].sevk_edilen = hedef;
            kd[key].sevk_adet = hedef;
            degisti = true;
        }
        tSevk += Math.max(parseInt(kd[key].sevk_edilen || 0, 10) || 0, parseInt(kd[key].sevk_adet || 0, 10) || 0);
    }
    const panelEski = parseInt(kd.panel_sevk_toplam || 0, 10) || 0;
    if (tSevk > panelEski) {
        kd.panel_sevk_toplam = tSevk;
        degisti = true;
    }
    return { degisti, tSevk };
}

/**
 * Ortak sevk toplamı (mutlak). Sipariş ihtiyaç + konfeksiyon sevk + sipariş detay aynı yere yazar/okur:
 * KD_KONFEKSIYON.kalem_i.sevk_edilen + pipeline sevk_edilen_adet (+ artan fark için KONF_SEVK log).
 * Azaltmada aynı kalemin TÜM pipeline satırları dengelenir (tek satır güncelleyip diğerlerini bırakmaz).
 *
 * Tek yazma UI: menü → Sevkiyat (Yüklenen / Sevk +/-).
 */
const ERP_SEVK_ADET_TEK_KAYNAK = 'SEVKIYAT';

function erpSevkAdetGirisAc(opts = {}) {
    const msg = String(opts.toast || 'Sevk adedi yalnızca Sevkiyat menüsünden girilir.').trim();
    if (typeof erpToast === 'function') erpToast(msg, 'info', 4200);
    if (typeof setAppMode === 'function') {
        try { setAppMode('SEVKIYAT'); } catch (e) { console.warn('erpSevkAdetGirisAc', e); }
    }
}
try { window.erpSevkAdetGirisAc = erpSevkAdetGirisAc; } catch (e) {}

function erpSevkAdetYazmaKapaliMi() {
    return true; /* diğer ekranlardan adet yazmayı kapat — tek kaynak Sevkiyat */
}
try { window.erpSevkAdetYazmaKapaliMi = erpSevkAdetYazmaKapaliMi; } catch (e) {}

function siparisOpKonfSevkSevkiyatAynasiMi(j) {
    const p = String((j && (j.pipeline || j.kaynak)) || '').toUpperCase();
    if (['SEVKIYAT', 'SIPARIS_IHTIYAC', 'SEVKIYAT_KUMAS', 'ORTAK_SEVK', 'SEVKIYAT_MAMUL_TOPLU'].includes(p)) return true;
    const n = String((j && j.note) || '');
    return /SEVK[İI]YAT|Sipariş ihtiyaç/i.test(n);
}
try { window.siparisOpKonfSevkSevkiyatAynasiMi = siparisOpKonfSevkSevkiyatAynasiMi; } catch (e) {}

async function konfSevkToplamYaz(siparisId, kalemIdx, yeniToplam, opts = {}) {
    const sid = String(siparisId || '').trim();
    const ki = parseInt(kalemIdx, 10);
    if (!sid || !Number.isFinite(ki) || ki < 0) throw new Error('Geçersiz sipariş/kalem');
    let hedef = Math.max(0, Math.round(Number(yeniToplam) || 0));
    /* opts.delta: "şu kadar ekle / düş" (depo çıkışı, +ekle girişi). Toplam aşağıda okunan
       kaydın üstüne kurulur; önbellekteki eski sayıdan hesaplanan mutlak toplam yazılmaz. */
    const deltaYaz = opts.delta != null && Number.isFinite(Number(opts.delta)) ? Math.round(Number(opts.delta)) : null;
    const user = String(erpCurrentUser?.display_name || erpCurrentUser?.username || 'Sistem').trim() || 'Sistem';
    const note = String(opts.note || '').trim();
    const kaynak = String(opts.kaynak || 'ORTAK_SEVK');
    const kaynakU = kaynak.toUpperCase();
    const sevkiyatAyna = ['SEVKIYAT', 'SIPARIS_IHTIYAC', 'SEVKIYAT_KUMAS', 'ORTAK_SEVK', 'SEVKIYAT_MAMUL_TOPLU'].includes(kaynakU);
    const sip = ((typeof dataCache !== 'undefined' && dataCache.siparisler) || []).find(s => String(s.id) === sid);
    const kalem = ((typeof siparisListeKalemleriArr === 'function')
        ? siparisListeKalemleriArr(sip || {})
        : [])[ki] || {};
    const kumasKalem = typeof siparisKalemKumasMi === 'function'
        ? siparisKalemKumasMi(kalem)
        : ['MT', 'KG', 'M', 'METRE'].includes(String(kalem.birim || '').toUpperCase().replace(/İ/g, 'I'));
    const kalemAdLog = String(kalem.ad || kalem.urun || '').trim();
    const kdOncekiRow = (_kdCache[`KD_KONFEKSIYON_${sid}`] || {})[`kalem_${ki}`] || {};
    const oncekiKayit = opts.onceki != null
        ? Math.max(0, Math.round(Number(opts.onceki) || 0))
        : Math.max(
            parseInt(kdOncekiRow.sevk_edilen || 0, 10) || 0,
            parseInt(kdOncekiRow.sevk_adet || 0, 10) || 0,
            (typeof sevkiyatYuklemeCacheOku === 'function' ? (sevkiyatYuklemeCacheOku(sid, ki) || 0) : 0)
        );

    /* Önce yerel Yüklenen — UI anında toplansın; pipeline/KD hata verse bile ekran doğru kalsın */
    sevkiyatYuklemeCacheYaz(sid, ki, hedef);

    /*
     * Sevkiyat Merkezi / mamül sevk: yalnız yükleme (adet) + SEVK günlüğü.
     * Eksik kesim/kalite için sahte KUMAS_GELIS / kesim backfill YAPILMAZ —
     * o görevler elle girildiğinde görünür.
     */
    if (!sevkiyatAyna && !kumasKalem && typeof konfLoadGlobalKumasGelis === 'function') {
        const has = (_konfGlobalKumasGelisCache || []).some(r => String(r.siparis_id) === sid);
        if (!has) {
            try { await konfLoadGlobalKumasGelis(); } catch (e) {}
        }
    }

    /* Kumaş (mt/kg) kaleme konfeksiyon adet pipeline / KONF_SEVK yazılmaz — karışmasın */
    const pipeRows = (sevkiyatAyna || kumasKalem) ? [] : (_konfGlobalKumasGelisCache || []).filter(r =>
        String(r.siparis_id) === sid && Number(r.kalem_idx) === ki
    );
    let oncekiPipe = 0;
    pipeRows.forEach(r => { oncekiPipe += parseInt(r.sevk_edilen_adet || 0, 10) || 0; });

    let row = pipeRows[0] || null;
    // Manuel / en güncel satırı tercih et
    if (pipeRows.length > 1) {
        row = pipeRows.find(r => r.manuel_sevk || r.not_json?.manuel_sevk) || pipeRows[0];
    }

    try {
        if (sevkiyatAyna || kumasKalem) {
            /* sevkiyat: pipeline/kesim/kalite yok — yalnız KD + SEVK log */
        } else if (!row && hedef > 0 && typeof konfManuelSevkEnsureRow === 'function') {
            row = await konfManuelSevkEnsureRow(sid, ki, Math.max(hedef, 1), note || kaynak);
            if (row && !pipeRows.some(r => String(r.akis_id) === String(row.akis_id))) {
                pipeRows.push(row);
            }
        }

        if (row && typeof konfPipelineKayitGuncelle === 'function') {
            const hazir = Math.max(
                parseInt(row.kalite_gecen_adet || 0, 10) || 0,
                hedef,
                parseInt(row.kesilen_adet || 0, 10) || 0
            );
            const kalan = Math.max(0, hazir - hedef);

            // Ana satıra hedef; aynı kalemin diğer pipeline satırlarında sevk = 0 (çift sayım / düşmeme engeli)
            const rowsToWrite = pipeRows.length ? pipeRows : [row];
            for (const r of rowsToWrite) {
                const buAna = String(r.akis_id) === String(row.akis_id);
                const sevkVal = buAna ? hedef : 0;
                const hazirR = buAna
                    ? hazir
                    : Math.max(parseInt(r.kalite_gecen_adet || 0, 10) || 0, parseInt(r.kesilen_adet || 0, 10) || 0);
                const kalanR = Math.max(0, hazirR - sevkVal);
                await konfPipelineKayitGuncelle(r.akis_id, sid, {
                    sevk_edilen_adet: sevkVal,
                    ...(buAna ? {
                        kalite_gecen_adet: hazir,
                        kalite_bekleyen_adet: Math.max(parseInt(r.kalite_bekleyen_adet || 0, 10) || 0, hazir),
                        kesilen_adet: Math.max(parseInt(r.kesilen_adet || 0, 10) || 0, hazir)
                    } : {}),
                    kalan_adet: kalanR,
                    durum: sevkVal <= 0
                        ? (hazirR > 0 ? 'SEVK_BEKLIYOR' : (r.durum || 'SEVK_BEKLIYOR'))
                        : (kalanR > 0 ? 'SEVK_BEKLIYOR' : 'SEVK_TAMAM'),
                    sevk_ts: new Date().toISOString(),
                    sevk_user: user,
                    manuel_sevk: true
                });
                const cacheRow = (_konfGlobalKumasGelisCache || []).find(x => String(x.akis_id) === String(r.akis_id));
                if (cacheRow) {
                    cacheRow.sevk_edilen_adet = sevkVal;
                    if (buAna) {
                        cacheRow.kalite_gecen_adet = hazir;
                        cacheRow.kalan_adet = kalan;
                        cacheRow.durum = hedef <= 0 ? 'SEVK_BEKLIYOR' : (kalan > 0 ? 'SEVK_BEKLIYOR' : 'SEVK_TAMAM');
                    } else {
                        cacheRow.kalan_adet = kalanR;
                    }
                }
            }

            const oncekiGercek = Math.max(oncekiPipe, Math.max(0, parseInt(opts.onceki, 10) || 0));
            const delta = hedef - oncekiGercek;
            /* Sevkiyat / sipariş ihtiyaç zaten depo "Sevk" satırı yazar — KONF_SEVK kopyası açılmaz */
            if (delta !== 0 && !sevkiyatAyna) {
                await erpAkisEkle({
                    siparis_id: sid,
                    islem: 'KONF_SEVK',
                    kalem_ad: kalemAdLog || row.stok_kodu || row.kumas_cinsi || 'Kumaş',
                    miktar: delta,
                    notlar: JSON.stringify({
                        ts: new Date().toISOString(),
                        user,
                        kalem_idx: ki,
                        kalem_renk: row.not_json?.kalem_renk || row.renk || kalem.renk || '',
                        kalem_ebat: row.not_json?.kalem_ebat || kalem.ebat || '',
                        kalem_key: row.not_json?.kalem_key || '',
                        kumas_gelis_id: row.akis_id,
                        konf_panel: true,
                        pipeline: kaynak,
                        manuel_sevk: true,
                        duzeltme: delta < 0,
                        note: `${kaynak} · sevk toplam ${hedef} (${delta > 0 ? '+' : ''}${delta})${note ? ' · ' + note : ''}`,
                        sevk_adet: delta,
                        toplam_sevk: hedef,
                        kalan_adet: kalan
                    })
                }, 'Sevk kaydı');
            }
        }
    } catch (e) {
        console.warn('konfSevkToplamYaz pipeline (KD yine yazılacak)', e);
    }

    const kd = deltaYaz != null ? await kdSonOkunanKopya(sid, 'KD_KONFEKSIYON') : kdKopya(await sbKdGet(sid, 'KD_KONFEKSIYON', !sevkiyatAyna));
    const key = `kalem_${ki}`;
    if (!kd[key]) kd[key] = {};
    /* Fark ile yazan: toplam = okunan kaydın sevki + fark. Ortak yazıcının sayaç birleştirmesi
       (güncel + (benim − taban)) başka cihazın araya giren artışını da korur.
       SP701, 02.10.2026: önbellekte sevk 0 sanılıp 19.802 mutlak yazıldı, taze kayıttaki 5 m
       "yalnız ben değiştirdim" sayılıp ezildi. */
    if (deltaYaz != null) {
        const tabanSevk = Math.max(parseInt(kd[key].sevk_edilen || 0, 10) || 0, parseInt(kd[key].sevk_adet || 0, 10) || 0);
        hedef = Math.max(0, tabanSevk + deltaYaz);
    }
    kd[key].sevk_edilen = hedef;
    kd[key].sevk_adet = hedef;
    let tSevk = 0;
    Object.keys(kd).forEach((k) => {
        if (!/^kalem_\d+$/.test(k)) return;
        const r = kd[k] || {};
        tSevk += Math.max(parseInt(r.sevk_edilen || 0, 10) || 0, parseInt(r.sevk_adet || 0, 10) || 0);
    });
    kd.panel_sevk_toplam = tSevk;
    kd.konf_last_save_ts = new Date().toISOString();
    kd.konf_last_save_user = user;
    kd.konf_last_save_tip = 'SEVK';
    sevkiyatYuklemeCacheYaz(sid, ki, hedef);
    const res = await sbKdSet(sid, 'KD_KONFEKSIYON', kd);
    if (res && res.error) throw res.error;
    /* Yazılan gerçek toplam (başka cihazın birleşen artışı dahil) — günlük ve ekran bunu göstersin */
    if (deltaYaz != null) hedef = Math.max(parseInt(kd[key]?.sevk_edilen || 0, 10) || 0, parseInt(kd[key]?.sevk_adet || 0, 10) || 0);
    sevkiyatYuklemeCacheYaz(sid, ki, hedef);

    // Senkron sonrası KD yüklemesini koru / düşürmeyi uygula (stale pipe=0 silmesin)
    // Sevkiyat ayna: ağır pipeline senkronu yok — kesim/kalite uydurma + yavaş kayıt engeli
    if (!sevkiyatAyna) {
        try {
            if (typeof konfPipeOzetIndexBuild === 'function') konfPipeOzetIndexBuild();
            _konfGlobalKumasGelisAt = 0;
        } catch (e) {}
        try {
            if (typeof konfPipelineSiparisDurumSenkron === 'function') {
                await konfPipelineSiparisDurumSenkron(sid, {
                    sevkMutlak: true,
                    sevkKalemMutlak: { [ki]: hedef }
                });
            }
        } catch (e) { console.warn('konfSevkToplamYaz sync', e); }

        /* Senkron birleştirmesinden sonra hedefi tekrar yaz — tek kaynak Sevkiyat */
        try {
            const kd2 = kdKopya(await sbKdGet(sid, 'KD_KONFEKSIYON', true));
            if (!kd2[key]) kd2[key] = {};
            kd2[key].sevk_edilen = hedef;
            kd2[key].sevk_adet = hedef;
            let t2 = 0;
            Object.keys(kd2).forEach((k) => {
                if (!/^kalem_\d+$/.test(k)) return;
                const r = kd2[k] || {};
                t2 += Math.max(parseInt(r.sevk_edilen || 0, 10) || 0, parseInt(r.sevk_adet || 0, 10) || 0);
            });
            kd2.panel_sevk_toplam = t2;
            kd2.konf_last_save_ts = new Date().toISOString();
            kd2.konf_last_save_user = user;
            kd2.konf_last_save_tip = 'SEVK';
            await sbKdSet(sid, 'KD_KONFEKSIYON', kd2);
            sevkiyatYuklemeCacheYaz(sid, ki, hedef);
        } catch (e) { console.warn('konfSevkToplamYaz kd final', e); }
    }

    try {
        if (typeof siparisDetayYuklemeYenile === 'function' && !opts.skipDetayYenile && !sevkiyatAyna) {
            await siparisDetayYuklemeYenile(sid);
        }
    } catch (e) { console.warn('konfSevkToplamYaz detay yenile', e); }

    /* Sevkiyat Merkezi: işlem günlüğünde görünsün (depo hareketi gecikse bile) */
    try {
        const deltaLog = deltaYaz != null ? deltaYaz : hedef - oncekiKayit;
        if (sevkiyatAyna && deltaLog !== 0 && typeof sb !== 'undefined' && sb && !opts.skipAkisLog) {
            await erpAkisEkle({
                siparis_id: sid,
                islem: 'SEVK',
                kalem_ad: kalemAdLog || kalem.kod || kalem.ad || '—',
                miktar: Math.abs(deltaLog),
                notlar: JSON.stringify({
                    ts: new Date().toISOString(),
                    user,
                    kalem_idx: ki,
                    kalem_renk: kalem.renk || '',
                    kalem_ebat: kalem.ebat || '',
                    kaynak: kaynakU,
                    sevkiyat_merkezi: true,
                    duzeltme: deltaLog < 0,
                    /* Düşürme kesin: "en büyük toplam" okuyucuları eski toplama geri şişirmesin */
                    kesin_toplam: deltaLog < 0 || undefined,
                    toplam_sevk: hedef,
                    note: `Sevkiyat Merkezi · ${deltaLog > 0 ? '+' : ''}${deltaLog} → yükleme toplam ${hedef}${note ? ' · ' + note : ''}`
                })
            }, 'Sevk kaydı');
            if (!opts.skipAkisReload && typeof konfLoadIslemLog === 'function') {
                try { await konfLoadIslemLog(sid); } catch (e) {}
            }
        }
    } catch (e) { console.warn('konfSevkToplamYaz akis log', e); }

    // Sevkiyat Merkezi: depo hareketi + muhasebe → planlamaIhtiyacSevkToplamYazGuvenli / sevkiyatMamulDepoHareketYaz
    return hedef;
}
try { window.konfSevkToplamYaz = konfSevkToplamYaz; } catch (e) {}

/**
 * Mamül sevkiyat toplu yükleme — sipariş başına 1 KD yazımı + tek akış insert.
 * Satır satır konfSevkToplamYaz yerine kullanılır (dakikalarca süren kayıt engeli).
 * entries: [{ siparisId, kalemIdx, deltaAdet, note? }]
 */
async function konfSevkMamulTopluYukle(entries) {
    const list = Array.isArray(entries) ? entries : [];
    if (!list.length) return 0;
    const user = String(erpCurrentUser?.display_name || erpCurrentUser?.username || 'Sistem').trim() || 'Sistem';
    const kaynakU = 'SEVKIYAT_MAMUL_TOPLU';
    const agg = new Map(); // sid|ki -> { sid, ki, delta, note }

    list.forEach((e) => {
        const sid = String(e?.siparisId || e?.siparis_id || '').trim();
        const ki = parseInt(e?.kalemIdx != null ? e.kalemIdx : e?.kalem_idx, 10);
        const delta = Math.round(Number(e?.deltaAdet != null ? e.deltaAdet : e?.adet) || 0);
        if (!sid || !Number.isFinite(ki) || ki < 0 || !delta) return;
        const key = `${sid}|${ki}`;
        const cur = agg.get(key) || { sid, ki, delta: 0, note: '' };
        cur.delta += delta;
        if (e?.note) cur.note = String(e.note);
        else if (!cur.note) cur.note = `Mamül sevk +${Math.abs(delta)} ad`;
        agg.set(key, cur);
    });
    if (!agg.size) return 0;

    const bySip = new Map();
    agg.forEach((v) => {
        if (!bySip.has(v.sid)) bySip.set(v.sid, []);
        bySip.get(v.sid).push(v);
    });

    const akisRows = [];
    let yukOk = 0;
    const sipIds = [...bySip.keys()];

    const yazBirSiparis = async (sid) => {
        const items = bySip.get(sid) || [];
        const sip = ((typeof dataCache !== 'undefined' && dataCache.siparisler) || []).find(s => String(s.id) === sid);
        const kalemler = (typeof siparisListeKalemleriArr === 'function')
            ? siparisListeKalemleriArr(sip || {})
            : [];
        /* Son okunan hâl (önbellekte okunmuşsa ağ yok; iyimser değiştirilmiş önbellek nesnesi değil) */
        const kd = await kdSonOkunanKopya(sid, 'KD_KONFEKSIYON');
        /* Toplam, okunan kaydın sevki + fark: yerel ayna önbellek (sevkiyatYuklemeCacheOku) KD'den
           büyükse fark iki kez sayılıyordu; ortak yazıcı başka cihazın araya giren artışını korur. */
        const yazilacak = [];
        items.forEach((it) => {
            const key = `kalem_${it.ki}`;
            if (!kd[key]) kd[key] = {};
            const onceki = Math.max(
                parseInt(kd[key].sevk_edilen || 0, 10) || 0,
                parseInt(kd[key].sevk_adet || 0, 10) || 0
            );
            const hedef = Math.max(0, onceki + it.delta);
            if (hedef === onceki) return;
            kd[key].sevk_edilen = hedef;
            kd[key].sevk_adet = hedef;
            sevkiyatYuklemeCacheYaz(sid, it.ki, hedef);
            yazilacak.push(it);
        });
        let tSevk = 0;
        Object.keys(kd).forEach((k) => {
            if (!/^kalem_\d+$/.test(k)) return;
            const r = kd[k] || {};
            tSevk += Math.max(parseInt(r.sevk_edilen || 0, 10) || 0, parseInt(r.sevk_adet || 0, 10) || 0);
        });
        kd.panel_sevk_toplam = tSevk;
        kd.konf_last_save_ts = new Date().toISOString();
        kd.konf_last_save_user = user;
        kd.konf_last_save_tip = 'SEVK';
        const res = await sbKdSet(sid, 'KD_KONFEKSIYON', kd);
        if (res && res.error) throw res.error;
        /* Günlük satırı yazılan gerçek toplamla (başka cihazın birleşen artışı dahil) */
        yazilacak.forEach((it) => {
            const r = kd[`kalem_${it.ki}`] || {};
            const toplam = Math.max(parseInt(r.sevk_edilen || 0, 10) || 0, parseInt(r.sevk_adet || 0, 10) || 0);
            sevkiyatYuklemeCacheYaz(sid, it.ki, toplam);
            const kalem = kalemler[it.ki] || {};
            const kalemAd = String(kalem.ad || kalem.urun || kalem.kod || '—').trim();
            akisRows.push({
                siparis_id: sid,
                islem: 'SEVK',
                kalem_ad: kalemAd,
                miktar: Math.abs(it.delta),
                notlar: JSON.stringify({
                    ts: new Date().toISOString(),
                    user,
                    kalem_idx: it.ki,
                    kalem_renk: kalem.renk || '',
                    kalem_ebat: kalem.ebat || '',
                    kaynak: kaynakU,
                    sevkiyat_merkezi: true,
                    duzeltme: it.delta < 0,
                    kesin_toplam: it.delta < 0 || undefined,
                    toplam_sevk: toplam,
                    note: `Sevkiyat Merkezi · ${it.delta > 0 ? '+' : ''}${it.delta} → yükleme toplam ${toplam}${it.note ? ' · ' + it.note : ''}`
                })
            });
            yukOk += 1;
        });
    };

    /* Farklı siparişleri paralel (en fazla 4) — aynı sipariş tek yazım */
    const CONC = 4;
    for (let i = 0; i < sipIds.length; i += CONC) {
        const chunk = sipIds.slice(i, i + CONC);
        await Promise.all(chunk.map(async (sid) => {
            try { await yazBirSiparis(sid); }
            catch (e) { console.warn('konfSevkMamulTopluYukle', sid, e); }
        }));
    }

    if (akisRows.length && typeof sb !== 'undefined' && sb) {
        try {
            for (let i = 0; i < akisRows.length; i += 40) {
                const chunk = akisRows.slice(i, i + 40);
                const { error } = await sb.from('siparis_akis').insert(chunk);
                if (error) throw error;
            }
        } catch (e) { console.warn('konfSevkMamulTopluYukle akis', e); }
    }

    /* Detay modal açıksa arka planda yenile — kaydı bekletme */
    sipIds.forEach((sid) => {
        if (typeof siparisDetayYuklemeYenile === 'function') {
            Promise.resolve().then(() => siparisDetayYuklemeYenile(sid)).catch(() => {});
        }
    });

    return yukOk;
}
try { window.konfSevkMamulTopluYukle = konfSevkMamulTopluYukle; } catch (e) {}

/** Sipariş ihtiyaç satırından sevk — +adet ekler, -adet düşer; alan sıfırlanır */
const _planlamaIhtiyacSevkTaslak = {};

function planlamaIhtiyacSevkTaslakKey(siparisId, kalemIdx) {
    return `${String(siparisId || '')}_${parseInt(kalemIdx, 10)}`;
}

function planlamaIhtiyacSevkTaslakYaz(siparisId, kalemIdx, val) {
    const k = planlamaIhtiyacSevkTaslakKey(siparisId, kalemIdx);
    if (String(val || '').trim() === '') delete _planlamaIhtiyacSevkTaslak[k];
    else _planlamaIhtiyacSevkTaslak[k] = val;
}
try { window.planlamaIhtiyacSevkTaslakYaz = planlamaIhtiyacSevkTaslakYaz; } catch (e) {}

/** Sevkiyat grid mamül çıkışı: stok_kodu yoksa ürün / sno / kalem yedekleri */
function sevkiyatMamulStokKoduCoz({ kod, urun, sno, kalemIdx }) {
    const k = String(kod || '').trim();
    if (k && k.toUpperCase() !== 'KODSUZ') return k;
    const u = String(urun || '').trim();
    if (u) return u.slice(0, 72);
    const snoS = String(sno || '').trim();
    const ki = Number.isFinite(Number(kalemIdx)) ? Number(kalemIdx) : 0;
    if (snoS) return `SIP-${snoS}-K${ki}`;
    return `KALEM-${ki}`;
}

const _sevkiyatMamulHareketDedup = new Set();

/**
 * Sevkiyat Merkezi adet grid → kumas_stok mamül hareketi + muhasebe fişi.
 * delta > 0: ÇIKIŞ; delta < 0: GİRİŞ (düzeltme). Aynı SEVK_GRID etiketi tekrar yazılmaz.
 */
async function sevkiyatMamulDepoHareketYaz(siparisId, kalemIdx, deltaAdet, opts = {}) {
    const sid = String(siparisId || '').trim();
    const ki = parseInt(kalemIdx, 10);
    const delta = Math.round(Number(deltaAdet) || 0);
    if (!sid || !Number.isFinite(ki) || ki < 0 || !delta) return null;

    const onceki = opts.onceki != null ? Math.round(Number(opts.onceki) || 0) : null;
    const hedef = opts.hedef != null ? Math.round(Number(opts.hedef) || 0) : null;
    const dedupKey = `SG|${sid}|${ki}|${onceki}|${hedef}|${delta}`;
    if (_sevkiyatMamulHareketDedup.has(dedupKey)) return { skipped: true };

    const tag = `[SEVK_GRID:${sid}|${ki}|${onceki}->${hedef}|d${delta}]`;
    if ((dataCache.kumas_stok || []).some(r => String(r.notlar || '').includes(tag))) {
        _sevkiyatMamulHareketDedup.add(dedupKey);
        return { skipped: true };
    }

    const sip = (dataCache.siparisler || []).find(s => String(s.id) === sid) || null;
    const kalemler = (typeof siparisListeKalemleriArr === 'function')
        ? siparisListeKalemleriArr(sip || {})
        : [];
    const k = kalemler[ki] || {};
    const urun = String(k.ad || k.kod || opts.urun || `Kalem ${ki + 1}`).trim() || `Kalem ${ki + 1}`;
    const kodHam = String(k.kod || opts.kod || '').trim();
    const sno = String(sip?.sno || opts.sno || '').trim();
    const stokKodu = sevkiyatMamulStokKoduCoz({ kod: kodHam, urun, sno, kalemIdx: ki });
    const firma = String(sip?.firma || sip?.musteri || opts.firma || '').trim().toUpperCase();
    const renk = String((typeof uaKalemRenkGetir === 'function' ? uaKalemRenkGetir(k) : k.renk) || '').trim();
    const ebat = String((typeof uaKalemEbatGetir === 'function' ? uaKalemEbatGetir(k) : (k.ebat || k.olcu)) || '').trim();
    const urunGrup = String(k.grup || k.urun_grubu || k.urun_grup || '').trim();
    const sevkTagTemizle = (v) => String(v || '').replace(/[\[\]]/g, '').trim();
    const isCikis = delta > 0;
    const adet = Math.abs(delta);
    const user = String(erpCurrentUser?.display_name || erpCurrentUser?.username || 'Sistem').trim() || 'Sistem';
    const note = String(opts.note || '').trim();
    const notBody = [
        tag,
        isCikis ? '[SEVK_YER:MUSTERI]' : '',
        sno ? `[LOT_NO:${sno}]` : '',
        urun ? `[SEVK_URUN:${sevkTagTemizle(urun)}]` : '',
        renk ? `[SEVK_RENK:${sevkTagTemizle(renk)}]` : '',
        ebat ? `[SEVK_EBAT:${sevkTagTemizle(ebat)}]` : '',
        urunGrup ? `[SEVK_GRUP:${sevkTagTemizle(urunGrup)}]` : '',
        note,
        `Sevkiyat Merkezi mamül ${isCikis ? 'çıkış' : 'düzeltme giriş'}`
    ].filter(Boolean).join(' ');
    const notlar = (typeof depoNotlarWithBirim === 'function')
        ? depoNotlarWithBirim('AD', notBody)
        : notBody;

    let insertPayload = [{
        stok_kodu: stokKodu,
        urun_adi: urun,
        kumas_cinsi: urun,
        lot_no: sno,
        siparis_id: /^\d+$/.test(sid) ? Number(sid) : sid,
        kalem_idx: ki,
        siparis_sno: sno || null,
        marka: '',
        renk,
        ebat,
        cuval_sayisi: isCikis ? -adet : adet,
        miktar_kg: 0,
        miktar_mt: 0,
        firma: isCikis ? firma : '',
        irsaliye_no: '',
        notlar,
        islem_turu: isCikis ? 'ÇIKIŞ' : 'GİRİŞ',
        kaynak_birim: 'DEPO_HAREKET_MAMUL_DEPO',
        ana_grup: 'MAMUL',
        updated_by: user,
        islem_gecmisi: `✨ ${new Date().toLocaleString('tr-TR')} — [${user}]: Sevkiyat Merkezi mamül ${isCikis ? 'çıkış' : 'giriş'} ${adet} ad`
    }];
    if (!insertPayload[0].ebat) delete insertPayload[0].ebat;
    if (!insertPayload[0].renk) delete insertPayload[0].renk;

    const triedCols = new Set();
    let hareketId = null;
    let error = null;
    while (true) {
        const ins = await sb.from('kumas_stok').insert(insertPayload).select('id');
        error = ins.error || null;
        if (!error) {
            hareketId = ins.data?.[0]?.id || null;
            break;
        }
        const msg = String(error?.message || '');
        const missingCol = (typeof erpSyncParseMissingColumn === 'function' ? erpSyncParseMissingColumn(msg) : null)
            || (msg.match(/Could not find the '([^']+)' column/i) || [])[1];
        if (!missingCol || triedCols.has(missingCol)) break;
        triedCols.add(missingCol);
        insertPayload = insertPayload.map(row => {
            const r = { ...row };
            delete r[missingCol];
            return r;
        });
        if (!insertPayload[0] || !Object.keys(insertPayload[0]).length) break;
    }
    if (error) throw error;

    const row = {
        ...insertPayload[0],
        id: hareketId,
        created_at: new Date().toISOString()
    };
    if (Array.isArray(dataCache.kumas_stok)) dataCache.kumas_stok.unshift(row);
    _sevkiyatMamulHareketDedup.add(dedupKey);

    let fis = null;
    if (isCikis && firma && typeof muhasebeFisMamulCikisKaydet === 'function') {
        try {
            fis = await muhasebeFisMamulCikisKaydet({
                payloads: [row],
                hareketIds: hareketId ? [hareketId] : []
            });
        } catch (e) {
            console.warn('sevkiyatMamulDepoHareketYaz muhasebe', e?.message || e);
        }
    }
    try {
        if (typeof erpSyncTablesBackground === 'function') erpSyncTablesBackground(['kumas_stok']);
    } catch (e) {}
    return { hareketId, fis, payload: row };
}
try { window.sevkiyatMamulDepoHareketYaz = sevkiyatMamulDepoHareketYaz; } catch (e) {}
try { window.sevkiyatMamulStokKoduCoz = sevkiyatMamulStokKoduCoz; } catch (e) {}

async function planlamaIhtiyacSevkToplamYazGuvenli(sid, ki, hedef, note, opts = {}) {
    const n = Math.max(0, Math.round(Number(hedef) || 0));
    const kaynak = (typeof appMode === 'string' && appMode === 'SEVKIYAT') ? 'SEVKIYAT' : 'SIPARIS_IHTIYAC';
    const rowK = (_kdCache[`KD_KONFEKSIYON_${sid}`] || {})[`kalem_${ki}`] || {};
    const onceki = opts.onceki != null
        ? Math.max(0, Math.round(Number(opts.onceki) || 0))
        : planlamaIhtiyacSevkAdet(sid, ki, rowK);
    /* opts.delta: "+ekle / −düş" girişi fark olarak yazılır (taze kaydın üstüne); düzeltme
       (önceki→hedef) mutlak kalır */
    const yazilan = await konfSevkToplamYaz(sid, ki, n, { kaynak, note: note || 'Sevkiyat', onceki, delta: opts.delta });
    const delta = opts.delta != null && Number.isFinite(Number(opts.delta)) ? Math.round(Number(opts.delta)) : n - onceki;
    if (kaynak === 'SEVKIYAT' && delta !== 0) {
        const sip = (dataCache.siparisler || []).find(s => String(s.id) === String(sid));
        const kalemler = (typeof siparisListeKalemleriArr === 'function')
            ? siparisListeKalemleriArr(sip || {})
            : [];
        const kalem = kalemler[ki] || {};
        const kumasKalem = typeof siparisKalemKumasMi === 'function'
            ? siparisKalemKumasMi(kalem)
            : ['MT', 'KG', 'M', 'METRE'].includes(String(kalem.birim || '').toUpperCase().replace(/İ/g, 'I'));
        if (!kumasKalem) {
            try {
                await sevkiyatMamulDepoHareketYaz(sid, ki, delta, {
                    onceki,
                    hedef: Number.isFinite(yazilan) ? yazilan : n,
                    note: note || 'Sevkiyat'
                });
            } catch (e) {
                console.error('sevkiyatMamulDepoHareketYaz', e);
                if (typeof erpToast === 'function') {
                    erpToast('Sevk adedi kaydedildi; depo/muhasebe hareketi yazılamadı: ' + (e && e.message ? e.message : e), 'warn', 7000);
                }
            }
        }
    }
    return Number.isFinite(yazilan) ? yazilan : n;
}

async function planlamaIhtiyacSevkKaydet(siparisId, kalemIdx, el) {
    if (!planlamaIhtiyacSevkGirisYapabilir()) {
        if (typeof erpToast === 'function') erpToast('Sipariş ihtiyaç / sevk veri girişi yetkiniz yok.', 'error');
        return;
    }
    if (!(typeof sevkiyatAdetGirisAktifMi === 'function' && sevkiyatAdetGirisAktifMi())) {
        if (typeof erpSevkAdetGirisAc === 'function') erpSevkAdetGirisAc({ toast: 'Sevk adedi sadece Sevkiyat ekranından girilebilir.' });
        return;
    }
    const sid = String(siparisId || '').trim();
    const ki = parseInt(kalemIdx, 10);
    if (!sid || !Number.isFinite(ki) || ki < 0) return;
    const tKey = planlamaIhtiyacSevkTaslakKey(sid, ki);
    const raw = el && el.value != null ? String(el.value) : '';
    const trimmed = raw.trim();
    if (trimmed === '') {
        delete _planlamaIhtiyacSevkTaslak[tKey];
        return;
    }
    const eklenen = Math.round(planlamaIhtiyacGirisParseAdet(trimmed));
    if (!Number.isFinite(eklenen) || eklenen === 0) {
        if (typeof erpToast === 'function') erpToast('Geçerli bir adet girin (+ekle / −düş).', 'error');
        return;
    }
    const rowK = (_kdCache[`KD_KONFEKSIYON_${sid}`] || {})[`kalem_${ki}`] || {};
    const onceki = planlamaIhtiyacSevkAdet(sid, ki, rowK);
    const hedef = Math.max(0, onceki + eklenen);
    if (hedef === onceki) {
        if (typeof erpToast === 'function') erpToast(eklenen < 0 ? 'Yüklenen zaten 0 — daha fazla düşülemez.' : 'Değişiklik yok.', 'warn');
        if (el) el.value = '';
        delete _planlamaIhtiyacSevkTaslak[tKey];
        return;
    }
    /* Veri bekçisi (26-veri-bekcisi.js): sipariş / kalite aşımı — sorulur, engellemez */
    if (eklenen > 0 && typeof erpSevkGirisUyarilari === 'function') {
        const veriUyari = await erpSevkGirisUyarilari([{ sid, ki, adet: eklenen }]);
        if (veriUyari.length && !(await erpAskConfirm(`⚠ KONTROL EDİN:\n• ${veriUyari.join('\n• ')}\n\n+${eklenen} yine de eklensin mi?`))) return;
    }
    try {
        if (el) el.disabled = true;
        const isaret = eklenen > 0 ? `+${eklenen}` : String(eklenen);
        const yazilan = await planlamaIhtiyacSevkToplamYazGuvenli(sid, ki, hedef, `Sipariş ihtiyaç ${isaret}`, { onceki, delta: eklenen });
        sevkiyatYuklemeCacheYaz(sid, ki, yazilan);
        delete _planlamaIhtiyacSevkTaslak[tKey];
        if (el) el.value = '';
        if (typeof erpToast === 'function') {
            erpToast(
                eklenen > 0
                    ? `+${eklenen} eklendi — yüklenen: ${yazilan}`
                    : `${isaret} düşüldü — yüklenen: ${yazilan}`,
                'success'
            );
        }
        try { if (typeof konfDurumTabYenile === 'function') await konfDurumTabYenile(sid); } catch (e) {}
        if (appMode === 'SEVKIYAT' && typeof sevkiyatRender === 'function') sevkiyatRender({ keepFocus: true });
    } catch (e) {
        console.error('planlamaIhtiyacSevkKaydet', e);
        if (typeof erpToast === 'function') erpToast('Sevk kaydı hatası: ' + (e && e.message ? e.message : e), 'error');
    } finally {
        if (el) el.disabled = false;
    }
}
try { window.planlamaIhtiyacSevkKaydet = planlamaIhtiyacSevkKaydet; } catch (e) {}

/** Yüklenen toplamını doğrudan düzelt (mutlak değer) */
async function planlamaIhtiyacYuklemeDuzelt(siparisId, kalemIdx, el) {
    if (!planlamaIhtiyacSevkGirisYapabilir()) {
        if (typeof erpToast === 'function') erpToast('Sipariş ihtiyaç / sevk veri girişi yetkiniz yok.', 'error');
        return;
    }
    if (!(typeof sevkiyatAdetGirisAktifMi === 'function' && sevkiyatAdetGirisAktifMi())) {
        if (typeof erpSevkAdetGirisAc === 'function') erpSevkAdetGirisAc({ toast: 'Yüklenen düzeltmesi sadece Sevkiyat ekranından yapılır.' });
        return;
    }
    const sid = String(siparisId || '').trim();
    const ki = parseInt(kalemIdx, 10);
    if (!sid || !Number.isFinite(ki) || ki < 0) return;
    const raw = el && el.value != null ? String(el.value) : '';
    const trimmed = raw.trim();
    let hedef;
    if (trimmed === '') hedef = 0;
    else {
        const n = planlamaIhtiyacGirisParseAdet(trimmed);
        if (!Number.isFinite(n) || n < 0) {
            if (typeof erpToast === 'function') erpToast('Geçerli bir yüklenen adedi girin.', 'error');
            return;
        }
        hedef = Math.round(n);
    }
    const rowK = (_kdCache[`KD_KONFEKSIYON_${sid}`] || {})[`kalem_${ki}`] || {};
    const onceki = planlamaIhtiyacSevkAdet(sid, ki, rowK);
    if (onceki === hedef) {
        if (el) el.value = hedef ? String(hedef) : '0';
        return;
    }
    const fark = hedef - onceki;
    const onayMetin = fark < 0
        ? `Yüklenen ${onceki} → ${hedef} olarak düzeltilecek (${fark}). Onaylıyor musunuz?`
        : `Yüklenen ${onceki} → ${hedef} olarak düzeltilecek (+${fark}). Onaylıyor musunuz?`;
    const onay = typeof erpAskConfirm === 'function'
        ? await erpAskConfirm(onayMetin)
        : confirm(onayMetin);
    if (!onay) {
        if (el) el.value = onceki ? String(onceki) : '0';
        return;
    }
    try {
        if (el) el.disabled = true;
        await planlamaIhtiyacSevkToplamYazGuvenli(sid, ki, hedef, `Sipariş ihtiyaç düzeltme ${onceki}→${hedef}`, { onceki });
        if (el) el.value = String(hedef);
        if (typeof erpToast === 'function') erpToast(`Yüklenen düzeltildi: ${onceki} → ${hedef}`, 'success');
        try { if (typeof konfDurumTabYenile === 'function') await konfDurumTabYenile(sid); } catch (e) {}
        if (appMode === 'SEVKIYAT' && typeof sevkiyatRender === 'function') sevkiyatRender();
    } catch (e) {
        console.error('planlamaIhtiyacYuklemeDuzelt', e);
        if (typeof erpToast === 'function') erpToast('Düzeltme hatası: ' + (e && e.message ? e.message : e), 'error');
        if (el) el.value = onceki ? String(onceki) : '0';
    } finally {
        if (el) el.disabled = false;
    }
}
try { window.planlamaIhtiyacYuklemeDuzelt = planlamaIhtiyacYuklemeDuzelt; } catch (e) {}

function planlamaIhtiyacGirisParseAdet(raw) {
    let s = String(raw == null ? '' : raw).trim();
    if (!s) return null;
    s = s.replace(/\s+/g, '').replace(/−/g, '-');
    if (s.includes(',') && s.includes('.')) s = s.replace(/\./g, '').replace(',', '.');
    else if (s.includes(',')) s = s.replace(',', '.');
    const n = parseFloat(s);
    return Number.isFinite(n) ? n : NaN;
}

function planlamaIhtiyacGirisHucreleri(r, opts) {
    const compact = !!(opts && opts.compact);
    /* Sevk yazma yalnızca Sevkiyat menüsünde (forceSevkGiris) */
    const canSevk = !!(opts && opts.forceSevkGiris) && typeof sevkiyatAdetGirisAktifMi === 'function' && sevkiyatAdetGirisAktifMi();
    const notVal = String(r.not || '');
    const sidJs = pdfEsc(JSON.stringify(String(r.siparisId || '')));
    const ki = parseInt(r.kalemIdx, 10);
    const tKey = planlamaIhtiyacSevkTaslakKey(r.siparisId, ki);
    const sevkTaslak = _planlamaIhtiyacSevkTaslak[tKey] != null ? String(_planlamaIhtiyacSevkTaslak[tKey]) : '';
    const yuklemeN = Math.round(parseFloat(r.yukleme) || 0);
    const pad = compact ? 'padding:3px 6px;' : 'padding:6px 8px;';
    const inpCommon = `class="pro-input" autocomplete="off" onclick="event.stopPropagation()" onmousedown="event.stopPropagation()" onkeydown="if(event.key==='Enter'){event.preventDefault();this.blur()}"`;
    /* Yüklenen = biriken toplam (salt okunur). Giriş yalnızca «Bu sefer +/−» ile yapılır. */
    const yuklemeInp = `<span style="font-family:'DM Mono',monospace;font-weight:800;font-size:12px;color:var(--emerald-c)" title="Biriken yükleme toplamı">${planlamaIhtiyacAdetYazi(yuklemeN)}</span>`;
    const hazirN = Math.max(0, Math.round(parseFloat(r.hazir != null ? r.hazir : r.depoBekleyen) || 0));
    const sevkInp = canSevk
        ? `<input type="text" id="svk-plus-${pdfEsc(String(r.siparisId || ''))}-${ki}" data-svk-sip="${pdfEsc(String(r.siparisId || ''))}" data-svk-ki="${ki}" inputmode="decimal" ${inpCommon} style="width:100%;min-width:0;max-width:72px;box-sizing:border-box;padding:3px 4px;font-size:10px;font-family:'DM Mono',monospace;text-align:right;font-weight:700;color:var(--rose-c);border:1px solid rgba(244,63,94,0.35)"
            value="${pdfEsc(sevkTaslak)}" placeholder="${sevkiyatSatirKumasMi(r) ? (String(r.birim || '').toUpperCase() === 'KG' ? '+kg' : '+mt') : '+ad'}" title="Bu satıra eklenecek (${sevkiyatSatirKumasMi(r) ? 'kumaş mt/kg' : 'ürün adet'}). Depoda hazır: ${hazirN}. Örn: 10 veya -5"
            oninput="planlamaIhtiyacSevkTaslakYaz(${sidJs}, ${ki}, this.value)"
            onblur="planlamaIhtiyacSevkKaydet(${sidJs}, ${ki}, this)">`
        : `<span style="font-family:'DM Mono',monospace;font-weight:700;color:var(--rose-c)">${planlamaIhtiyacAdetYazi(r.sevk)}</span>`;
    const notInp = `<span style="color:${notVal ? 'var(--text2)' : 'var(--text3)'};word-break:break-word">${notVal ? pdfEsc(notVal) : '—'}</span>`;
    return {
        yuklemeTd: `<td style="${pad}text-align:right" onclick="event.stopPropagation()">${yuklemeInp}</td>`,
        sevkTd: `<td style="${pad}text-align:right" onclick="event.stopPropagation()">${sevkInp}</td>`,
        notTd: `<td style="${pad}text-align:left;min-width:${compact ? '100px' : '140px'}" onclick="event.stopPropagation()">${notInp}</td>`
    };
}

let _planlamaIhtiyacSatirCache = { key: '', rows: null, ver: 0 };

function planlamaIhtiyacSatirCacheKey() {
    const aktif = (dataCache.siparisler || []).filter(s => !siparisKapaliMi(s));
    const sipPart = aktif.map(s => `${s.id}:${s.updated_at || s.created_at || ''}`).join('|');
    let kdPart = '';
    aktif.forEach(s => {
        kdPart += `${_kdCacheAt[`KD_KONFEKSIYON_${s.id}`] || 0},${_kdCacheAt[`KD_DOKUMA_${s.id}`] || 0};`;
    });
    const taslak = (typeof _planlamaIhtiyacSevkTaslak === 'object' && _planlamaIhtiyacSevkTaslak)
        ? Object.keys(_planlamaIhtiyacSevkTaslak).join(',')
        : '';
    const loc = (typeof _sevkiyatYuklemeLocal === 'object' && _sevkiyatYuklemeLocal)
        ? Object.keys(_sevkiyatYuklemeLocal).length + ':' + Object.values(_sevkiyatYuklemeLocal).reduce((a, b) => a + (parseInt(b, 10) || 0), 0)
        : '0';
    return `${_planlamaIhtiyacSatirCache.ver}|sevkv3|${sipPart}|${kdPart}|${taslak}|${loc}`;
}

function planlamaIhtiyacSatirlariGetir() {
    const cacheKey = planlamaIhtiyacSatirCacheKey();
    if (_planlamaIhtiyacSatirCache.key === cacheKey && Array.isArray(_planlamaIhtiyacSatirCache.rows)) {
        return _planlamaIhtiyacSatirCache.rows;
    }
    const aktif = (dataCache.siparisler || []).filter(s => !siparisKapaliMi(s));
    const satirlar = [];
    aktif.forEach((s) => {
        // KD kalem_i indeksi sipariş cins dizisiyle aynı olmalı
        const kalemler = siparisListeKalemleriArr(s);
        if (!kalemler.length) return;
        const kdK = _kdCache[`KD_KONFEKSIYON_${s.id}`] || {};
        const kdD = _kdCache[`KD_DOKUMA_${s.id}`] || {};
        const kdP = _kdCache[`KD_PLANLAMA_IHTIYAC_${s.id}`] || {};
        kalemler.forEach((k, i) => {
            const miktar = parseFloat(k.miktar) || 0;
            if (!(miktar > 0)) return;
            const urun = String(k.ad || k.kod || `Kalem ${i + 1}`).trim() || `Kalem ${i + 1}`;
            const kod = String(k.kod || '').trim();
            const rowK = kdK[`kalem_${i}`] || {};
            const rowP = kdP[`kalem_${i}`] || {};
            const uRaw = (kdD.urunler || {});
            const u = (Array.isArray(uRaw) ? uRaw[i] : null)
                || uRaw[i] || uRaw[String(i)] || {};
            const dokOzet = (typeof dokumaUrunIkinciOzet === 'function')
                ? dokumaUrunIkinciOzet(u, k)
                : { ikinci: parseInt(u.toplam_adet, 10) || 0, metre: parseFloat(u.toplam_metre) || 0 };
            const birim = (typeof siparisKalemBirim === 'function' ? siparisKalemBirim(k) : (k.birim || 'ADET')) || 'ADET';
            const birimU = String(birim).toUpperCase().replace(/İ/g, 'I');
            const dokMt = Math.round(parseFloat(dokOzet.metre != null ? dokOzet.metre : u.toplam_metre) || 0);
            const dokKg = Math.round(parseFloat(dokOzet.kg != null ? dokOzet.kg : u.toplam_kg) || 0);
            const dokAd = Math.round(parseFloat(dokOzet.adet != null ? dokOzet.adet : (dokOzet.ikinci != null ? dokOzet.ikinci : u.toplam_adet)) || 0);
            let dok = 0;
            let dokBirim = birimU;
            /* Dokunan = sipariş biriminde brüt üretim (Dokuma Takip) */
            if (birimU === 'MT' || birimU === 'M' || birimU === 'METRE' || birimU === 'METER') {
                dok = dokMt;
                dokBirim = 'MT';
            } else if (birimU === 'KG') {
                dok = dokKg > 0 ? dokKg : Math.round(parseFloat(dokOzet.ikinci) || 0);
                dokBirim = 'KG';
            } else {
                dok = dokAd;
                dokBirim = 'ADET';
            }
            const kalite = parseInt(rowK.kk_gecen, 10) || 0;
            const sevkToplam = planlamaIhtiyacSevkAdet(s.id, i, rowK);
            const yukleme = sevkToplam;
            const siparisKalan = Math.max(0, Math.round(miktar - yukleme));
            /* Depoda hazır = dokunan − yüklenen (aynı birim; negatif olmaz) */
            const depoBekleyen = Math.max(0, Math.round(dok - yukleme));
            const planRaw = rowP.plan_adet;
            const planAdet = (planRaw == null || planRaw === '') ? null : (Number.isFinite(Number(planRaw)) ? Number(planRaw) : null);
            satirlar.push({
                siparisId: s.id,
                kalemIdx: i,
                sno: s.sno || '—',
                musteri: String(s.firma || s.musteri || '—').trim() || '—',
                urun,
                kod,
                renk: uaKalemRenkGetir(k) || '—',
                ebat: uaKalemEbatGetir(k) || '—',
                miktar,
                birim,
                dok,
                dokBirim,
                dokMt,
                dokAd,
                kalite,
                yukleme,
                sevk: sevkToplam,
                siparisKalan,
                depoBekleyen,
                hazir: depoBekleyen,
                planAdet,
                not: String(rowP.not || ''),
                grupKey: planlamaIhtiyacNorm(kod || urun)
            });
        });
    });
    _planlamaIhtiyacSatirCache = {
        key: cacheKey,
        rows: satirlar,
        ver: _planlamaIhtiyacSatirCache.ver || 0
    };
    return satirlar;
}

const PLANLAMA_KALEM_SECIM_KEY = 'erp_planlama_kalem_secim_v1';
const PLANLAMA_UA_ASAMA_ISLEM = {
    kesim: 'KESIM', dikim: 'DIKIM', kalite: 'KALITE', koli: 'KOLI', paket: 'KOLI', sevk: 'SEVK', sevkiyat: 'SEVK'
};

function planlamaKalemSecimStoreGet() {
    try { return JSON.parse(localStorage.getItem(PLANLAMA_KALEM_SECIM_KEY) || '{}'); } catch (e) { return {}; }
}
function planlamaKalemSecimStoreSet(siparisId, indices) {
    const d = planlamaKalemSecimStoreGet();
    d[String(siparisId)] = indices;
    try { localStorage.setItem(PLANLAMA_KALEM_SECIM_KEY, JSON.stringify(d)); } catch (e) {}
}

function planlamaIslemAlanMap() {
    return {
        KESIM: { alan: 'kesilen', label: 'Kesim', renk: '#4338ca', bg: 'rgba(99,102,241,0.12)' },
        DIKIM: { alan: 'dikilen', label: 'Dikim', renk: '#be185d', bg: 'rgba(236,72,153,0.12)' },
        KALITE: { alan: 'kk_gecen', label: 'Kalite geçen', renk: '#b45309', bg: 'rgba(245,158,11,0.14)' },
        KOLI: { alan: 'kolide', label: 'Koli', renk: '#047857', bg: 'rgba(16,185,129,0.12)' },
        SEVK: { alan: 'sevk_edilen', label: 'Sevk', renk: '#7c3aed', bg: 'rgba(124,58,237,0.12)' }
    };
}

function planlamaPlanSeciliKalemIndices(siparisId, kalemler) {
    const raw = planlamaKalemSecimStoreGet()[String(siparisId)];
    if (!Array.isArray(raw)) return (kalemler || []).map((_, i) => i);
    const valid = raw.map((n) => parseInt(n, 10)).filter((i) => Number.isFinite(i) && i >= 0 && i < (kalemler || []).length);
    if (valid.length) return [...new Set(valid)].sort((a, b) => a - b);
    return (kalemler || []).map((_, i) => i);
}

function planlamaIslemlerForKalem(kalemIdx, kdUa) {
    const ua = (kdUa || {})[`u_${kalemIdx}`] || {};
    const asamalar = new Set((ua.asamalar || []).map(a => String(a || '').toLowerCase()));
    const sira = Object.keys(planlamaIslemAlanMap());
    if (!asamalar.size) return sira;
    const out = [];
    asamalar.forEach(a => {
        const k = PLANLAMA_UA_ASAMA_ISLEM[a];
        if (k && !out.includes(k)) out.push(k);
    });
    return sira.filter(k => out.includes(k));
}

function renderPlanlamaKalemIslemOzeti(siparisId) {
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    if (!siparis) return '';
    const kalemler = uaSiparisKalemleriGetir(siparis);
    const kd = _kdCache[`KD_KONFEKSIYON_${siparisId}`] || {};
    const kdUa = _kdCache[`KD_URUN_AGACI_${siparisId}`] || {};
    const islemMap = planlamaIslemAlanMap();
    const islemSira = Object.keys(islemMap);
    const seciliIdx = planlamaPlanSeciliKalemIndices(siparisId, kalemler);
    const secimSet = new Set(seciliIdx);
    const sidJs = JSON.stringify(String(siparisId));

    const satirlar = [];
    seciliIdx.forEach((i) => {
        const k = kalemler[i] || {};
        const row = kd[`kalem_${i}`] || {};
        const hedef = parseInt(k.miktar, 10) || 0;
        const renkEbat = [k.renk, k.ebat || k.olcu].filter(Boolean).join(' · ');
        const ad = k.ad || k.kod || `Kalem ${i + 1}`;
        planlamaIslemlerForKalem(i, kdUa).forEach((islemKey) => {
            const meta = islemMap[islemKey];
            if (!meta) return;
            const yapilan = parseInt(row[meta.alan], 10) || 0;
            const pct = hedef > 0 ? Math.min(100, Math.round((yapilan / hedef) * 100)) : (yapilan > 0 ? 100 : 0);
            satirlar.push({
                i, ad, renkEbat, islemKey,
                islemLabel: meta.label, islemRenk: meta.renk, islemBg: meta.bg,
                islemSira: islemSira.indexOf(islemKey),
                hedef, yapilan, pct,
                yapildi: yapilan > 0,
                tamam: hedef > 0 && yapilan >= hedef
            });
        });
    });

    satirlar.sort((a, b) => {
        if (a.yapildi !== b.yapildi) return a.yapildi ? -1 : 1;
        if (a.tamam !== b.tamam) return a.tamam ? -1 : 1;
        if (a.islemSira !== b.islemSira) return a.islemSira - b.islemSira;
        return b.pct - a.pct || a.i - b.i;
    });

    const yapilanSay = satirlar.filter((s) => s.yapildi).length;
    const tamamSay = satirlar.filter((s) => s.tamam).length;

    const kalemListeHtml = (kalemler || []).length ? (kalemler || []).map((k, i) => {
        const checked = secimSet.has(i);
        const ua = kdUa[`u_${i}`] || {};
        const tanimli = ua.asamalar && ua.asamalar.length > 0;
        const renkTxt = uaKalemRenkGetir(k) || '—';
        const ebatTxt = uaKalemEbatGetir(k) || '—';
        return `<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--border);background:${checked ? 'rgba(99,102,241,0.06)' : 'transparent'}">
            <input type="checkbox" ${checked ? 'checked' : ''} onchange="planlamaKalemSecimToggle(${sidJs}, ${i}, this.checked)" style="accent-color:var(--accent2);width:14px;height:14px;flex-shrink:0">
            <div style="flex:1;min-width:0">
                <div style="font-size:11px;font-weight:600;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${pdfEsc(k.ad || k.kod || `Kalem ${i + 1}`)}</div>
                <div style="font-size:9px;color:var(--text3);margin-top:2px">Renk: ${pdfEsc(renkTxt)} · Ebat: ${pdfEsc(ebatTxt)} · <span style="font-family:'DM Mono',monospace">Sipariş: ${(parseInt(k.miktar, 10) || 0).toLocaleString('tr-TR')}</span></div>
            </div>
            <span class="pill ${tanimli ? 'pill-green' : 'pill-gray'}" style="flex-shrink:0;font-size:8px">${tanimli ? '✓ Ağaç' : '—'}</span>
        </div>`;
    }).join('') : '<div style="padding:20px;text-align:center;color:var(--text3);font-size:11px">Bu siparişte kalem yok.</div>';

    const listeHtml = satirlar.length
        ? `<div style="overflow:auto;border:1px solid var(--border);border-radius:10px;max-height:min(50vh,420px)">
            <table class="dt-table" style="width:100%;min-width:720px;border-collapse:collapse;font-size:11px">
                <thead>
                    <tr style="background:var(--surface2);font-size:8px;font-weight:800;color:var(--text3);text-transform:uppercase;font-family:'DM Mono',monospace">
                        <th style="padding:8px 10px;text-align:left">Kalem</th>
                        <th style="padding:8px 10px;text-align:left">İşlem</th>
                        <th style="padding:8px 10px;text-align:right">Sipariş</th>
                        <th style="padding:8px 10px;text-align:right">Yapılan</th>
                        <th style="padding:8px 10px;text-align:right">%</th>
                        <th style="padding:8px 10px;text-align:center">Durum</th>
                    </tr>
                </thead>
                <tbody>
                    ${satirlar.map((s) => {
                        const durum = s.tamam
                            ? '<span class="pill pill-green" style="font-size:8px">Tamam</span>'
                            : s.yapildi
                                ? '<span class="pill pill-amber" style="font-size:8px">Kısmi</span>'
                                : '<span class="pill pill-gray" style="font-size:8px">Yapılmadı</span>';
                        return `<tr style="border-bottom:1px solid var(--border);background:${s.yapildi ? s.islemBg : 'transparent'}">
                            <td style="padding:8px 10px">
                                <div style="font-weight:600;color:var(--text)">${pdfEsc(s.ad)}</div>
                                ${s.renkEbat ? `<div style="font-size:8px;color:var(--accent2);font-family:'DM Mono',monospace;margin-top:2px">${pdfEsc(s.renkEbat)}</div>` : ''}
                            </td>
                            <td style="padding:8px 10px;font-weight:700;color:${s.islemRenk}">${pdfEsc(s.islemLabel)}</td>
                            <td style="padding:8px 10px;text-align:right;font-family:'DM Mono',monospace">${s.hedef > 0 ? s.hedef.toLocaleString('tr-TR') : '—'}</td>
                            <td style="padding:8px 10px;text-align:right;font-family:'DM Mono',monospace;font-weight:700;color:${s.islemRenk}">${s.yapilan > 0 ? s.yapilan.toLocaleString('tr-TR') : '—'}</td>
                            <td style="padding:8px 10px;text-align:right;font-family:'DM Mono',monospace">${s.hedef > 0 ? s.pct + '%' : (s.yapilan > 0 ? '—' : '0%')}</td>
                            <td style="padding:8px 10px;text-align:center">${durum}</td>
                        </tr>`;
                    }).join('')}
                </tbody>
            </table>
        </div>`
        : `<div style="padding:16px;text-align:center;color:var(--text3);font-size:11px">Seçili kalemlerde gösterilecek işlem yok.</div>`;

    return `<div class="panel-box" style="padding:14px 16px;border:1px solid rgba(99,102,241,0.25);background:rgba(99,102,241,0.04)">
        <div style="display:flex;flex-wrap:wrap;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:12px">
            <div>
                <div style="font-size:10px;font-weight:800;color:var(--text);text-transform:uppercase;letter-spacing:0.06em">Kalem & işlem özeti</div>
                <div style="font-size:9px;color:var(--text3);margin-top:4px;line-height:1.45">${pdfEsc(siparis.sno || '—')} · ${pdfEsc(siparis.firma || '—')} — ürün ağacı işlemleri, konfeksiyon gerçekleşen</div>
            </div>
            <button type="button" class="btn-pro btn-ghost-pro" style="padding:4px 10px;font-size:9px" onclick="planlamaSiparisDetayKapat()">Kapat</button>
        </div>
        <div style="display:grid;grid-template-columns:minmax(260px,1fr) minmax(0,2fr);gap:12px;align-items:start">
            <div class="panel-box" style="overflow:hidden;padding:0">
                <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 12px;border-bottom:1px solid var(--border);background:var(--surface2)">
                    <span style="font-size:9px;font-weight:700;color:var(--text2)">Ürün kalemleri (çoktan seçmeli)</span>
                    <div style="display:flex;gap:4px">
                        <button type="button" class="btn-pro btn-ghost-pro" style="padding:3px 8px;font-size:9px" onclick="planlamaKalemSecimHepsi(${sidJs}, true)">Tümü</button>
                        <button type="button" class="btn-pro btn-ghost-pro" style="padding:3px 8px;font-size:9px" onclick="planlamaKalemSecimHepsi(${sidJs}, false)">Temizle</button>
                    </div>
                </div>
                <div style="max-height:min(42vh,360px);overflow:auto">${kalemListeHtml}</div>
            </div>
            <div>
                <div style="display:flex;flex-wrap:wrap;gap:10px;margin-bottom:10px;font-size:10px;font-family:'DM Mono',monospace">
                    <span style="color:var(--text2)">Seçili: <b>${seciliIdx.length}</b> kalem</span>
                    <span style="color:var(--emerald-c)">Tamam: <b>${tamamSay}</b> satır</span>
                    <span style="color:var(--accent2)">Yapılan: <b>${yapilanSay}</b> satır</span>
                </div>
                ${listeHtml}
            </div>
        </div>
    </div>`;
}

function planlamaKalemSecimToggle(siparisId, idx, checked) {
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    const kalemler = uaSiparisKalemleriGetir(siparis);
    const sel = new Set(planlamaPlanSeciliKalemIndices(siparisId, kalemler));
    const i = parseInt(idx, 10);
    if (!Number.isFinite(i) || i < 0) return;
    if (checked) sel.add(i);
    else sel.delete(i);
    planlamaKalemSecimStoreSet(siparisId, [...sel].sort((a, b) => a - b));
    planlamaSiparisDetayRender();
}

function planlamaKalemSecimHepsi(siparisId, hepsi) {
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    const kalemler = uaSiparisKalemleriGetir(siparis);
    planlamaKalemSecimStoreSet(siparisId, hepsi ? kalemler.map((_, i) => i) : []);
    planlamaSiparisDetayRender();
}

function planlamaDetayRowsByKod(kod) {
    const rows = Array.isArray(_planlamaLastRows) ? _planlamaLastRows : [];
    if (!kod) return [];
    const k = String(kod).toUpperCase();
    if (k === 'YIKAMA_BEK') return rows.filter(r => (parseInt(r.yBek, 10) || 0) > 0);
    if (k === 'KESIM_BEK') return rows.filter(r => (parseInt(r.kesBek, 10) || 0) > 0);
    if (k === 'KALITE_BEK') return rows.filter(r => (parseInt(r.kaliteBek, 10) || 0) > 0);
    if (k === 'KOLI_BEK') return rows.filter(r => (parseInt(r.koliBek, 10) || 0) > 0);
    if (k === 'SEVK_HAZIR') return rows.filter(r => (parseInt(r.sevkHazirBek, 10) || 0) > 0);
    if (k === 'DOKUMA_TAMAM') return rows.filter(r => r.dokumaTam);
    return [];
}

function planlamaDetayBaslik(kod) {
    const m = {
        YIKAMA_BEK: 'Yıkamada bekleyen mal',
        KESIM_BEK: 'Kesimde bekleyen mal',
        KALITE_BEK: 'Kalite onayı bekleyen mal',
        KOLI_BEK: 'Koliye giriş bekleyen mal',
        SEVK_HAZIR: 'Sevke hazır bekleyen mal',
        DOKUMA_TAMAM: 'Dokuması tamamlanan ürünler'
    };
    return m[kod] || 'Detay';
}

function planlamaDetayMiktarByKod(r, kod) {
    const k = String(kod).toUpperCase();
    if (k === 'YIKAMA_BEK') return parseInt(r.yBek, 10) || 0;
    if (k === 'KESIM_BEK') return parseInt(r.kesBek, 10) || 0;
    if (k === 'KALITE_BEK') return parseInt(r.kaliteBek, 10) || 0;
    if (k === 'KOLI_BEK') return parseInt(r.koliBek, 10) || 0;
    if (k === 'SEVK_HAZIR') return parseInt(r.sevkHazirBek, 10) || 0;
    if (k === 'DOKUMA_TAMAM') return Math.round(parseFloat(r.dokAdet) || 0);
    return 0;
}

function planlamaDetayRender() {
    const out = document.getElementById('planlama-detay-out');
    if (!out) return;
    if (!_planlamaDetayKod) {
        out.innerHTML = `<div style="font-size:10px;color:var(--text3)">Üstteki bekleyen miktar kutucuklarından birine tıklayarak sipariş / ürün detayını açın.</div>`;
        return;
    }
    const rows = planlamaDetayRowsByKod(_planlamaDetayKod);
    const baslik = planlamaDetayBaslik(_planlamaDetayKod);
    out.innerHTML = `
        <div class="panel-box" style="overflow:hidden">
            <div class="panel-head">
                <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--accent2)"></span>${baslik} · ürün detay</span>
                <button class="btn-pro" style="padding:4px 8px;font-size:9px" onclick="planlamaDetayKapat()">Kapat</button>
            </div>
            <div style="max-height:260px;overflow-y:auto;overflow-x:hidden">
                <table class="dt-table" style="width:100%;table-layout:fixed">
                    <thead><tr><th>Sipariş</th><th>Müşteri</th><th>Ürün</th><th>Alan</th><th style="text-align:right">Miktar</th><th>Termin</th></tr></thead>
                    <tbody>
                        ${rows.map(r => `<tr>
                            <td style="font-family:'DM Mono',monospace">${pdfEsc(r.s?.sno || '—')}</td>
                            <td style="word-break:break-word;line-height:1.3">${pdfEsc(r.s?.firma || '—')}</td>
                            <td style="word-break:break-word;line-height:1.3">${pdfEsc(r.urunEtiket || '—')}</td>
                            <td style="word-break:break-word;line-height:1.3">${pdfEsc(r.alan || '—')}</td>
                            <td style="text-align:right;font-weight:700">${planlamaDetayMiktarByKod(r, _planlamaDetayKod).toLocaleString('tr-TR')}</td>
                            <td>${r.s?.ttarih ? new Date(r.s.ttarih).toLocaleDateString('tr-TR') : '—'}</td>
                        </tr>`).join('') || `<tr><td colspan="6" style="text-align:center;padding:16px;color:var(--text3)">Bu başlıkta bekleyen ürün yok.</td></tr>`}
                    </tbody>
                </table>
            </div>
        </div>`;
}

function planlamaDetayAc(kod) {
    _planlamaDetayKod = String(kod || '');
    planlamaDetayRender();
}

function planlamaDetayKapat() {
    _planlamaDetayKod = '';
    planlamaDetayRender();
}

function planlamaSiparisDetayRender() {
    const out = document.getElementById('planlama-siparis-detay-out');
    if (!out) return;
    const siparisId = String(_planlamaSiparisDetay?.siparisId || '');
    if (!siparisId) {
        out.innerHTML = `<div style="font-size:10px;color:var(--text3);padding:8px 2px">Simteks / Fason / Doğrudan sevk tablosunda bir sipariş satırına tıklayın — kalem seçimi ve işlem özeti burada açılır.</div>`;
        return;
    }
    out.innerHTML = renderPlanlamaKalemIslemOzeti(siparisId);
}

function planlamaSiparisDetayAc(alan, siparisId) {
    _planlamaSiparisDetay = { alan: String(alan || ''), siparisId: String(siparisId || '') };
    planlamaSiparisDetayRender();
    const out = document.getElementById('planlama-siparis-detay-out');
    if (out) out.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function planlamaSiparisDetayKapat() {
    _planlamaSiparisDetay = { alan: '', siparisId: '' };
    planlamaSiparisDetayRender();
}

function planlamaKalemUretimAlani(siparisId, kalemIdx) {
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    const siparisYerKolon = uaNormalizeUretimYeri(siparis?.uretim_yeri || '');
    if (siparisYerKolon) return siparisYerKolon;
    const allUa = _kdCache[`KD_URUN_AGACI_${siparisId}`] || {};
    const uaKalem = allUa[`u_${kalemIdx}`] || {};
    const siparisMeta = allUa.siparis || {};
    const siparisFoy = allUa.siparis_foy || {};
    const kalemYer = uaNormalizeUretimYeri(
        uaKalem?.urun_teknik_genel?.uretim_yeri || uaKalem?.teknik_genel?.uretim_yeri
    );
    const sipYer = uaNormalizeUretimYeri(
        siparisMeta?.urun_teknik_genel?.uretim_yeri || siparisFoy?.teknik_genel?.uretim_yeri
    );
    const yer = kalemYer || sipYer;
    return yer || 'SIMTEKS_KONF';
}

async function renderPlanlama() {
    if (appMode !== 'PLANLAMA') return;
    const list = document.getElementById('main-list');
    if (!list) return;

    if (!list.innerHTML.trim()) {
        list.innerHTML = `<div class="panel-box" style="padding:40px 20px;text-align:center;color:var(--text3)"><div style="font-size:28px;margin-bottom:8px">⏳</div><div style="font-size:13px;font-weight:600">Planlama: ürün bazlı veriler yükleniyor…</div><div style="font-size:10px;margin-top:8px;opacity:.85">Aktif siparişler için dokuma / konfeksiyon özetleri okunuyor.</div></div>`;
    }

    const siparisler = dataCache.siparisler || [];
    const aktifSip = siparisler.filter(s => !siparisKapaliMi(s));
    const aktifSipById = new Map(aktifSip.map(s => [String(s.id), s]));
    const now = new Date();
    const dayKey = (d) => erpYerelGun(d);
    const d0 = new Date(now); d0.setHours(0, 0, 0, 0);
    const haftaBaslangic = new Date(d0); haftaBaslangic.setDate(d0.getDate() - 6);
    const ayBaslangic = new Date(d0); ayBaslangic.setDate(d0.getDate() - 29);

    const inRange = (v, start) => {
        const dt = new Date(v || 0);
        return Number.isFinite(dt.getTime()) && dt >= start && dt <= now;
    };

    let akisRows = [];
    const nowMs = Date.now();
    const sameDay = _planlamaPerfCache.dayKey === dayKey(now);
    const aylikCacheFresh = sameDay && (nowMs - _planlamaPerfCache.aylikTs) < _planlamaPerfCache.ttlMs;
    if (aylikCacheFresh) {
        akisRows = _planlamaPerfCache.aylikRows || [];
    } else {
        try {
            /* Ayda ~1000 satır oluyor (Eylül 2026: 998) — tek istek 1000'de kesilir, sayfalı çek. */
            const { data, error } = await sbTumSatirlar(() => sb.from('siparis_akis')
                .select('id,siparis_id,islem,miktar,created_at')
                .gte('created_at', ayBaslangic.toISOString())
                .order('created_at', { ascending: false })
                .order('id', { ascending: false }));
            if (!error) {
                akisRows = data || [];
                _planlamaPerfCache.aylikRows = akisRows;
                _planlamaPerfCache.aylikTs = nowMs;
                _planlamaPerfCache.dayKey = dayKey(now);
            }
        } catch (e) {}
    }

    const sumRange = (start) => (akisRows || [])
        .filter(r => inRange(r.created_at, start))
        .reduce((a, r) => a + (parseFloat(r.miktar) || 0), 0);
    const gunlukUretim = sumRange(d0);
    const haftalikUretim = sumRange(haftaBaslangic);
    const aylikUretim = sumRange(ayBaslangic);

    /** Bugünkü üretim hareketleri (ürün / sipariş bağlantılı) */
    let akisBugun = [];
    const bugunCacheFresh = sameDay && (nowMs - _planlamaPerfCache.bugunTs) < _planlamaPerfCache.ttlMs;
    if (bugunCacheFresh) {
        akisBugun = _planlamaPerfCache.bugunRows || [];
    } else {
        try {
            const { data, error } = await sbTumSatirlar(() => sb.from('siparis_akis')
                .select('id,siparis_id,islem,miktar,created_at,kalem_ad,notlar')
                .gte('created_at', d0.toISOString())
                .in('islem', ['YIKAMA_SEVK', 'YIKAMA_GELEN', 'KESIM', 'KESİM', 'DİKİM', 'DIKIM', 'KALITE', 'KALİTE', 'KALİTE KONTROL', 'KALITE KONTROL', 'KK_GECEN', 'SEVK', 'KOLI', 'KOLİ', 'PAKET'])
                .order('created_at', { ascending: false })
                .order('id', { ascending: false }));
            if (!error) {
                akisBugun = data || [];
                _planlamaPerfCache.bugunRows = akisBugun;
                _planlamaPerfCache.bugunTs = nowMs;
                _planlamaPerfCache.dayKey = dayKey(now);
            }
        } catch (e) {}
    }

    function bugunSatirlari(islemSetNorm) {
        const agg = new Map();
        for (const r of akisBugun) {
            if (!islemSetNorm.has(planlamaNormIslem(r.islem))) continue;
            const sip = aktifSipById.get(String(r.siparis_id));
            if (!sip) continue;
            const kalemler = siparisListeKalemleriArr(sip);
            const ix = planlamaAkisKalemIndex(kalemler, r);
            const kalem = ix >= 0 ? kalemler[ix] : null;
            const urun = kalem ? String(kalem.ad || kalem.kod || '').trim() || '—' : String(r.kalem_ad || '').trim() || '—';
            const key = `${sip.id}__${urun}`.toLowerCase();
            const once = agg.get(key);
            const miktar = parseFloat(r.miktar) || 0;
            const ts = r.created_at ? new Date(r.created_at).getTime() : 0;
            if (!once) {
                agg.set(key, { sip, urun, miktar, ts, adet: 1 });
            } else {
                once.miktar += miktar;
                once.adet += 1;
                if (ts > once.ts) once.ts = ts;
            }
        }
        return Array.from(agg.values())
            .sort((a, b) => b.ts - a.ts)
            .slice(0, 28)
            .map(x => ({
                sip: x.sip,
                urun: x.urun,
                miktar: x.miktar,
                saat: x.ts ? new Date(x.ts).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }) : '—',
                adet: x.adet
            }));
    }

    const bugunYikSevk = bugunSatirlari(new Set(['YIKAMA_SEVK'].map(planlamaNormIslem)));
    const bugunKesim = bugunSatirlari(new Set(['KESIM', 'KESİM'].map(planlamaNormIslem)));

    /* Eskiden sipariş × KD tipi kadar ayrı sorgu atılıyordu (80 sipariş =
       240 istek). sbKdGetMany 40'lık gruplarla çektiği için istek sayısı
       sipariş sayısından bağımsız kalıyor; MAX_SIP bu yüzden yükseltildi. */
    const MAX_SIP = 400;
    const sipSubset = aktifSip.slice(0, MAX_SIP);
    if (aktifSip.length > MAX_SIP) {
        console.warn(`[Planlama] ${aktifSip.length} aktif siparişin ilk ${MAX_SIP}'ü işlendi.`);
    }
    /* Konfeksiyon Panel kesim/yıkamayı yalnız konf_kesim_yikama'ya yazar; KD kopyası geride
       kalabiliyor (28.09.2026: 20 kalem). Sayılar konfGetKdForSiparis ile birleşik okunur —
       tablo KD çekimiyle paralel yüklenir, TTL'li önbellek. */
    const konfKaynakHazir = Promise.all([
        konfLoadKesimGecmis({ skipRotaDuzelt: true }),
        konfLoadGlobalKumasGelis({ skipUa: true })
    ]).catch(() => {});
    if (typeof sbKdGetMany === 'function') {
        for (const tip of ['KD_KONFEKSIYON', 'KD_DOKUMA', 'KD_URUN_AGACI']) {
            const eksik = sipSubset.filter(s => _kdCache[`${tip}_${s.id}`] === undefined).map(s => s.id);
            if (!eksik.length) continue;
            try { await sbKdGetMany(eksik, tip); } catch (e) { console.warn('planlama KD batch', tip, e); }
        }
    } else {
        for (let i = 0; i < sipSubset.length; i += 8) {
            const chunk = sipSubset.slice(i, i + 8);
            try {
                await Promise.all(chunk.flatMap(s => {
                    const jobs = [];
                    if (_kdCache[`KD_KONFEKSIYON_${s.id}`] === undefined) jobs.push(sbKdGet(s.id, 'KD_KONFEKSIYON'));
                    if (_kdCache[`KD_DOKUMA_${s.id}`] === undefined) jobs.push(sbKdGet(s.id, 'KD_DOKUMA'));
                    if (_kdCache[`KD_URUN_AGACI_${s.id}`] === undefined) jobs.push(sbKdGet(s.id, 'KD_URUN_AGACI'));
                    return jobs;
                }));
            } catch (e) {}
        }
    }
    await konfKaynakHazir;

    const urunSatirlari = [];
    let yikBekUrunTop = 0;
    let dokumaTamamSayisi = 0;
    const bekleyen = { yikama: 0, kesim: 0, kalite: 0, koli: 0, sevk: 0 };
    const hiddenWarnings = planlamaHiddenWarningsGet();
    const globalWarnings = [];
    const MAX_WARNING_COLLECT = 400;
    for (const s of sipSubset) {
        const kalemler = siparisListeKalemleriArr(s);
        if (!kalemler.length) continue;
        const kdK = konfGetKdForSiparis(s.id);
        const kdD = _kdCache[`KD_DOKUMA_${s.id}`] || {};
        const sipAdet = kalemler.reduce((a, k) => a + (parseInt(k.miktar, 10) || 0), 0) || 1;
        const ySevk = parseInt(kdK.panel_yikama_sevk, 10) || 0;
        const yGel = parseInt(kdK.panel_yikama_gelen, 10) || 0;
        const sipSevk = parseInt(kdK.panel_sevk_toplam, 10) || 0;
        const yikKalemde = planlamaYikamaKalemBazliMi(kdK, kalemler.length);
        kalemler.forEach((k, i) => {
            const hedef = parseInt(k.miktar, 10) || 0;
            const rowK = kdK[`kalem_${i}`] || {};
            const u = (kdD.urunler || {})[i] || {};
            const dokOzet = dokumaUrunIkinciOzet(u, k);
            const dokAdet = dokOzet.ikinci;
            const dokM = dokOzet.metre;
            const dokIkinciTip = dokOzet.tip;
            const kes = parseInt(rowK.kesilen, 10) || 0;
            const dik = parseInt(rowK.dikilen, 10) || 0;
            const kk = parseInt(rowK.kk_gecen, 10) || 0;
            const kol = parseInt(rowK.kolide, 10) || 0;
            const pay = sipAdet > 0 ? hedef / sipAdet : 0;
            const sevkPr = Math.round(sipSevk * pay);
            const ySevkPr = yikKalemde ? (parseInt(rowK.yikama_sevk, 10) || 0) : Math.round(ySevk * pay);
            const yGelPr = yikKalemde ? (parseInt(rowK.yikama_gelen, 10) || 0) : Math.round(yGel * pay);
            const yBek = yikKalemde ? Math.max(0, ySevkPr - yGelPr) : Math.max(0, Math.round((ySevk - yGel) * pay));
            yikBekUrunTop += yBek;
            const sevkYuzde = planlamaSevkTamamlanma(hedef, sevkPr);
            const kolaySkor = planlamaKapatmaKolaylikSkoru(hedef, dokAdet, kes, dik, kk, kol, sevkPr);
            const urunEtiket = String(k.ad || k.kod || `Kalem ${i + 1}`).trim() || `Kalem ${i + 1}`;
            const alan = planlamaKalemUretimAlani(s.id, i);
            const kesBek = Math.max(0, Math.round(dokAdet) - kes);
            const kaliteBek = Math.max(0, dik - kk);
            const koliBek = Math.max(0, kk - kol);
            const sevkHazirBek = Math.max(0, kol - sevkPr);
            const dokumaTam = hedef > 0 && Math.round(dokAdet) >= hedef;
            if (dokumaTam) dokumaTamamSayisi += 1;
            bekleyen.yikama += yBek;
            bekleyen.kesim += kesBek;
            bekleyen.kalite += kaliteBek;
            bekleyen.koli += koliBek;
            bekleyen.sevk += sevkHazirBek;
            const warnBase = `${s.id}_${i}`;
            const checks = [
                planlamaPairUyari(warnBase, 'Sipariş', hedef, 'Dokuma', dokAdet),
                planlamaPairUyari(warnBase, 'Dokuma', dokAdet, 'Kesim', kes),
                planlamaPairUyari(warnBase, 'Kesim', kes, 'Yıkama Sevk', ySevkPr),
                planlamaPairUyari(warnBase, 'Yıkama Sevk', ySevkPr, 'Yıkama Gelen', yGelPr),
                planlamaPairUyari(warnBase, 'Yıkama Gelen', yGelPr, 'Kalite', kk),
                planlamaPairUyari(warnBase, 'Kalite', kk, 'Sevk', sevkPr)
            ].filter(Boolean);
            const aktifUyari = checks.filter(w => !hiddenWarnings.has(w.id));
            if (globalWarnings.length < MAX_WARNING_COLLECT) {
                aktifUyari.forEach(w => {
                    if (globalWarnings.length >= MAX_WARNING_COLLECT) return;
                    globalWarnings.push({
                        ...w,
                        siparis: s.sno || '—',
                        musteri: s.firma || '—',
                        urun: urunEtiket
                    });
                });
            }
            urunSatirlari.push({
                s,
                kalemIdx: i,
                urunEtiket,
                alan,
                hedef,
                dokAdet,
                dokM,
                dokIkinciTip,
                kes,
                dik,
                kk,
                kol,
                sevkPr,
                yBek,
                kesBek,
                kaliteBek,
                koliBek,
                sevkHazirBek,
                ySevkPr,
                yGelPr,
                dokumaTam,
                uyarilar: aktifUyari,
                sevkYuzde,
                kolaySkor
            });
        });
    }

    urunSatirlari.sort((a, b) => {
        if (b.kolaySkor !== a.kolaySkor) return b.kolaySkor - a.kolaySkor;
        if (b.sevkYuzde !== a.sevkYuzde) return b.sevkYuzde - a.sevkYuzde;
        const ta = a.s.ttarih ? new Date(a.s.ttarih).getTime() : 0;
        const tb = b.s.ttarih ? new Date(b.s.ttarih).getTime() : 0;
        return ta - tb;
    });

    const fmtMini = (rows, emptyMsg) => {
        if (!rows.length) return `<div style="font-size:11px;color:var(--text3);padding:8px 0">${emptyMsg}</div>`;
        return `<ul style="margin:0;padding:0 0 0 16px;font-size:11px;line-height:1.55;color:var(--text)">
            ${rows.map(o => `<li><b style="font-family:'DM Mono',monospace">${pdfEsc(o.sip.sno || '—')}</b> · ${pdfEsc(o.sip.firma || '—')} · <span style="color:var(--accent2)">${pdfEsc(o.urun)}</span> · ${o.miktar ? o.miktar.toLocaleString('tr-TR') : '—'} ad · ${pdfEsc(o.saat)}${(parseInt(o.adet,10)||0)>1?` · <span style="color:var(--text3)">${o.adet} kayıt birleştirildi</span>`:''}</li>`).join('')}
        </ul>`;
    };

    function planlamaSiparisTopla(rows) {
        const m = new Map();
        rows.forEach(r => {
            const key = String(r.s?.id || '');
            if (!key) return;
            if (!m.has(key)) {
                m.set(key, {
                    s: r.s,
                    alan: r.alan,
                    urunCesit: 0,
                    hedef: 0, dokAdet: 0, kes: 0, yBek: 0, kaliteBek: 0, koliBek: 0, sevkHazirBek: 0, sevkPr: 0, kolaySkorTop: 0, sevkYuzdeTop: 0, uyariTop: 0
                });
            }
            const a = m.get(key);
            a.urunCesit += 1;
            a.hedef += parseInt(r.hedef, 10) || 0;
            a.dokAdet += parseFloat(r.dokAdet) || 0;
            a.kes += parseInt(r.kes, 10) || 0;
            a.yBek += parseInt(r.yBek, 10) || 0;
            a.kaliteBek += parseInt(r.kaliteBek, 10) || 0;
            a.koliBek += parseInt(r.koliBek, 10) || 0;
            a.sevkHazirBek += parseInt(r.sevkHazirBek, 10) || 0;
            a.sevkPr += parseInt(r.sevkPr, 10) || 0;
            a.kolaySkorTop += parseInt(r.kolaySkor, 10) || 0;
            a.sevkYuzdeTop += parseInt(r.sevkYuzde, 10) || 0;
            a.uyariTop += (r.uyarilar || []).length;
        });
        return Array.from(m.values())
            .map(a => ({
                ...a,
                kolaySkor: a.urunCesit ? Math.round(a.kolaySkorTop / a.urunCesit) : 0,
                sevkYuzde: a.urunCesit ? Math.round(a.sevkYuzdeTop / a.urunCesit) : 0
            }))
            .sort((x, y) => y.kolaySkor - x.kolaySkor || y.sevkYuzde - x.sevkYuzde);
    }

    const tabloHtml = (rows, baslik, noktaRenk, panelKey) => {
        const sipRows = planlamaSiparisTopla(rows);
        const acik = planlamaYerPanelAcikMi(panelKey);
        return `
        <div class="panel-box" style="overflow:hidden">
            <div class="panel-head" style="cursor:pointer;user-select:none" onclick="planlamaYerPanelToggle('${panelKey}')" title="${acik ? 'Daralt' : 'Genişlet'}">
                <span class="panel-head-title">
                    <span style="display:inline-block;width:14px;font-size:10px;color:var(--text3);margin-right:4px">${acik ? '▼' : '▶'}</span>
                    <span class="panel-head-dot" style="background:${noktaRenk}"></span>${baslik}
                </span>
                <span style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace">${sipRows.length} sipariş · ${rows.length} kalem</span>
            </div>
            ${acik ? `<div style="max-height:48vh;overflow:auto">
                <table class="dt-table" style="min-width:1160px;width:100%">
                    <thead><tr>
                        <th>Sıra</th><th>Sipariş</th><th>Müşteri</th><th style="text-align:right">Ürün çeşidi</th>
                        <th style="text-align:right">Hedef</th><th style="text-align:right">Dokuma</th><th style="text-align:right">Kesim</th><th style="text-align:right">Yık.bek.</th>
                        <th style="text-align:right">Kalite bek.</th><th style="text-align:right">Koli bek.</th><th style="text-align:right">Sevke hazır</th><th style="text-align:right">Sevk</th>
                        <th style="text-align:right">Sevk %</th><th style="text-align:right">Kolaylık %</th><th>Uyarı</th><th>Termin</th>
                    </tr></thead>
                    <tbody>
                        ${sipRows.map((r, n) => `<tr style="cursor:pointer" onclick='planlamaSiparisDetayAc(${JSON.stringify(r.alan || '')}, ${JSON.stringify(String(r.s?.id || ''))})'>
                            <td style="font-family:'DM Mono',monospace;color:var(--text3)">${n + 1}</td>
                            <td style="font-family:'DM Mono',monospace">${pdfEsc(r.s.sno || '—')}</td>
                            <td>${pdfEsc(r.s.firma || '—')}</td>
                            <td style="text-align:right">${(parseInt(r.urunCesit,10)||0).toLocaleString('tr-TR')}</td>
                            <td style="text-align:right">${r.hedef.toLocaleString('tr-TR')}</td>
                            <td style="text-align:right">${r.dokAdet.toLocaleString('tr-TR')}</td>
                            <td style="text-align:right">${r.kes.toLocaleString('tr-TR')}</td>
                            <td style="text-align:right;color:${r.yBek>0?'var(--amber-c)':'var(--emerald-c)'}">${r.yBek.toLocaleString('tr-TR')}</td>
                            <td style="text-align:right;color:${r.kaliteBek>0?'var(--amber-c)':'var(--emerald-c)'}">${r.kaliteBek.toLocaleString('tr-TR')}</td>
                            <td style="text-align:right;color:${r.koliBek>0?'var(--amber-c)':'var(--emerald-c)'}">${r.koliBek.toLocaleString('tr-TR')}</td>
                            <td style="text-align:right;color:${r.sevkHazirBek>0?'var(--cyan-c)':'var(--text3)'}">${r.sevkHazirBek.toLocaleString('tr-TR')}</td>
                            <td style="text-align:right">${r.sevkPr.toLocaleString('tr-TR')}</td>
                            <td style="text-align:right;font-weight:700;color:var(--cyan-c)">${r.sevkYuzde}%</td>
                            <td style="text-align:right;font-weight:800;color:var(--emerald-c)">${r.kolaySkor}%</td>
                            <td>
                                ${r.uyariTop
                                    ? `<span class="pill pill-red" style="font-size:9px">${r.uyariTop} uyarı</span>`
                                    : `<span class="pill pill-green" style="font-size:9px">OK</span>`}
                            </td>
                            <td>${r.s.ttarih ? new Date(r.s.ttarih).toLocaleDateString('tr-TR') : '—'}</td>
                        </tr>`).join('') || `<tr><td colspan="16" style="text-align:center;padding:20px;color:var(--text3)">Bu alanda aktif sipariş bulunamadı.</td></tr>`}
                    </tbody>
                </table>
            </div>` : `<div style="padding:12px 16px;font-size:10px;color:var(--text3)">Tabloyu görmek için başlığa tıklayın.</div>`}
        </div>`;
    };

    const MAX_ROWS_PER_TABLE = 220;
    const simteksRows = urunSatirlari.filter(r => r.alan === 'SIMTEKS_KONF').slice(0, MAX_ROWS_PER_TABLE);
    const fasonRows = urunSatirlari.filter(r => r.alan === 'FASON_KONF').slice(0, MAX_ROWS_PER_TABLE);
    const dogrudanRows = urunSatirlari.filter(r => r.alan === 'DOGRUDAN_SEVK').slice(0, MAX_ROWS_PER_TABLE);
    _planlamaLastRows = urunSatirlari;

    list.innerHTML = `
    <div style="display:flex;flex-direction:column;gap:12px">
        <div class="panel-box" style="padding:12px 14px">
            <div style="font-size:10px;font-weight:800;color:var(--text2);text-transform:uppercase;letter-spacing:.08em;font-family:'DM Mono',monospace">Planlama · Ürün bazlı</div>
            <div style="margin-top:6px;font-size:11px;color:var(--text3);line-height:1.45">Her satır bir <b>sipariş kalemi</b> (ürün). Dokuma / kesim / yıkama bekleyen / sevk değerleri bu kaleme dağıtılmış veya kaleme özel KD alanlarından gelir. Sıralama: <b>kapatmaya en yakın</b> (kolay) üstte.</div>
            <div style="margin-top:8px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px">
                <div class="panel-box" style="padding:10px"><div style="font-size:9px;color:var(--text3)">Aktif Sipariş</div><div style="font-size:20px;font-weight:700">${aktifSip.length}</div></div>
                <div class="panel-box" style="padding:10px"><div style="font-size:9px;color:var(--text3)">Ürün satırı (kalem)</div><div style="font-size:20px;font-weight:700">${urunSatirlari.length}</div></div>
                <div class="panel-box" style="padding:10px"><div style="font-size:9px;color:var(--text3)">Yık.bek. (ürün dağılımı)</div><div style="font-size:20px;font-weight:700">${yikBekUrunTop.toLocaleString('tr-TR')}</div></div>
            </div>
            <div style="margin-top:8px;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px">
                <div class="panel-box" style="padding:10px;cursor:pointer;transition:box-shadow .15s,border-color .15s" title="Detay için tıklayın" onclick="planlamaDetayAc('DOKUMA_TAMAM')" onmouseenter="this.style.boxShadow='0 2px 10px rgba(0,0,0,.1)'" onmouseleave="this.style.boxShadow='none'"><div style="font-size:9px;color:var(--text3)">Dokuması tamamlanan ürün</div><div style="font-size:18px;font-weight:700;color:var(--accent2)">${dokumaTamamSayisi.toLocaleString('tr-TR')}</div></div>
                <div class="panel-box" style="padding:10px;cursor:pointer;transition:box-shadow .15s,border-color .15s" title="Detay için tıklayın" onclick="planlamaDetayAc('YIKAMA_BEK')" onmouseenter="this.style.boxShadow='0 2px 10px rgba(0,0,0,.1)'" onmouseleave="this.style.boxShadow='none'"><div style="font-size:9px;color:var(--text3)">Yıkamada bekleyen mal</div><div style="font-size:18px;font-weight:700;color:var(--amber-c)">${bekleyen.yikama.toLocaleString('tr-TR')}</div></div>
                <div class="panel-box" style="padding:10px;cursor:pointer;transition:box-shadow .15s,border-color .15s" title="Detay için tıklayın" onclick="planlamaDetayAc('KESIM_BEK')" onmouseenter="this.style.boxShadow='0 2px 10px rgba(0,0,0,.1)'" onmouseleave="this.style.boxShadow='none'"><div style="font-size:9px;color:var(--text3)">Kesimde bekleyen mal</div><div style="font-size:18px;font-weight:700;color:var(--violet-c)">${bekleyen.kesim.toLocaleString('tr-TR')}</div></div>
                <div class="panel-box" style="padding:10px;cursor:pointer;transition:box-shadow .15s,border-color .15s" title="Detay için tıklayın" onclick="planlamaDetayAc('KALITE_BEK')" onmouseenter="this.style.boxShadow='0 2px 10px rgba(0,0,0,.1)'" onmouseleave="this.style.boxShadow='none'"><div style="font-size:9px;color:var(--text3)">Kalite onayı bekleyen</div><div style="font-size:18px;font-weight:700;color:var(--rose-c)">${bekleyen.kalite.toLocaleString('tr-TR')}</div></div>
                <div class="panel-box" style="padding:10px;cursor:pointer;transition:box-shadow .15s,border-color .15s" title="Detay için tıklayın" onclick="planlamaDetayAc('KOLI_BEK')" onmouseenter="this.style.boxShadow='0 2px 10px rgba(0,0,0,.1)'" onmouseleave="this.style.boxShadow='none'"><div style="font-size:9px;color:var(--text3)">Koliye giriş bekleyen</div><div style="font-size:18px;font-weight:700;color:var(--cyan-c)">${bekleyen.koli.toLocaleString('tr-TR')}</div></div>
                <div class="panel-box" style="padding:10px;cursor:pointer;transition:box-shadow .15s,border-color .15s" title="Detay için tıklayın" onclick="planlamaDetayAc('SEVK_HAZIR')" onmouseenter="this.style.boxShadow='0 2px 10px rgba(0,0,0,.1)'" onmouseleave="this.style.boxShadow='none'"><div style="font-size:9px;color:var(--text3)">Sevke hazır bekleyen</div><div style="font-size:18px;font-weight:700;color:var(--emerald-c)">${bekleyen.sevk.toLocaleString('tr-TR')}</div></div>
            </div>
            <div id="planlama-detay-out" style="margin-top:8px"></div>
        </div>

        <div class="panel-box" style="padding:12px 14px">
            <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap">
                <div style="font-size:10px;font-weight:800;color:var(--text2);text-transform:uppercase;letter-spacing:.08em;font-family:'DM Mono',monospace">Akış Uyarıları (Sipariş→Dokuma→Kesim→Yıkama→Kalite→Sevk)</div>
                <button class="btn-pro" style="padding:6px 10px;font-size:10px" onclick="planlamaUyarilariSifirla()">Kapatılan uyarıları geri aç</button>
            </div>
            <div style="margin-top:8px;display:flex;flex-direction:column;gap:7px;max-height:180px;overflow:auto">
                ${globalWarnings.length ? globalWarnings.slice(0, 250).map(w => `
                    <div style="display:flex;gap:10px;align-items:flex-start;justify-content:space-between;border:1px solid rgba(251,113,133,.35);background:rgba(251,113,133,.08);border-radius:10px;padding:8px 10px">
                        <div style="min-width:0">
                            <div style="font-size:10px;font-weight:700;color:var(--rose-c)">${pdfEsc(w.tip)} · ${pdfEsc(w.siparis)} · ${pdfEsc(w.musteri)}</div>
                            <div style="font-size:11px;color:var(--text);line-height:1.45">${pdfEsc(w.urun)} — ${pdfEsc(w.metin)}</div>
                        </div>
                        <button class="btn-pro" style="padding:4px 8px;font-size:9px;white-space:nowrap" onclick="planlamaUyariKapat('${pdfEsc(w.id)}')">Uyarıyı kapat</button>
                    </div>
                `).join('') : `<div style="font-size:11px;color:var(--emerald-c);font-weight:700;padding:6px 2px">Aktif akış uyarısı yok.</div>`}
            </div>
        </div>

        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
            <div class="panel-box" style="padding:12px">
                <div style="font-size:10px;font-weight:800;color:var(--text2);text-transform:uppercase;letter-spacing:.06em;font-family:'DM Mono',monospace;margin-bottom:6px">Bugün yıkamaya sevk (hareket)</div>
                ${fmtMini(bugunYikSevk, 'Bugün kayıtlı yıkama sevk satırı yok veya aktif siparişe bağlı değil.')}
            </div>
            <div class="panel-box" style="padding:12px">
                <div style="font-size:10px;font-weight:800;color:var(--text2);text-transform:uppercase;letter-spacing:.06em;font-family:'DM Mono',monospace;margin-bottom:6px">Bugün kesim (hareket)</div>
                ${fmtMini(bugunKesim, 'Bugün kayıtlı kesim satırı yok veya aktif siparişe bağlı değil.')}
            </div>
        </div>

        <div class="panel-box" style="padding:10px">
            <div style="font-size:10px;font-weight:700;color:var(--text2);margin-bottom:6px">Üretim Girişleri (miktar toplam)</div>
            <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">
                <div><div style="font-size:9px;color:var(--text3)">Günlük</div><div style="font-size:16px;font-weight:700">${gunlukUretim.toLocaleString('tr-TR')}</div></div>
                <div><div style="font-size:9px;color:var(--text3)">Haftalık</div><div style="font-size:16px;font-weight:700">${haftalikUretim.toLocaleString('tr-TR')}</div></div>
                <div><div style="font-size:9px;color:var(--text3)">Aylık</div><div style="font-size:16px;font-weight:700">${aylikUretim.toLocaleString('tr-TR')}</div></div>
            </div>
        </div>

        ${tabloHtml(simteksRows, 'Simteks konfeksiyon', 'var(--cyan-c)', 'SIMTEKS_KONF')}
        ${tabloHtml(fasonRows, 'Fason konfeksiyon', 'var(--amber-c)', 'FASON_KONF')}
        ${tabloHtml(dogrudanRows, 'Doğrudan sevk', 'var(--violet-c)', 'DOGRUDAN_SEVK')}
        <div id="planlama-siparis-detay-out"></div>
    </div>`;
    planlamaDetayRender();
    planlamaSiparisDetayRender();
}

// ════════════════════════════════════════════════════════
//  SEVKİYAT — mamul sevk adedi tek giriş ekranı
// ════════════════════════════════════════════════════════
let _sevkiyatQ = '';
let _sevkiyatYukleBusy = false;
let _sevkiyatYukleToken = 0;
let _sevkiyatHafifTimer = null;
let _sevkiyatHafifSon = 0;
/** @type {'TUMU'|'HAZIR'|'KALAN'|'KUMAS'|'URUN'} */
let _sevkiyatTip = 'TUMU';
let _sevkiyatAraTimer = null;

function sevkiyatFiltreNorm(v) {
    if (typeof planlamaIhtiyacNorm === 'function') return planlamaIhtiyacNorm(v);
    return String(v || '').trim().toLocaleUpperCase('tr-TR');
}

function sevkiyatSatirKumasMi(r) {
    const b = String(r?.birim || 'ADET').toUpperCase().replace(/İ/g, 'I');
    return b === 'MT' || b === 'M' || b === 'METRE' || b === 'METER' || b === 'KG';
}
function sevkiyatSatirMetreMi(r) {
    const b = String(r?.birim || 'ADET').toUpperCase().replace(/İ/g, 'I');
    return b === 'MT' || b === 'M' || b === 'METRE' || b === 'METER';
}

function sevkiyatSatirEslesir(r, qRaw) {
    const qFull = sevkiyatFiltreNorm(qRaw);
    if (!qFull) return true;
    const tokens = qFull.split(/\s+/).filter(Boolean);
    if (!tokens.length) return true;
    const yuk = Math.round(parseFloat(r.yukleme) || 0);
    const sip = Math.round(parseFloat(r.miktar) || 0);
    const dok = Math.round(parseFloat(r.dok) || 0);
    const sipKalan = r.siparisKalan != null
        ? Math.round(parseFloat(r.siparisKalan) || 0)
        : Math.max(0, sip - yuk);
    const hazir = r.hazir != null
        ? Math.round(parseFloat(r.hazir) || 0)
        : (r.depoBekleyen != null
            ? Math.round(parseFloat(r.depoBekleyen) || 0)
            : Math.max(0, dok - yuk));
    const blob = [
        r.urun, r.kod, r.musteri, r.renk, r.ebat, r.sno, r.siparisId, r.birim, r.grupKey,
        r.dokBirim,
        String(sip), String(dok), String(yuk), String(hazir), String(sipKalan),
        hazir > 0 ? 'HAZIR' : '',
        sipKalan > 0 ? 'KALAN' : '',
        sevkiyatSatirKumasMi(r) ? 'KUMAS' : 'URUN MAMUL ADET'
    ].map(sevkiyatFiltreNorm).join(' ');
    return tokens.every((t) => blob.includes(t));
}

function sevkiyatSatirTipEslesir(r, tip) {
    const t = String(tip || 'TUMU').toUpperCase();
    if (t === 'TUMU' || !t) return true;
    const yuk = Math.round(parseFloat(r.yukleme) || 0);
    const sipKalan = r.siparisKalan != null
        ? Math.round(parseFloat(r.siparisKalan) || 0)
        : Math.max(0, Math.round(parseFloat(r.miktar) || 0) - yuk);
    const hazir = r.hazir != null
        ? Math.round(parseFloat(r.hazir) || 0)
        : (r.depoBekleyen != null
            ? Math.round(parseFloat(r.depoBekleyen) || 0)
            : Math.max(0, Math.round(parseFloat(r.dok) || 0) - yuk));
    if (t === 'HAZIR') return hazir > 0;
    if (t === 'KALAN') return sipKalan > 0;
    if (t === 'KUMAS') return sevkiyatSatirKumasMi(r);
    if (t === 'URUN') return !sevkiyatSatirKumasMi(r);
    return true;
}

function sevkiyatFiltreUygula(satirlar) {
    const list = satirlar || [];
    return list.filter((r) => sevkiyatSatirEslesir(r, _sevkiyatQ) && sevkiyatSatirTipEslesir(r, _sevkiyatTip));
}

function sevkiyatAraYaz(val) {
    _sevkiyatQ = String(val || '');
    try {
        const g = document.getElementById('search');
        if (g && appMode === 'SEVKIYAT' && document.activeElement !== g) g.value = _sevkiyatQ;
        ['sevkiyat-ara', 'sevkiyat-ara-tablo'].forEach((id) => {
            const el = document.getElementById(id);
            if (el && document.activeElement !== el) el.value = _sevkiyatQ;
        });
    } catch (e) {}
    if (_sevkiyatAraTimer) clearTimeout(_sevkiyatAraTimer);
    _sevkiyatAraTimer = setTimeout(() => {
        _sevkiyatAraTimer = null;
        if (sevkiyatMerkezGrup === 'DOKUMA_DEPO') {
            try {
                if (typeof dokumaDepoFiltre === 'object' && dokumaDepoFiltre) dokumaDepoFiltre.q = _sevkiyatQ;
                if (typeof dokumaDepoYenileAktifEkran === 'function') {
                    dokumaDepoYenileAktifEkran({ filterOnly: true });
                }
            } catch (e) {}
            return;
        }
        if (typeof sevkiyatRender === 'function') sevkiyatRender({ keepFocus: true });
    }, 140);
}
try { window.sevkiyatAraYaz = sevkiyatAraYaz; } catch (e) {}

function sevkiyatTipSec(tip) {
    const t = String(tip || 'TUMU').toUpperCase();
    _sevkiyatTip = ['TUMU', 'HAZIR', 'KALAN', 'KUMAS', 'URUN'].includes(t) ? t : 'TUMU';
    // Geri uyumluluk
    window._sevkiyatSadeceKalan = (_sevkiyatTip === 'HAZIR' || _sevkiyatTip === 'KALAN');
    if (typeof sevkiyatRender === 'function') sevkiyatRender({ keepFocus: true });
}
try { window.sevkiyatTipSec = sevkiyatTipSec; } catch (e) {}

function sevkiyatSadeceKalanToggle(on) {
    // Eski checkbox API — Hazır filtresine map et
    sevkiyatTipSec(on ? 'HAZIR' : 'TUMU');
}
try { window.sevkiyatSadeceKalanToggle = sevkiyatSadeceKalanToggle; } catch (e) {}

function sevkiyatFiltreSifirla() {
    _sevkiyatQ = '';
    _sevkiyatTip = 'TUMU';
    window._sevkiyatSadeceKalan = false;
    try {
        const g = document.getElementById('search');
        if (g) g.value = '';
        if (typeof dokumaDepoFiltre === 'object' && dokumaDepoFiltre) {
            dokumaDepoFiltre.q = '';
            dokumaDepoFiltre.durum = 'HEPSI';
            dokumaDepoFiltre.siparisId = '';
        }
    } catch (e) {}
    if (sevkiyatMerkezGrup === 'DOKUMA_DEPO' && typeof dokumaDepoYenileAktifEkran === 'function') {
        dokumaDepoYenileAktifEkran({ filterOnly: true });
    }
    if (typeof sevkiyatRender === 'function') sevkiyatRender({ keepFocus: true });
}
try { window.sevkiyatFiltreSifirla = sevkiyatFiltreSifirla; } catch (e) {}

let _sevkiyatSadeceKalan = false;
/** Sevkiyat listesinde tüm satırları göster (varsayılan: ilk 400 — veri kaybolmaz, hepsi aramada) */
let _sevkiyatTumunuGoster = false;
function sevkiyatTumunuGosterToggle(on) {
    _sevkiyatTumunuGoster = on === true || on === '1' || on === 1;
    if (typeof sevkiyatRender === 'function') sevkiyatRender({ keepFocus: true });
}
try { window.sevkiyatTumunuGosterToggle = sevkiyatTumunuGosterToggle; } catch (e) {}

function erpOrphanAramaDropTemizle() {
    try {
        const bulkFocus = document.activeElement?.id?.match(/^(kt|mt)-kod-/);
        const formAktif = typeof sevkiyatFormModalAktifMi === 'function' && sevkiyatFormModalAktifMi();
        document.querySelectorAll('#kumas-toplu-kod-drop, #mamul-toplu-kod-drop').forEach(drop => {
            const inp = drop._anchorInput;
            const inpOk = inp && inp.isConnected && document.contains(inp);
            const acik = drop.classList.contains('is-open') || (drop.style.display && drop.style.display !== 'none');
            if (!acik) return;
            if (!inpOk || (!formAktif && !bulkFocus)) {
                if (typeof dropdownPortalTemizle === 'function') dropdownPortalTemizle(drop);
            }
        });
        document.querySelectorAll('body > #kumas-toplu-kod-drop, body > #mamul-toplu-kod-drop').forEach(drop => {
            const inp = drop._anchorInput;
            const inpOk = inp && inp.isConnected;
            if (!inpOk || !formAktif) {
                if (typeof dropdownPortalTemizle === 'function') dropdownPortalTemizle(drop);
                else try { drop.remove(); } catch (e) {}
            }
        });
    } catch (e) {}
}
try { window.erpOrphanAramaDropTemizle = erpOrphanAramaDropTemizle; } catch (e) {}

/* Sevkiyat Genel Merkezi başlık logosu: kamyon simgesi yerine fotoğraf (kullanıcı, 24.09.2026). 96×96 JPEG, 44×44 kutuda gösterilir. */
const SVK_HERO_LOGO = 'data:image/jpeg;base64,';

/* Telefon: İplik/Kumaş/Mamül sevkiyat formu açıkken alanda tam Sevkiyat Merkezi (arama + kanallar)
   yerine yalnız o grubun son 10 hareketi gösterilir — kullanıcı zaten oradan geldi, aynı ekranı
   ikinci kez görmek istemiyor (25.09.2026: "bir tuşa bastık çıktık, sevkiyat menüsüne basmadıkça
   tekrar görülmesin"). Form kapanınca (sevkiyatMerkezKapat) normal Sevkiyat Merkezi geri gelir. */
function sevkiyatMobilSonHareketlerKaynak(grup) {
    if (grup === 'IPLIK') return (dataCache.iplik_stok || []);
    if (grup === 'MAMUL_DEPO') return (dataCache.kumas_stok || []).filter(r => typeof kumasStokHareketiMamulDepoMu === 'function' && kumasStokHareketiMamulDepoMu(r));
    return (dataCache.kumas_stok || []).filter(r => typeof kumasStokHareketiKumasDepoMu === 'function' && kumasStokHareketiKumasDepoMu(r));
}

function sevkiyatMobilSonHareketlerHtml(grup) {
    const rows = sevkiyatMobilSonHareketlerKaynak(grup)
        .slice()
        .sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')))
        .slice(0, 10);
    const satirlar = rows.map((r) => {
        const giris = /GİR|GIR/i.test(String(r.islem_turu || ''));
        const ad = grup === 'IPLIK'
            ? ([r.iplik_no, r.cins].filter(Boolean).join(' · ') || r.stok_kodu)
            : (r.kumas_cinsi || r.urun_adi || r.stok_kodu);
        const miktarN = grup === 'IPLIK' ? (parseFloat(r.miktar_kg) || 0)
            : grup === 'MAMUL_DEPO' ? (parseInt(r.cuval_sayisi, 10) || 0)
            : (parseFloat(r.miktar_mt) || 0);
        const birim = grup === 'IPLIK' ? 'kg' : grup === 'MAMUL_DEPO' ? 'ad' : 'mt';
        const miktarYazi = Math.abs(miktarN).toLocaleString('tr-TR', { maximumFractionDigits: 1 });
        const tarih = r.created_at ? new Date(r.created_at).toLocaleString('tr-TR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—';
        const notMetni = String(r.notlar || '').replace(/\[[^\]]*\]/g, ' ').replace(/\s+/g, ' ').trim();
        return `<div class="svk-son-hareket-satir">
            <div class="svk-son-hareket-ust">
                <span class="svk-son-hareket-ad">${pdfEsc(ad)}</span>
                <span class="svk-son-hareket-miktar ${giris ? 'is-giris' : 'is-cikis'}">${giris ? '+' : '−'}${miktarYazi} <em>${birim}</em></span>
            </div>
            <div class="svk-son-hareket-alt">${pdfEsc(tarih)} · ${pdfEsc(r.updated_by || 'Sistem')}${notMetni ? ' · ' + pdfEsc(notMetni.slice(0, 60)) : ''}</div>
        </div>`;
    }).join('');
    return `<div class="svk-son-hareket-panel">
        <div class="svk-son-hareket-baslik">Son ${rows.length || 0} hareket</div>
        ${rows.length ? satirlar : `<div class="svk-son-hareket-bos">Bu grupta henüz depo hareketi yok.</div>`}
    </div>`;
}

function sevkiyatRender(opts = {}) {
    try { erpOrphanAramaDropTemizle(); } catch (e) {}
    const out = document.getElementById('sevkiyat-out');
    if (!out || appMode !== 'SEVKIYAT') return;
    if (window.ERP_MOBIL_LITE && typeof sevkiyatDepoFormGrubuMu === 'function' && sevkiyatDepoFormGrubuMu(sevkiyatMerkezGrup)) {
        out.innerHTML = sevkiyatMobilSonHareketlerHtml(sevkiyatMerkezGrup);
        return;
    }
    const keepFocus = !!(opts && opts.keepFocus);
    const prevAe = keepFocus ? document.activeElement : null;
    const prevId = prevAe && prevAe.id ? prevAe.id : null;
    const prevSip = prevAe && prevAe.getAttribute ? prevAe.getAttribute('data-svk-sip') : null;
    const prevKi = prevAe && prevAe.getAttribute ? prevAe.getAttribute('data-svk-ki') : null;
    const prevSel = (prevAe && typeof prevAe.selectionStart === 'number') ? prevAe.selectionStart : null;

    const can = typeof sevkiyatAdetGirisAktifMi === 'function' && sevkiyatAdetGirisAktifMi();
    const satirlar = typeof planlamaIhtiyacSatirlariGetir === 'function' ? planlamaIhtiyacSatirlariGetir() : [];
    let filtered = sevkiyatFiltreUygula(satirlar);
    /** Kumaş = MT/KG; ürün = ADET. Özet kartları aktif siparişlerin tamamından. */
    const sevkiyatOzetFmtMt = (n) => {
        const v = parseFloat(n) || 0;
        if (!(v > 0)) return '';
        return `${v.toLocaleString('tr-TR', { maximumFractionDigits: 1 })} mt kumaş`;
    };
    const sevkiyatOzetFmtAd = (n) => {
        const v = Math.round(parseFloat(n) || 0);
        if (!(v > 0)) return '';
        return `${v.toLocaleString('tr-TR')} adet ürün`;
    };
    const sevkiyatOzetFmtKg = (n) => {
        const v = parseFloat(n) || 0;
        if (!(v > 0)) return '';
        return `${v.toLocaleString('tr-TR', { maximumFractionDigits: 1 })} kg kumaş`;
    };
    const sevkiyatOzetCiftHtml = (mt, adet, kg) => {
        const a = sevkiyatOzetFmtMt(mt);
        const k = sevkiyatOzetFmtKg(kg);
        const b = sevkiyatOzetFmtAd(adet);
        if (!a && !b && !k) {
            return `<div class="svk-ozet-empty">—</div>`;
        }
        return `<div style="display:flex;flex-direction:column;gap:2px">
            ${a ? `<div class="svk-ozet-line">${a}</div>` : ''}
            ${k ? `<div class="svk-ozet-line">${k}</div>` : ''}
            ${b ? `<div class="svk-ozet-line">${b}</div>` : ''}
        </div>`;
    };

    let sipMt = 0, sipAd = 0, sipKg = 0, dokMt = 0, dokAd = 0, dokKg = 0, yukMt = 0, yukAd = 0, yukKg = 0;
    let kalanSipMt = 0, kalanSipAd = 0, kalanSipKg = 0, depoMt = 0, depoAd = 0, depoKg = 0;
    const cesitSet = new Set();
    const ozetKaynak = satirlar;
    for (let i = 0; i < ozetKaynak.length; i++) {
        const r = ozetKaynak[i];
        const yuk = parseFloat(r.yukleme) || 0;
        const sip = parseFloat(r.miktar) || 0;
        const dok = parseFloat(r.dok) || 0;
        const sipKalan = r.siparisKalan != null
            ? Math.max(0, parseFloat(r.siparisKalan) || 0)
            : Math.max(0, sip - yuk);
        const depoBek = r.depoBekleyen != null
            ? Math.max(0, parseFloat(r.depoBekleyen) || 0)
            : Math.max(0, dok - yuk);
        const cesitKey = String(r.grupKey || planlamaIhtiyacNorm(r.kod || r.urun) || '').trim();
        if (cesitKey) cesitSet.add(cesitKey);
        const dokB = String(r.dokBirim || r.birim || 'ADET').toUpperCase().replace(/İ/g, 'I');
        if (sevkiyatSatirKumasMi(r)) {
            if (dokB === 'KG') {
                sipKg += sip; dokKg += dok; yukKg += yuk; kalanSipKg += sipKalan; depoKg += depoBek;
            } else {
                sipMt += sip; dokMt += dok; yukMt += yuk; kalanSipMt += sipKalan; depoMt += depoBek;
            }
        } else {
            sipAd += Math.round(sip);
            dokAd += Math.round(dok);
            yukAd += Math.round(yuk);
            kalanSipAd += Math.round(sipKalan);
            depoAd += Math.round(depoBek);
        }
    }
    const kalemAdedi = ozetKaynak.length;
    const cesitAdedi = cesitSet.size;

    const tipSay = {
        TUMU: satirlar.length,
        HAZIR: satirlar.filter((r) => sevkiyatSatirTipEslesir(r, 'HAZIR')).length,
        KALAN: satirlar.filter((r) => sevkiyatSatirTipEslesir(r, 'KALAN')).length,
        KUMAS: satirlar.filter((r) => sevkiyatSatirTipEslesir(r, 'KUMAS')).length,
        URUN: satirlar.filter((r) => sevkiyatSatirTipEslesir(r, 'URUN')).length
    };
    const tipChip = (id, lbl) => {
        const on = _sevkiyatTip === id;
        const n = tipSay[id] || 0;
        return `<button type="button" class="svk-chip${on ? ' is-on' : ''}" onclick="sevkiyatTipSec('${id}')">${lbl}<em>${n}</em></button>`;
    };
    const filtreAktif = !!String(_sevkiyatQ || '').trim() || _sevkiyatTip !== 'TUMU';

    const rows = filtered.slice().sort((a, b) =>
        String(a.sno).localeCompare(String(b.sno), 'tr', { numeric: true })
        || String(a.urun).localeCompare(String(b.urun), 'tr')
        || String(a.renk).localeCompare(String(b.renk), 'tr')
    );

    /* Büyük listelerde DOM hafif kalsın — “Tümünü göster” ile tamamı açılır (veri silinmez).
       Telefonda her satır karta döner (6-8 satır yükseklik): 400 kart hem çok uzun hem ağır —
       mobilde ilk görünüm 60 satır (kullanıcı 24.09.2026: telefonda kullanılabilirlik). */
    const SVK_ILK = (typeof window !== 'undefined' && window.ERP_MOBIL_LITE) ? 60 : 400;
    const MAX_ROWS = _sevkiyatTumunuGoster ? rows.length : SVK_ILK;
    const truncated = !_sevkiyatTumunuGoster && rows.length > SVK_ILK;
    const shown = truncated ? rows.slice(0, SVK_ILK) : rows;
    const moreNote = truncated
        ? `<div class="svk-more">İlk ${SVK_ILK} / ${rows.length.toLocaleString('tr-TR')} satır.
            <button type="button" class="btn-pro btn-ghost-pro" style="padding:4px 10px;font-size:10px;margin-left:8px;border-radius:8px"
                onclick="sevkiyatTumunuGosterToggle(true)">Tümünü göster</button>
            <span style="opacity:.8"> · veya arama ile daraltın</span></div>`
        : (_sevkiyatTumunuGoster && rows.length > SVK_ILK
            ? `<div class="svk-more">${rows.length.toLocaleString('tr-TR')} satırın tamamı.
                <button type="button" class="btn-pro btn-ghost-pro" style="padding:4px 10px;font-size:10px;margin-left:8px;border-radius:8px"
                    onclick="sevkiyatTumunuGosterToggle(false)">Hızlı görünüm (${SVK_ILK})</button></div>`
            : '');

    const tabloAraHtml = `<div class="svk-table-search">
        <input id="sevkiyat-ara-tablo" type="search" class="pro-input"
            placeholder="Ara…"
            value="${pdfEsc(_sevkiyatQ)}"
            oninput="sevkiyatAraYaz(this.value)"
            onkeydown="if(event.key==='Escape'){event.preventDefault();sevkiyatFiltreSifirla();}"
            autocomplete="off">
        ${String(_sevkiyatQ || '').trim()
            ? `<button type="button" class="svk-table-search__clear" onclick="sevkiyatFiltreSifirla()" title="Aramayı temizle">Temizle</button>`
            : ''}
    </div>`;

    /* Telefonda "Aktif sipariş kalemleri" tablosu hiç gösterilmiyor (kullanıcı, 25.09.2026) —
       satır HTML'i baştan kurulmasın diye boş dizeyle kısa devre. */
    const govde = window.ERP_MOBIL_LITE ? '' : !shown.length
        ? `<div class="svk-table-wrap">
            <div class="svk-table-head">
                <div class="svk-table-head__row">
                    <div class="svk-table-head__title">Aktif sipariş kalemleri</div>
                    <div class="svk-table-head__meta">${satirlar.length ? '0 sonuç' : 'Kalem yok'}${filtreAktif ? ' · filtre aktif' : ''}</div>
                </div>
                ${tabloAraHtml}
            </div>
            <div class="svk-empty">${satirlar.length ? 'Aramaya / filtreye uyan satır yok — kelimeleri değiştirin veya Temizle’ye basın.' : 'Aktif siparişte kalem yok.'}</div>
        </div>`
        : `<div class="svk-table-wrap">
            <div class="svk-table-head">
                <div class="svk-table-head__row">
                    <div class="svk-table-head__title">Aktif sipariş kalemleri</div>
                    <div class="svk-table-head__meta">${shown.length.toLocaleString('tr-TR')} / ${rows.length.toLocaleString('tr-TR')} satır${filtreAktif ? ' · filtre aktif' : ''} · Hazır = Dokunan − Sevk</div>
                </div>
                ${tabloAraHtml}
            </div>
            <div class="svk-table-scroll">
            <table class="svk-table">
                <colgroup>
                    <col style="width:10%">
                    <col style="width:20%">
                    <col style="width:7%">
                    <col style="width:7%">
                    <col style="width:9%">
                    <col style="width:9%">
                    <col style="width:9%">
                    <col style="width:11%">
                    <col style="width:8%">
                    <col style="width:10%">
                </colgroup>
                <thead><tr>
                    <th>Sipariş</th>
                    <th>Ürün</th>
                    <th>Renk</th>
                    <th>Ebat</th>
                    <th style="text-align:right" title="Sipariş miktarı">Sip.</th>
                    <th style="text-align:right;color:var(--cyan-c)" title="Dokunan (Dokuma Takip)">Dok.</th>
                    <th style="text-align:right;color:var(--emerald-c)" title="Yüklenen / sevk edilen">Sevk</th>
                    <th style="text-align:right;color:var(--amber-c)" title="Dokunan − Sevk = depoda hazır">Hazır</th>
                    <th style="text-align:right" title="Sipariş − sevk">Kalan</th>
                    <th style="text-align:right" title="Bu sevkiyatta eklenecek">+</th>
                </tr></thead>
                <tbody>
                    ${shown.map((r) => {
                        const gh = planlamaIhtiyacGirisHucreleri(r, { forceSevkGiris: true, compact: true });
                        const yuk = Math.round(parseFloat(r.yukleme) || 0);
                        const sip = Math.round(parseFloat(r.miktar) || 0);
                        const dok = Math.round(parseFloat(r.dok) || 0);
                        const sipKalan = r.siparisKalan != null ? Math.round(parseFloat(r.siparisKalan) || 0) : Math.max(0, sip - yuk);
                        const hazir = r.hazir != null
                            ? Math.round(parseFloat(r.hazir) || 0)
                            : (r.depoBekleyen != null ? Math.round(parseFloat(r.depoBekleyen) || 0) : Math.max(0, dok - yuk));
                        const birimLbl = sevkiyatSatirMetreMi(r) ? 'mt' : (String(r.birim || '').toUpperCase() === 'KG' ? 'kg' : 'ad');
                        const urunTitle = pdfEsc([r.urun, r.kod].filter(Boolean).join(' · '));
                        const musTitle = pdfEsc(r.musteri);
                        const hazirTitle = pdfEsc(`Dokunan ${dok} − Sevk ${yuk} = Hazır ${hazir} ${birimLbl}`);
                        return `<tr>
                        <td>
                            <div class="svk-cell-sno">${pdfEsc(r.sno)}</div>
                            <div class="svk-cell-mus" title="${musTitle}">${pdfEsc(r.musteri)}</div>
                        </td>
                        <td title="${urunTitle}">
                            <div class="svk-cell-urun">${pdfEsc(r.urun)}</div>
                            ${r.kod ? `<div class="svk-cell-kod">${pdfEsc(r.kod)}</div>` : ''}
                        </td>
                        <td style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${pdfEsc(r.renk)}">${pdfEsc(r.renk)}</td>
                        <td style="font-family:'DM Mono',monospace;font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${pdfEsc(r.ebat)}">${pdfEsc(r.ebat)}</td>
                        <td class="svk-num" style="font-weight:600;font-size:10px">${pdfEsc(planlamaIhtiyacMiktarYazi(r.miktar, r.birim))}</td>
                        <td class="svk-num svk-num--cyan" title="Dokunan">${planlamaIhtiyacAdetYazi(dok)}<span class="u">${birimLbl}</span></td>
                        <td class="svk-num svk-num--emerald">${planlamaIhtiyacAdetYazi(yuk)}<span class="u">${birimLbl}</span></td>
                        <td class="svk-hazir ${hazir > 0 ? 'is-on' : 'is-off'}" title="${hazirTitle}">${planlamaIhtiyacAdetYazi(hazir)}<span class="u">${birimLbl}</span></td>
                        <td class="svk-num ${sipKalan > 0 ? 'svk-num--rose' : 'svk-num--ok'}">${planlamaIhtiyacAdetYazi(sipKalan)}</td>
                        ${gh.sevkTd}
                    </tr>`;
                    }).join('')}
                </tbody>
            </table>
            </div>${moreNote}
        </div>`;

    const aktifMerkez = sevkiyatMerkezGrup || '';
    const chanVariant = { IPLIK: 'iplik', KUMAS: 'kumas', MAMUL_DEPO: 'mamul', DOKUMA_DEPO: 'dokuma' };
    const merkezKart = (grup, ikon, baslik, alt) => {
        const on = aktifMerkez === grup;
        const v = chanVariant[grup] || 'dokuma';
        return `<button type="button" onclick="sevkiyatMerkezAc('${grup}')" class="svk-chan svk-chan--${v}${on ? ' is-on' : ''}">
            <span class="svk-chan__ico">${ikon}</span>
            <span class="svk-chan__name">${baslik}</span>
            <span class="svk-chan__alt">${alt}</span>
        </button>`;
    };
    const dokumaPanel = aktifMerkez === 'DOKUMA_DEPO'
        ? `<div id="sevkiyat-dokuma-depo-panel" style="margin-top:4px"><div class="panel-box" style="padding:24px;text-align:center;color:var(--text3);font-size:11px">Dokuma Depo sevkiyat yükleniyor…</div></div>`
        : '';
    const liveOn = !!(typeof window !== 'undefined' && window._erpLiveStarted);
    const liveBadge = liveOn ? '<div class="svk-live">Canlı senkron</div>' : '';

    out.innerHTML = `
        <div class="svk-root">
            <div class="svk-hero">
                <div class="svk-hero__top">
                    <div class="svk-hero__brand">
                        <div class="svk-hero__icon svk-hero__icon--foto" aria-hidden="true"><img src="${SVK_HERO_LOGO}" alt="" width="44" height="44"></div>
                        <div>
                            <div class="svk-hero__eyebrow">Operasyon · Sevkiyat</div>
                            <div class="svk-hero__title">Sevkiyat Genel Merkezi <span class="svk-hero__sign">kadir'in yeri</span></div>
                            ${liveBadge}
                        </div>
                    </div>
                    <div class="svk-toolbar">
                        <input id="sevkiyat-ara" type="search" class="pro-input" placeholder="Sipariş no, müşteri, ürün, kod, renk…"
                            value="${pdfEsc(_sevkiyatQ)}" oninput="sevkiyatAraYaz(this.value)" autocomplete="off">
                        ${(filtreAktif || window.ERP_MOBIL_LITE) ? `<button type="button" class="btn-pro btn-ghost-pro" style="padding:7px 10px;font-size:10px;border-radius:10px" onclick="sevkiyatFiltreSifirla()">Temizle</button>` : ''}
                    </div>
                </div>
                ${window.ERP_MOBIL_LITE ? '' : `<div class="svk-filtre-bar">
                    <span class="svk-filtre-bar__lbl">Filtre</span>
                    <div class="svk-chips" style="margin-top:0">
                        ${tipChip('TUMU', 'Tümü')}
                        ${tipChip('HAZIR', 'Hazır')}
                        ${tipChip('KALAN', 'Sipariş kalan')}
                        ${tipChip('KUMAS', 'Kumaş')}
                        ${tipChip('URUN', 'Ürün')}
                    </div>
                </div>`}
                ${window.ERP_MOBIL_LITE ? '' : `<div class="svk-metrics">
                    <div class="svk-metric">
                        <div class="svk-metric__lbl">Satır</div>
                        <div class="svk-metric__big">${kalemAdedi.toLocaleString('tr-TR')} <span>kalem</span></div>
                        <div class="svk-metric__sub">${filtreAktif ? (filtered.length.toLocaleString('tr-TR') + ' filtrelenen · ') : ''}${cesitAdedi.toLocaleString('tr-TR')} çeşit mal</div>
                    </div>
                    <div class="svk-metric">
                        <div class="svk-metric__lbl">Sipariş</div>
                        ${sevkiyatOzetCiftHtml(sipMt, sipAd, sipKg)}
                    </div>
                    <div class="svk-metric svk-metric--cyan">
                        <div class="svk-metric__lbl">Dokunan</div>
                        ${sevkiyatOzetCiftHtml(dokMt, dokAd, dokKg)}
                    </div>
                    <div class="svk-metric svk-metric--emerald">
                        <div class="svk-metric__lbl">Sevk edilen</div>
                        ${sevkiyatOzetCiftHtml(yukMt, yukAd, yukKg)}
                    </div>
                    <div class="svk-metric svk-metric--rose">
                        <div class="svk-metric__lbl">Sipariş kalan</div>
                        ${sevkiyatOzetCiftHtml(kalanSipMt, kalanSipAd, kalanSipKg)}
                    </div>
                    <div class="svk-metric svk-metric--amber">
                        <div class="svk-metric__lbl">Depoda hazır</div>
                        <div class="svk-metric__hint">Dokunan − Sevk</div>
                        ${sevkiyatOzetCiftHtml(depoMt, depoAd, depoKg)}
                    </div>
                </div>`}
            </div>

            <div class="svk-channels">
                <div class="svk-channels__head">
                    <div class="svk-channels__title">Sevkiyat kanalları</div>
                    ${aktifMerkez ? `<button type="button" class="btn-pro btn-ghost-pro" style="padding:6px 10px;font-size:10px;border-radius:8px" onclick="sevkiyatMerkezKapat()">Formu kapat</button>` : ''}
                </div>
                <div class="svk-channels__grid">
                    ${merkezKart('IPLIK', '🧶', 'İplik sevkiyat', 'İplik depo çıkışı / sevkiyat')}
                    ${merkezKart('KUMAS', '🏁', 'Kumaş sevkiyat', 'Konfeksiyon, boyahane veya müşteri sevki')}
                    ${merkezKart('MAMUL_DEPO', '🧥', 'Mamül sevkiyat', 'Teslim bilgili mamül çıkışı')}
                    ${merkezKart('DOKUMA_DEPO', '🧵', 'Dokuma Depo sevkiyat', 'Kalem ekle → toplu sevk (hedef + mt/kg)')}
                </div>
            </div>

            ${dokumaPanel}
            ${!can ? `<div class="svk-warn">Sevk girişi için yetkiniz yok.</div>` : ''}
            ${aktifMerkez === 'DOKUMA_DEPO' ? '' : govde}
        </div>`;

    if (aktifMerkez === 'DOKUMA_DEPO' && typeof renderDokumaDepoIcerik === 'function') {
        renderDokumaDepoIcerik({ filterOnly: false, targetId: 'sevkiyat-dokuma-depo-panel', sevkGirisAktif: true, embed: true });
    }

    if (keepFocus) {
        let el = prevId ? document.getElementById(prevId) : null;
        if (!el && prevSip != null && prevKi != null) {
            el = document.querySelector(`[data-svk-sip="${String(prevSip).replace(/"/g, '')}"][data-svk-ki="${String(prevKi).replace(/"/g, '')}"]`);
        }
        if (el && typeof el.focus === 'function') {
            try {
                el.focus();
                if (prevSel != null && el.setSelectionRange) el.setSelectionRange(prevSel, prevSel);
            } catch (e) {}
        }
    }
}
try { window.sevkiyatRender = sevkiyatRender; } catch (e) {}

async function sevkiyatHafifYenile(force = false) {
    if (appMode !== 'SEVKIYAT') return;
    if (!document.getElementById('sevkiyat-out')) {
        await renderSevkiyat(false);
        return;
    }
    if (!force && typeof erpShouldDeferUiRefresh === 'function' && erpShouldDeferUiRefresh()) {
        if (typeof erpScheduleDeferredUiRefresh === 'function') erpScheduleDeferredUiRefresh();
        return;
    }
    const simdi = Date.now();
    if (!force && simdi - _sevkiyatHafifSon < 8000) {
        if (_sevkiyatHafifTimer) return;
        _sevkiyatHafifTimer = setTimeout(() => {
            _sevkiyatHafifTimer = null;
            sevkiyatHafifYenile(true).catch(() => {});
        }, Math.max(400, 8000 - (simdi - _sevkiyatHafifSon)));
        return;
    }
    _sevkiyatHafifSon = simdi;
    sevkiyatRender();
}

async function renderSevkiyat(forceNetwork) {
    if (appMode !== 'SEVKIYAT') return;
    const list = document.getElementById('main-list');
    if (!list) return;

    /* Ekranı anında aç — “Sevkiyat yükleniyor…” beklemesi yok */
    if (!list.querySelector('#sevkiyat-out')) {
        list.innerHTML = `<div id="sevkiyat-out" style="display:flex;flex-direction:column;gap:12px"></div>`;
    }
    if (typeof sevkiyatRender === 'function') sevkiyatRender();

    if (_sevkiyatYukleBusy) {
        /* Zaten arka plan yüklemesi var; token yenile ki eski iş bitsin, yeni tur başlasın */
        ++_sevkiyatYukleToken;
        return;
    }
    _sevkiyatYukleBusy = true;
    const buToken = ++_sevkiyatYukleToken;

    /* Ağ işi arka planda — setAppMode / tıklama burada takılmaz */
    (async () => {
        try {
            const aktif = (dataCache.siparisler || []).filter(s => !siparisKapaliMi(s));
            const forceKd = !!forceNetwork;
            const ttl = forceKd ? 0 : (typeof KD_SOFT_TTL_MS === 'number' ? KD_SOFT_TTL_MS : 90000);
            const eksikKd = aktif.filter(s => {
                const konfStale = typeof kdCacheStaleMi === 'function'
                    ? kdCacheStaleMi(s.id, 'KD_KONFEKSIYON', ttl)
                    : (_kdCache[`KD_KONFEKSIYON_${s.id}`] === undefined);
                const dokStale = typeof kdCacheStaleMi === 'function'
                    ? kdCacheStaleMi(s.id, 'KD_DOKUMA', ttl)
                    : (_kdCache[`KD_DOKUMA_${s.id}`] === undefined);
                return konfStale || dokStale;
            });

            const CHUNK = 40;
            let loadedChunks = 0;
            for (let i = 0; i < eksikKd.length; i += CHUNK) {
                if (appMode !== 'SEVKIYAT' || buToken !== _sevkiyatYukleToken) return;
                const chunk = eksikKd.slice(i, i + CHUNK);
                const konfIds = chunk.filter(s => kdCacheStaleMi(s.id, 'KD_KONFEKSIYON', ttl)).map(s => s.id);
                const dokIds = chunk.filter(s => kdCacheStaleMi(s.id, 'KD_DOKUMA', ttl)).map(s => s.id);
                try {
                    await Promise.all([
                        konfIds.length && typeof sbKdGetMany === 'function'
                            ? sbKdGetMany(konfIds, 'KD_KONFEKSIYON', { force: true })
                            : Promise.all(konfIds.map(id => sbKdGet(id, 'KD_KONFEKSIYON', true).catch(() => null))),
                        dokIds.length && typeof sbKdGetMany === 'function'
                            ? sbKdGetMany(dokIds, 'KD_DOKUMA', { force: true })
                            : Promise.all(dokIds.map(id => sbKdGet(id, 'KD_DOKUMA', true).catch(() => null)))
                    ]);
                } catch (e) {}
                loadedChunks += 1;
                if (appMode === 'SEVKIYAT' && buToken === _sevkiyatYukleToken
                    && (loadedChunks === 1 || loadedChunks % 2 === 0 || i + CHUNK >= eksikKd.length)) {
                    try {
                        if (typeof planlamaIhtiyacSatirCacheInvalidate === 'function') planlamaIhtiyacSatirCacheInvalidate();
                        if (typeof sevkiyatRender === 'function') sevkiyatRender({ keepFocus: true });
                    } catch (e) {}
                }
                if (i + CHUNK < eksikKd.length) await new Promise(r => setTimeout(r, 0));
            }

            if (appMode !== 'SEVKIYAT' || buToken !== _sevkiyatYukleToken) return;

            if (typeof konfLoadGlobalKumasGelis === 'function') {
                try {
                    await konfLoadGlobalKumasGelis({ force: !!forceNetwork, skipUa: true });
                } catch (e) {}
                if (appMode === 'SEVKIYAT' && buToken === _sevkiyatYukleToken) {
                    try {
                        if (typeof planlamaIhtiyacSatirCacheInvalidate === 'function') planlamaIhtiyacSatirCacheInvalidate();
                        if (typeof sevkiyatRender === 'function') sevkiyatRender({ keepFocus: true });
                    } catch (e) {}
                }
            }
        } finally {
            const yeniden = buToken !== _sevkiyatYukleToken;
            _sevkiyatYukleBusy = false;
            if (yeniden && appMode === 'SEVKIYAT') {
                renderSevkiyat(!!forceNetwork).catch(() => {});
            }
        }
    })().catch(() => { _sevkiyatYukleBusy = false; });
}
try { window.renderSevkiyat = renderSevkiyat; } catch (e) {}

