const FASON_SAYI_ALANLARI = Object.entries(FASON_ALAN).filter(([, v]) => v.tip === 'num').map(([k]) => k);
const FASON_HAREKET_ALANLARI = Object.keys(FASON_ALAN);
/* Hareket formunun alanları. Fason ağacında (A|…) kumaş / aksesuar malzeme listesinden seçilir
   (aks_key yerine agac_malzeme), ürün hareketinde hangi kalem (satir_id) seçilir. */
function fasonHareketAlanlari(tip, anahtar) {
    const t = FASON_TIPLER[tip];
    if (!String(anahtar || '').startsWith('A|')) return { alanlar: t.alanlar, zorunlu: t.zorunlu };
    const ekle = (l, alan) => l.includes(alan) ? l : [...l.slice(0, 3), alan, ...l.slice(3)];
    let alanlar = t.alanlar.map(a => a === 'aks_key' ? 'agac_malzeme' : a);
    let zorunlu = t.zorunlu.map(a => a === 'aks_key' ? 'agac_malzeme' : a);
    if (['KUMAS', 'IADE'].includes(tip)) { alanlar = ekle(alanlar, 'agac_malzeme'); zorunlu = [...new Set(['agac_malzeme', ...zorunlu])]; }
    if (['GELEN', 'TAMIR_GELEN', 'URUN', 'TAMIR'].includes(tip)) { alanlar = ekle(alanlar, 'satir_id'); zorunlu = [...new Set(['satir_id', ...zorunlu])]; }
    return { alanlar, zorunlu };
}

let _fasonAkis = { yuklendi: false, yukleniyor: null, hata: null, satirlar: [], surum: 0, zaman: 0 };
let _fasonDurumOnbellek = null;
let _fasonForm = null;
