    if (satirId && !x) { erpToast('Kalem bulunamadı.', 'error'); return; }
    const yeni = !x;
    const id = x ? x.id : fasonId('S');
    const ek = x ? fasonAgacJson(x.ek_malzeme) : {};
    _fasonForm = { tur: 'AGAC_KALEM', sid: String(sid), id, yeni };
    const yeniEbatGoster = !ag.ebatlar.length || !!(x && x.ebatYok);
